var INSPECTION_DATA = {"tables": [{"id": "quality_ch1", "title": "质量篇-第1章-质量管理行为监督要点", "category": "质量篇", "sheets": [{"name": "1.1 建设单位质量管理行为", "items": [{"seq": 1, "point": "施工许可手续办理", "content": "1. 建设单位应在工程开工前依法取得施工许可证；\n2. 施工许可证载明的工程名称、建设规模、合同工期等应与实际情况一致；\n3. 未取得施工许可证不得擅自开工建设；\n4. 施工许可证应按规定在施工现场显著位置公示。", "basis": "《建筑法》第七条\n《建设工程质量管理条例》第十三条\n《建筑工程施工许可管理办法》第二条、第三条"}, {"seq": 2, "point": "质量监督手续办理", "content": "1. 建设单位应在开工前向工程质量监督机构办理质量监督手续；\n2. 提交的报监资料应齐全、真实、有效，包括项目立项批文、规划许可证、施工图审查合格书等；\n3. 质量监督手续办理完成后应取得质量监督注册证书或相关凭证。", "basis": "《建设工程质量管理条例》第十三条\n《房屋建筑和市政基础设施工程质量监督管理规定》第六条"}, {"seq": 3, "point": "施工图设计文件审查", "content": "1. 建设单位应将施工图设计文件报送具备资质的审查机构进行审查；\n2. 施工图审查应在施工前完成，未经审查合格的施工图不得使用；\n3. 涉及重大设计变更的，变更后的施工图应重新审查；\n4. 施工图审查合格书及审查意见应归档保存。", "basis": "《建设工程质量管理条例》第十一条\n《房屋建筑和市政基础设施工程施工图设计文件审查管理办法》第三条、第九条"}, {"seq": 4, "point": "竣工验收备案", "content": "1. 建设单位应在工程竣工验收合格后规定时限内向主管部门备案；\n2. 备案时应提交竣工验收报告、规划、消防、环保等专项验收文件；\n3. 备案文件应齐全、内容真实，不得弄虚作假；\n4. 未经竣工验收或验收不合格的工程不得交付使用。", "basis": "《建设工程质量管理条例》第四十九条\n《房屋建筑和市政基础设施工程竣工验收备案管理办法》第四条、第五条"}, {"seq": 5, "point": "开工条件审查", "content": "1. 建设单位应在开工前确认现场「三通一平」条件满足施工要求；\n2. 施工组织设计、专项施工方案已审批完成；\n3. 施工图会审和设计交底已完成；\n4. 施工合同已签订并备案，质量安全措施费用已落实。", "basis": "《建设工程质量管理条例》第九条\n《建设工程安全生产管理条例》第七条"}, {"seq": 6, "point": "质量管理机构设置", "content": "1. 建设单位应设立专门的质量管理机构或明确质量管理部门；\n2. 应配备专职质量管理人员，专业及数量应满足项目管理需要；\n3. 质量管理机构职责应明确，并形成书面文件；\n4. 质量管理人员应具备相应专业知识和工程管理经验。", "basis": "《建设工程质量管理条例》第七条\n《工程建设施工企业质量管理规范》（GB/T 50430）"}, {"seq": 7, "point": "质量管理制度建设", "content": "1. 建设单位应建立健全质量管理制度体系，包括质量目标管理、质量检查、质量例会、质量奖惩等制度；\n2. 制度应具有可操作性，明确责任人、工作流程和时限要求；\n3. 各项制度应形成书面文件并正式发布实施；\n4. 应根据工程进展和管理需要及时修订完善相关制度。", "basis": "《建设工程质量管理条例》第七条\n《质量管理体系 要求》（GB/T 19001）"}, {"seq": 8, "point": "质量责任制落实", "content": "1. 建设单位应明确项目负责人为工程质量第一责任人；\n2. 应逐级签订质量责任书，明确各岗位质量职责；\n3. 应建立质量责任追溯机制，质量责任可追溯到具体责任人；\n4. 质量责任落实情况应纳入绩效考核。", "basis": "《建设工程质量管理条例》第七条\n《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》"}, {"seq": 9, "point": "质量管理目标制定", "content": "1. 建设单位应在项目开工前制定明确的质量管理目标，包括创优目标；\n2. 质量管理目标应量化、可考核，分解到各参建单位和各施工阶段；\n3. 应定期对质量目标完成情况进行检查和评估；\n4. 质量目标应在施工合同、监理合同中予以明确。", "basis": "《建设工程质量管理条例》第七条\n《工程建设施工企业质量管理规范》（GB/T 50430）"}, {"seq": 10, "point": "合理确定工期", "content": "1. 建设单位应根据工程规模、技术复杂程度等合理确定工期，不得随意压缩合理工期；\n2. 合同工期应与定额工期进行对比，压缩超过定额工期20%的应组织专家论证；\n3. 施工过程中需要调整工期的，应经各方协商一致并按规定程序审批；\n4. 赶工措施应有针对性，并保证质量和安全。", "basis": "《建设工程质量管理条例》第十条\n《建设工程安全生产管理条例》第七条"}, {"seq": 11, "point": "组织设计交底和图纸会审", "content": "1. 建设单位应在施工前组织设计单位向施工、监理单位进行设计交底；\n2. 设计交底应涵盖设计意图、关键技术要求、施工难点及注意事项等；\n3. 图纸会审中提出的问题应予以记录，设计单位应及时书面答复；\n4. 设计交底和图纸会审应形成纪要，作为施工依据。", "basis": "《建设工程质量管理条例》第二十三条\n《建设工程监理规范》（GB/T 50319）5.2"}, {"seq": 12, "point": "施工质量检查", "content": "1. 建设单位应定期组织质量检查，一般每月至少一次；\n2. 检查应覆盖所有施工标段和主要施工环节；\n3. 检查发现的质量问题应及时下发整改通知，并跟踪验证整改情况；\n4. 检查记录应规范、完整，整改闭环资料应归档。", "basis": "《建设工程质量管理条例》第七条、第十五条\n《房屋建筑和市政基础设施工程质量监督管理规定》"}, {"seq": 13, "point": "分包管理", "content": "1. 建设单位应审查总承包单位的分包方案，分包单位资质应符合要求；\n2. 分包合同中应明确质量要求，分包工程质量由总承包单位负责；\n3. 建设单位不得指定分包单位或材料供应商（属于违法发包的情形除外需依法依规）；\n4. 应建立分包单位台账，包含单位名称、资质、分包范围、主要人员等信息。", "basis": "《建设工程质量管理条例》第七十八条\n《建筑工程施工发包与承包违法行为认定查处管理办法》"}, {"seq": 14, "point": "质量问题整改落实", "content": "1. 建设单位应建立质量问题台账，详细记录问题来源、性质、整改要求及时限；\n2. 对监督机构、监理单位、自查发现的问题，应督促施工单位限期整改；\n3. 整改完成后应组织复查，确认整改效果并签字确认；\n4. 重大质量问题应进行原因分析，制定预防措施，防止重复发生。", "basis": "《建设工程质量管理条例》第十四条、第十五条\n《房屋建筑和市政基础设施工程质量监督管理规定》"}, {"seq": 15, "point": "材料构配件质量管理", "content": "1. 建设单位应对涉及结构安全、使用功能的主要材料和构配件提出质量要求；\n2. 按规定需要建设单位见证取样的，应安排人员见证取样并签字确认；\n3. 不得明示或暗示施工单位使用不合格材料或构配件；\n4. 对进场材料检验不合格的，应监督清退出场并记录。", "basis": "《建设工程质量管理条例》第十四条\n《建设工程质量检测管理办法》"}, {"seq": 16, "point": "质量事故报告", "content": "1. 建设单位应在质量事故发生后按规定时限向有关部门报告；\n2. 事故报告内容应完整，包括事故发生的时间、地点、工程部位、事故经过、伤亡情况等；\n3. 不得隐瞒不报、谎报或迟报；\n4. 事故发生后应立即组织抢险，防止事故扩大，保护事故现场。", "basis": "《建设工程质量管理条例》第五十二条\n《生产安全事故报告和调查处理条例》第九条、第十二条"}, {"seq": 17, "point": "质量事故处理", "content": "1. 建设单位应组织或参与质量事故调查分析，查明事故原因；\n2. 应制定事故处理方案，经相关方审核批准后实施；\n3. 事故处理过程中应加强监督，确保处理方案落实到位；\n4. 事故处理完成后应进行验收，形成处理报告并归档。", "basis": "《建设工程质量管理条例》第五十二条\n《生产安全事故报告和调查处理条例》"}, {"seq": 18, "point": "新技术新工艺推广应用", "content": "1. 建设单位应积极推广使用新技术、新工艺、新材料、新设备；\n2. 采用「四新」技术前应进行技术论证，必要时组织专家评审；\n3. 应制定「四新」技术应用实施方案和保障措施；\n4. 对「四新」技术的应用效果应进行跟踪评价和总结。", "basis": "《建设工程质量管理条例》第七条\n《建设领域推广应用新技术管理规定》"}, {"seq": 19, "point": "BIM等信息化技术应用", "content": "1. 鼓励建设单位在大型复杂项目中推行BIM技术应用；\n2. BIM应用应制定实施方案，明确应用目标和范围；\n3. BIM模型应在设计、施工、竣工阶段持续更新和完善；\n4. 应利用BIM技术进行碰撞检查、进度模拟、质量追溯等。", "basis": "《关于推进建筑信息模型应用的指导意见》\n《建筑信息模型应用统一标准》（GB/T 51212）"}, {"seq": 20, "point": "质量教育培训", "content": "1. 建设单位应制定年度或项目质量教育培训计划；\n2. 教育培训内容应包括质量法规、标准规范、质量管理制度、典型案例等；\n3. 教育培训应覆盖项目管理人员和各参建方主要管理人员；\n4. 应建立教育培训档案，记录培训时间、内容、参加人员、考核结果等。", "basis": "《建设工程质量管理条例》第七条\n《安全生产培训管理办法》"}, {"seq": 21, "point": "对监理单位履约检查", "content": "1. 建设单位应定期检查监理单位的履约情况，包括人员到位、设备配置、工作成效等；\n2. 应检查监理规划和监理实施细则的编制及执行情况；\n3. 应检查监理日志、旁站记录、平行检验记录等监理资料的真实性和完整性；\n4. 对监理人员数量不足或资质不符的，应督促监理单位整改。", "basis": "《建设工程质量管理条例》第十二条\n《建设工程监理规范》（GB/T 50319）"}, {"seq": 22, "point": "对监理工作考核", "content": "1. 建设单位应建立监理工作考核制度，一般每季度考核一次；\n2. 考核内容应包括监理工作质量、监理人员到位率、质量安全问题发现及处理情况等；\n3. 考核结果应与监理费用支付挂钩；\n4. 对考核不合格的，应约谈监理单位负责人并限期整改。", "basis": "《建设工程质量管理条例》第十二条\n《建设工程监理规范》（GB/T 50319）"}, {"seq": 23, "point": "对试验检测单位管理", "content": "1. 建设单位应选择具备相应资质的试验检测单位，并在合同中明确检测项目、标准和要求；\n2. 应审核试验检测单位提交的检测计划和检测方案；\n3. 应定期检查试验检测工作的进展和检测报告的质量；\n4. 对检测结果异常的，应督促相关单位进行调查分析和处理。", "basis": "《建设工程质量检测管理办法》\n《建设工程质量管理条例》第三十一条"}, {"seq": 24, "point": "见证取样和送检管理", "content": "1. 建设单位应按规定落实见证取样和送检制度；\n2. 见证人员应具备相应资格，并经过培训；\n3. 见证取样应在见证人员见证下进行，取样数量和部位应符合规范要求；\n4. 见证取样记录和送检台账应完整、规范。", "basis": "《建设工程质量检测管理办法》\n《房屋建筑和市政基础设施工程见证取样和送检管理规定》"}, {"seq": 25, "point": "质量档案管理", "content": "1. 建设单位应建立健全工程质量档案管理制度；\n2. 质量档案应包括质量管理制度文件、质量检查记录、整改通知及回复、质量事故报告及处理、验收文件等；\n3. 档案应分类编号、装订成册，便于查阅和追溯；\n4. 工程竣工后应及时将质量档案移交存档。", "basis": "《建设工程质量管理条例》第十七条\n《建设工程文件归档规范》（GB/T 50328）"}, {"seq": 26, "point": "质量终身责任信息档案", "content": "1. 建设单位应建立工程质量终身责任信息档案；\n2. 档案应包括五方责任主体项目负责人质量终身责任信息；\n3. 相关人员应签署工程质量终身责任承诺书；\n4. 项目负责人变更的，应重新签署承诺书并纳入档案。", "basis": "《建筑工程五方责任主体项目负责人质量终身责任追究暂行办法》\n《建设工程质量管理条例》"}]}, {"name": "1.2 施工单位质量管理行为", "items": [{"seq": 1, "point": "资质管理", "content": "1. 施工单位应在其资质等级许可范围内承揽工程，不得超越资质范围施工；\n2. 资质证书应在有效期内，法人代表、技术负责人等变更应及时办理变更手续；\n3. 不得以其他施工单位名义承揽工程或允许其他单位以本单位名义承揽工程；\n4. 施工项目部应在施工现场公示企业资质及项目主要人员信息。", "basis": "《建筑法》第二十六条\n《建设工程质量管理条例》第二十五条\n《建筑业企业资质管理规定》"}, {"seq": 2, "point": "质量管理体系", "content": "1. 施工单位应建立并有效运行质量管理体系，覆盖所有质量管理活动；\n2. 质量管理体系应形成文件，包括质量手册、程序文件、作业指导书等；\n3. 质量管理体系应定期进行内部审核和管理评审；\n4. 应取得质量管理体系认证证书并保持持续有效。", "basis": "《工程建设施工企业质量管理规范》（GB/T 50430）\n《质量管理体系 要求》（GB/T 19001）"}, {"seq": 3, "point": "质量责任制", "content": "1. 施工单位应建立从企业负责人到操作人员的全员质量责任制；\n2. 项目经理是项目质量第一责任人，应对项目质量全面负责；\n3. 应逐级签订质量责任书，明确各岗位的质量职责和考核标准；\n4. 关键岗位人员（技术负责人、质检员等）应持证上岗。", "basis": "《建设工程质量管理条例》第二十六条\n《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》"}, {"seq": 4, "point": "项目经理到岗履职", "content": "1. 项目经理应常驻施工现场，每月到岗时间不得少于施工天数的80%；\n2. 项目经理变更应经建设单位同意并办理变更手续，新任项目经理资格不得低于原任；\n3. 项目经理应参加重要工序验收、质量问题处理等关键环节；\n4. 施工日志中应记录项目经理每日工作内容。", "basis": "《建筑施工企业负责人及项目负责人施工现场带班暂行办法》\n《建设工程质量管理条例》第二十六条"}, {"seq": 5, "point": "施工组织设计编制与审批", "content": "1. 施工组织设计应在施工准备阶段编制完成，经施工单位内部审批后报监理、建设单位审批；\n2. 内容应完整，包括工程概况、施工部署、主要施工方法、质量保证措施、进度计划等；\n3. 对危险性较大的分部分项工程应有专项施工方案并经专家论证；\n4. 施工组织设计应动态调整，当条件发生重大变化时应及时修订。", "basis": "《建设工程质量管理条例》第二十八条\n《建筑施工组织设计规范》（GB/T 50502）"}, {"seq": 6, "point": "图纸会审与设计交底", "content": "1. 施工单位应组织技术人员认真熟悉图纸，形成书面问题清单；\n2. 参加建设单位组织的设计交底和图纸会审，做好会议记录；\n3. 图纸会审中提出的问题应有书面答复并形成纪要；\n4. 图纸会审纪要和设计变更文件应及时分发至各作业班组。", "basis": "《建设工程质量管理条例》第二十八条\n《建设工程监理规范》（GB/T 50319）5.2"}, {"seq": 7, "point": "技术交底", "content": "1. 施工单位应在每道工序施工前进行技术交底，交底对象覆盖全部作业人员；\n2. 技术交底内容应包括施工工艺、质量标准、安全要求、常见问题及预防措施等；\n3. 技术交底应有书面记录，交底人和被交底人签字确认；\n4. 对于关键工序和特殊过程，技术负责人应亲自进行交底。", "basis": "《建设工程质量管理条例》第二十八条\n《建筑施工安全检查标准》（JGJ 59）"}, {"seq": 8, "point": "测量放线", "content": "1. 施工单位应建立测量控制网，控制点应牢固可靠并有保护措施；\n2. 测量仪器应经法定计量检定机构检定合格并在有效期内；\n3. 测量放线工作应自检、互检后报监理复核，未经复核不得使用；\n4. 测量原始记录和成果报告应规范记录并归档。", "basis": "《工程测量规范》（GB 50026）\n《建设工程质量管理条例》第二十八条"}, {"seq": 9, "point": "材料进场检验", "content": "1. 施工单位应建立材料进场验收制度，对进场材料按批次进行质量检验；\n2. 应查验材料出厂合格证、质量证明文件，核对规格、数量、外观质量等；\n3. 需要复验的材料应在监理见证下取样送检，复验合格后方可使用；\n4. 不合格材料应标识、隔离并及时清退出场，不得用于工程。", "basis": "《建设工程质量管理条例》第二十九条\n《建设工程质量检测管理办法》"}, {"seq": 10, "point": "工序质量控制", "content": "1. 施工单位应严格执行「三检制」（自检、互检、交接检）；\n2. 隐蔽工程在隐蔽前应通知监理单位和建设单位检查验收，未经检查不得隐蔽；\n3. 每道工序完成后应经质检员检查合格方可进入下道工序；\n4. 工序质量检查应有书面记录，检查人员签字确认。", "basis": "《建设工程质量管理条例》第三十条\n《建筑工程施工质量验收统一标准》（GB 50300）"}, {"seq": 11, "point": "隐蔽工程验收", "content": "1. 隐蔽工程施工完成后，施工单位应先进行自检，填写隐蔽工程验收记录；\n2. 应及时通知监理单位（或建设单位）进行隐蔽验收，验收合格后方可隐蔽；\n3. 隐蔽验收记录应真实、完整，包括检查部位、检查结果、验收结论等；\n4. 隐蔽工程应留存影像资料，关键部位应有量测数据支撑。", "basis": "《建设工程质量管理条例》第三十条\n《建筑工程施工质量验收统一标准》（GB 50300）"}, {"seq": 12, "point": "质量检查与评定", "content": "1. 施工单位应按规定进行分项、分部工程质量检验评定；\n2. 检验评定应依据设计文件和验收规范进行，不得降低标准；\n3. 质量评定应实事求是，不得虚报、瞒报；\n4. 检验批划分应合理，检验数量和频率应符合规范要求。", "basis": "《建筑工程施工质量验收统一标准》（GB 50300）\n《建设工程质量管理条例》第三十条"}, {"seq": 13, "point": "质量问题整改", "content": "1. 施工单位对施工过程中发现的质量问题应及时整改，不得拖延或隐瞒；\n2. 整改应有专人负责，整改方案应经技术负责人审核；\n3. 整改完成后应自检合格，再报监理/建设单位复查确认；\n4. 应建立质量问题整改台账，记录问题发现、整改措施、完成时间、验证结果等。", "basis": "《建设工程质量管理条例》第三十二条\n《工程建设施工企业质量管理规范》（GB/T 50430）"}, {"seq": 14, "point": "分包管理", "content": "1. 施工单位应依法分包，分包单位应具备相应资质；\n2. 分包合同应明确质量要求和责任，不得以包代管；\n3. 总承包单位应对分包工程质量负总责，加强对分包单位的质量管理和控制；\n4. 分包单位进场前应进行资质审查和技术交底。", "basis": "《建设工程质量管理条例》第二十七条\n《房屋建筑和市政基础设施工程施工分包管理办法》"}, {"seq": 15, "point": "施工日志与记录", "content": "1. 施工单位应逐日填写施工日志，记录当天的施工部位、施工内容、作业人员、材料机具使用情况等；\n2. 施工日志应由施工员或技术负责人填写，项目经理定期检查签字；\n3. 施工日志应连续、完整，不得缺页、篡改；\n4. 施工日志是质量追溯的重要凭证，应妥善保管。", "basis": "《建设工程质量管理条例》第三十条\n《建筑工程施工质量验收统一标准》（GB 50300）"}, {"seq": 16, "point": "样板引路制度", "content": "1. 重要工序或部位施工前，施工单位应先制作样板，经各方验收合格后方可大面积施工；\n2. 样板应包括主要施工工艺、节点做法、质量效果等，具有示范性和可复制性；\n3. 样板验收应形成书面记录，明确验收标准和通过结论；\n4. 后续施工应严格以样板为标准，不得降低施工质量。", "basis": "《建设工程质量管理条例》第二十八条\n《工程建设施工企业质量管理规范》（GB/T 50430）"}, {"seq": 17, "point": "混凝土质量管理", "content": "1. 混凝土浇筑前应进行配合比设计试验，配合比应符合设计和规范要求；\n2. 拌合站的生产、运输、浇筑、养护等环节应符合混凝土质量控制标准；\n3. 应按规范留置混凝土试件，标准养护和同条件养护试件均应满足要求；\n4. 大体积混凝土应有温控措施，冬季和高温季节施工应有专项方案。", "basis": "《混凝土结构工程施工质量验收规范》（GB 50204）\n《混凝土质量控制标准》（GB 50164）"}, {"seq": 18, "point": "钢筋工程质量管理", "content": "1. 钢筋进场应有出厂合格证和检验报告，按规定进行力学性能和重量偏差复验；\n2. 钢筋加工和安装应符合设计图纸和规范要求，接头位置、锚固长度等应重点检查；\n3. 钢筋连接（焊接、机械连接）应按规定进行工艺检验和现场检验；\n4. 钢筋隐蔽前应检查钢筋品种、规格、数量、位置、间距、保护层厚度等。", "basis": "《混凝土结构工程施工质量验收规范》（GB 50204）\n《钢筋焊接及验收规程》（JGJ 18）"}, {"seq": 19, "point": "新技术的应用推广", "content": "1. 施工单位应关注行业技术进步，积极学习和应用新技术、新工艺、新材料、新设备；\n2. 采用「四新」技术前应编制专项技术方案并按规定审批；\n3. 对「四新」技术的应用应有专项技术培训；\n4. 应总结「四新」技术应用经验，形成工法或技术成果。", "basis": "《建设领域推广应用新技术管理规定》\n《建筑施工企业安全生产管理规范》（GB 50656）"}, {"seq": 20, "point": "QC小组活动", "content": "1. 鼓励施工单位在项目中开展质量管理小组（QC小组）活动；\n2. QC小组应针对现场质量通病和难点问题开展攻关；\n3. QC小组活动应按PDCA循环开展，注重数据和事实；\n4. QC成果应进行发表和推广，促进全员质量改进意识。", "basis": "《质量管理小组活动准则》（T/CAQ 10201）\n《工程建设施工企业质量管理规范》（GB/T 50430）"}, {"seq": 21, "point": "质量教育培训", "content": "1. 施工单位应制定年度和项目质量教育培训计划并组织实施；\n2. 新进场工人应进行公司、项目部、班组三级质量安全教育；\n3. 特种作业人员应经专门培训取得操作资格证书后方可上岗；\n4. 教育培训应有记录，包括培训教材、签到表、考核试卷、成绩单等。", "basis": "《建设工程质量管理条例》第三十三条\n《建筑施工特种作业人员管理规定》"}, {"seq": 22, "point": "持证上岗管理", "content": "1. 施工单位应建立从业人员持证台账，关键岗位人员证件应齐全有效；\n2. 质检员、试验员、测量员等质量相关人员应持相应岗位证书；\n3. 特种作业人员操作证应在有效期内，按期复审；\n4. 项目部应留存所有持证人员的证书复印件，现场随机抽查人证相符。", "basis": "《建筑施工特种作业人员管理规定》\n《建设工程质量管理条例》第三十三条"}, {"seq": 23, "point": "工地试验室管理", "content": "1. 施工单位根据工程需要设立工地试验室的，应按规定进行能力核验；\n2. 试验室面积、环境条件、仪器设备等应满足检测工作需要；\n3. 试验检测人员应持证上岗，数量满足检测工作量要求；\n4. 试验仪器设备应定期检定/校准，并在有效期内使用。", "basis": "《建设工程质量检测管理办法》\n《公路水运工程试验检测管理办法》"}, {"seq": 24, "point": "试件试块管理", "content": "1. 混凝土试件、砂浆试块等应在浇筑地点随机取样制作，不得弄虚作假；\n2. 试件标识应清晰，注明工程部位、强度等级、制作日期等；\n3. 试件养护条件应符合规范要求（标准养护和同条件养护）；\n4. 试件送检应有台账管理，及时跟踪检测结果。", "basis": "《混凝土结构工程施工质量验收规范》（GB 50204）\n《建设工程质量检测管理办法》"}, {"seq": 25, "point": "施工质量资料管理", "content": "1. 施工单位应配备专（兼）职资料员，对施工质量资料进行跟踪收集和管理；\n2. 质量资料应随工程进度同步形成，不得事后补做、伪造；\n3. 质量资料应分类整理，目录清晰，内容完整，签章齐全；\n4. 竣工后应按档案管理要求将质量资料移交建设单位和城建档案馆。", "basis": "《建设工程文件归档规范》（GB/T 50328）\n《建设工程质量管理条例》第三十条"}, {"seq": 26, "point": "施工技术资料归档", "content": "1. 施工技术资料应包括施工组织设计、施工方案、技术交底、隐蔽验收、质量检验评定、竣工验收等文件；\n2. 资料归档前应进行完整性、准确性、规范性审查；\n3. 电子档案应定期备份，纸质档案应防火、防潮、防虫；\n4. 归档资料应便于检索和追溯。", "basis": "《建设工程文件归档规范》（GB/T 50328）\n《建设工程质量管理条例》第三十条"}, {"seq": 27, "point": "成品保护管理", "content": "1. 施工单位应制定成品保护方案，明确各工序成品的保护措施和责任人；\n2. 已完成的分项工程和安装设备应有标识和防护措施；\n3. 交叉施工时应合理安排工序，避免后道工序对前道工序成品造成损坏；\n4. 对因保护不当造成的质量缺陷应及时修复并经检查确认。", "basis": "《建设工程质量管理条例》第二十八条\n《工程建设施工企业质量管理规范》（GB/T 50430）"}, {"seq": 28, "point": "季节性施工质量管理", "content": "1. 施工单位应编制冬期、雨期、高温季节施工专项方案并按规定审批；\n2. 季节性施工措施应满足规范要求，如冬期施工的保温防冻措施、雨期施工的排水防雨措施等；\n3. 季节性施工期间应增加质量检查频次，特别是混凝土浇筑养护、焊接作业等关键环节；\n4. 季节性施工完成后应对受影响的分项工程进行质量复查。", "basis": "《建筑工程冬期施工规程》（JGJ/T 104）\n《混凝土结构工程施工质量验收规范》（GB 50204）"}]}, {"name": "1.3 监理单位质量管理行为", "items": [{"seq": 1, "point": "监理资质管理", "content": "1. 监理单位应在资质等级许可范围内承揽监理业务；\n2. 不得转让监理业务，不得允许其他单位或个人以本单位名义承揽监理业务；\n3. 监理合同应明确监理范围、内容、服务期限和人员配置；\n4. 监理单位应在施工现场公示监理企业资质和项目监理人员信息。", "basis": "《建设工程质量管理条例》第三十四条\n《工程监理企业资质管理规定》"}, {"seq": 2, "point": "项目监理机构组建", "content": "1. 项目监理机构应根据工程规模、合同约定和监理工作需要进行组建；\n2. 总监理工程师、专业监理工程师、监理员的数量和专业配置应满足工作需要；\n3. 总监理工程师应由注册监理工程师担任，一名总监同时管理的项目不应超过3个；\n4. 总监理工程师变更应经建设单位同意并办理变更手续。", "basis": "《建设工程监理规范》（GB/T 50319）3.1\n《建设工程质量管理条例》第三十七条"}, {"seq": 3, "point": "监理规划编制", "content": "1. 监理规划应在签订监理合同及收到设计文件后由总监理工程师组织编制；\n2. 监理规划应报监理单位技术负责人审批，并报送建设单位；\n3. 监理规划内容应包括工程概况、监理工作范围与内容、监理工作目标、监理工作程序与方法等；\n4. 在实施过程中情况发生变化时，应及时修订监理规划。", "basis": "《建设工程监理规范》（GB/T 50319）4.1、4.2"}, {"seq": 4, "point": "监理实施细则编制", "content": "1. 对专业性较强、危险性较大的分部分项工程应编制监理实施细则；\n2. 监理实施细则应由专业监理工程师编制，总监理工程师审批；\n3. 监理实施细则应详细具体，具有可操作性，包括专业工程特点、监理工作流程、监理工作要点等；\n4. 在相应工程开始施工前完成编制，并随工程进展动态调整。", "basis": "《建设工程监理规范》（GB/T 50319）4.3"}, {"seq": 5, "point": "监理人员到岗履职", "content": "1. 总监理工程师和专业监理工程师应按合同约定到岗，到岗时间不得少于合同约定；\n2. 关键工序、关键部位施工和隐蔽工程验收时，监理人员应到场旁站或巡视；\n3. 监理人员应佩戴证件，做好监理日志，记录每日工作内容和发现的问题；\n4. 总监理工程师因故离开现场超过规定天数的，应指定临时负责人。", "basis": "《建设工程监理规范》（GB/T 50319）3.2\n《建设工程质量管理条例》第三十八条"}, {"seq": 6, "point": "监理回避制度", "content": "1. 监理单位不得与被监理工程的建设施工单位、材料供应商等有利害关系；\n2. 工程监理单位的工作人员不得在施工、材料供应等单位兼职；\n3. 存在利害关系可能影响公正监理的，监理单位应主动回避或更换相关人员；\n4. 监理单位与被监理单位不得是同一集团的关联企业。", "basis": "《建设工程质量管理条例》第三十五条"}, {"seq": 7, "point": "禁止转包与挂靠", "content": "1. 监理单位不得转让工程监理业务；\n2. 监理单位不得允许其他单位或个人以本单位名义承揽监理业务（挂靠）；\n3. 监理项目部全部人员应与监理单位签订正式劳动合同并按期缴纳社保；\n4. 监理费用支付凭证、人员劳动关系等应一致，不得弄虚作假。", "basis": "《建设工程质量管理条例》第三十四条\n《工程监理企业资质管理规定》"}, {"seq": 8, "point": "施工图纸审查", "content": "1. 总监理工程师应组织监理人员熟悉施工图纸，提出书面审图意见；\n2. 对图纸中发现的问题应及时书面报告建设单位，由建设单位转设计单位处理；\n3. 参加建设单位组织的图纸会审和设计交底会议，并形成会议纪要；\n4. 设计变更文件应由建设单位签认后下发，监理应监督施工单位按变更文件施工。", "basis": "《建设工程监理规范》（GB/T 50319）5.1\n《建设工程质量管理条例》第三十七条"}, {"seq": 9, "point": "施工组织设计审查", "content": "1. 总监理工程师应组织专业监理工程师对施工组织设计进行审查；\n2. 审查应包括施工方案是否可行、质量保证措施是否到位、进度计划是否合理、安全措施是否完善等；\n3. 审查结论应书面告知施工单位，需要修改的应要求施工单位补充完善后重新报审；\n4. 施工组织设计未经监理审批同意，不得实施。", "basis": "《建设工程监理规范》（GB/T 50319）5.1\n《建设工程质量管理条例》第三十七条"}, {"seq": 10, "point": "分包单位资质审查", "content": "1. 监理单位应对施工总承包单位报送的分包单位资质进行审查；\n2. 审查内容应包括营业执照、资质证书、安全生产许可证、类似工程业绩等；\n3. 对审查不合格的分包单位，监理应书面通知施工单位更换；\n4. 未经监理审查同意，分包单位不得进场施工。", "basis": "《建设工程监理规范》（GB/T 50319）5.1\n《建设工程质量管理条例》第三十七条"}, {"seq": 11, "point": "测量放线复核", "content": "1. 监理工程师应对施工单位报送的测量放线成果进行复核；\n2. 复核应包括控制桩的校核、轴线控制桩的位置、各楼层高程控制线等；\n3. 复核结果合格后方可签认，同意施工单位进入下道工序；\n4. 复核记录应形成书面文件，监理工程师签字确认。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《工程测量规范》（GB 50026）"}, {"seq": 12, "point": "进场材料构配件检验", "content": "1. 监理工程师应对进场材料、构配件和设备的出厂合格证、质量保证资料进行审核；\n2. 对按规定需要复验的材料，监理应见证取样送检；\n3. 对检验不合格的材料，监理应签发监理通知单，要求施工单位限期退场并记录；\n4. 监理应建立材料进场台账，跟踪每批材料的检验结果和使用部位。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量管理条例》第三十七条"}, {"seq": 13, "point": "开工条件审查", "content": "1. 总监理工程师应组织对开工条件进行审查，包括施工许可证、施工组织设计审批、人员机具到位情况等；\n2. 审查合格后签署开工报告或开工令；\n3. 开工条件不满足的，监理应书面告知施工单位补充完善；\n4. 未经监理签署同意，施工单位不得擅自开工。", "basis": "《建设工程监理规范》（GB/T 50319）5.1\n《建设工程质量管理条例》第三十七条"}, {"seq": 14, "point": "巡视检查", "content": "1. 监理人员应每天对施工现场进行巡视检查，了解施工进度和质量状况；\n2. 巡视检查应关注施工工艺是否符合方案要求、操作是否规范、是否存在质量隐患等；\n3. 巡视检查发现的的问题应及时记录在监理日志中，并根据问题严重程度采取口头或书面形式告知施工单位；\n4. 对列入重点监控的施工部位和工序应增加巡视频次。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量管理条例》第三十八条"}, {"seq": 15, "point": "旁站监理", "content": "1. 对关键工序、关键部位（如混凝土浇筑、钢结构安装、预应力张拉等）应实施旁站监理；\n2. 旁站监理应按旁站方案执行，旁站监理人员不得擅离岗位；\n3. 旁站过程中发现质量问题的，应立即要求施工单位整改或暂停施工，并报告总监理工程师；\n4. 旁站监理应填写旁站监理记录，记录旁站时间、施工情况、发现问题及处理结果。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《房屋建筑工程施工旁站监理管理办法（试行）》"}, {"seq": 16, "point": "平行检验", "content": "1. 监理单位应按监理规划和合同约定对工程质量进行平行检验；\n2. 平行检验的项目和频次应满足合同要求和相关规范规定；\n3. 平行检验应使用经检定合格的仪器设备，检验数据应客观真实；\n4. 平行检验结果与施工单位自检结果不一致时，应分析原因并及时处理。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量管理条例》第三十八条"}, {"seq": 17, "point": "隐蔽工程验收", "content": "1. 监理工程师应在收到施工单位隐蔽工程报验申请后及时组织验收；\n2. 验收应核查施工自检记录、材料检测报告等资料，并现场检查实体质量；\n3. 验收合格的应及时签认，同意隐蔽；验收不合格的应要求整改后重新报验；\n4. 隐蔽工程验收记录应完整、规范，签章齐全。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量管理条例》第三十七条"}, {"seq": 18, "point": "检验批分项分部工程验收", "content": "1. 监理工程师应按规范要求对检验批、分项、分部工程进行验收；\n2. 验收应依据设计文件、验收规范和质量评定标准进行；\n3. 未经验收或验收不合格的，不得进入下道工序或下一分部工程施工；\n4. 验收记录应规范填写，签章齐全，评定结论应准确。", "basis": "《建筑工程施工质量验收统一标准》（GB 50300）\n《建设工程监理规范》（GB/T 50319）5.2"}, {"seq": 19, "point": "质量问题处理", "content": "1. 监理发现施工质量问题时，应根据问题严重程度及时签发监理通知单或工程暂停令；\n2. 应跟踪督促施工单位整改，施工单位整改后应报监理复查；\n3. 对涉及结构安全的重大质量问题，监理应立即报告建设单位并下达暂停令；\n4. 质量问题处理全过程应有书面记录，形成闭环管理。", "basis": "《建设工程监理规范》（GB/T 50319）5.2、6\n《建设工程质量管理条例》第三十八条"}, {"seq": 20, "point": "工程暂停与复工管理", "content": "1. 出现需要暂停施工的情况时，总监理工程师应及时签发工程暂停令；\n2. 工程暂停令应明确停工原因、停工范围和处理要求；\n3. 当暂停原因消除、具备复工条件时，监理应在施工单位提交复工申请后及时审查；\n4. 经审查符合复工条件的，总监理工程师应及时签署复工令。", "basis": "《建设工程监理规范》（GB/T 50319）6"}, {"seq": 21, "point": "监理日志与月报", "content": "1. 监理人员应逐日填写监理日志，全面记录当天施工情况、监理工作内容和发现的问题；\n2. 监理日志应连续、完整，不得缺页、事后补写；\n3. 总监理工程师应定期检查监理日志填写质量；\n4. 监理月报应按月编制，报送建设单位和监理单位。", "basis": "《建设工程监理规范》（GB/T 50319）7.1、7.2"}, {"seq": 22, "point": "监理人员教育培训", "content": "1. 监理单位应制定监理人员年度培训计划并组织实施；\n2. 培训内容应包括法律法规、标准规范、监理实务、典型案例等；\n3. 总监理工程师和监理工程师应按规定参加继续教育；\n4. 培训应有记录，包括培训通知、签到表、培训资料、考核结果等。", "basis": "《建设工程监理规范》（GB/T 50319）3.1\n《注册监理工程师管理规定》"}, {"seq": 23, "point": "对施工试验检测的监理", "content": "1. 监理工程师应对施工单位的试验检测工作进行检查和监督；\n2. 应审核施工单位提交的试验检测计划，核查检测项目和频次是否满足规范要求；\n3. 对见证取样和送检应按规范要求执行，见证记录应真实完整；\n4. 应定期检查施工单位工地试验室的运行情况。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量检测管理办法》"}, {"seq": 24, "point": "检测结果跟踪处理", "content": "1. 监理应建立检测结果台账，跟踪每份检测报告的结论；\n2. 对检测不合格的项目，监理应及时签发监理通知单要求进行处理；\n3. 施工单位处理后应重新检测，合格后方可进行下道工序；\n4. 检测结果异常可能影响结构安全的，监理应及时报告建设单位并组织分析处理。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量检测管理办法》"}, {"seq": 25, "point": "监理资料管理", "content": "1. 监理单位应配备专（兼）职资料管理人员，建立监理资料管理制度；\n2. 监理资料应随工程进度同步收集、整理，不得事后补做；\n3. 监理资料应包括监理管理文件（规划、细则等）、质量控制文件（通知单、旁站记录等）、验收文件等；\n4. 监理资料应分类立卷，目录清晰，签章齐全，内容完整。", "basis": "《建设工程监理规范》（GB/T 50319）7\n《建设工程文件归档规范》（GB/T 50328）"}, {"seq": 26, "point": "监理档案移交", "content": "1. 工程竣工后，监理单位应按规定整理监理档案，向建设单位和城建档案馆移交；\n2. 移交的监理档案应包括纸质档案和电子档案，内容应完整、规范；\n3. 移交前应经总监理工程师审核，确保档案质量；\n4. 移交手续应规范，填写档案移交清单，双方签字盖章。", "basis": "《建设工程监理规范》（GB/T 50319）7.4\n《建设工程文件归档规范》（GB/T 50328）"}, {"seq": 27, "point": "工程变更管理", "content": "1. 监理单位应对设计变更和工程洽商进行审核，重点审核变更的必要性、可行性及对质量的影响；\n2. 变更涉及的质量标准调整应符合规范要求，不得降低工程质量；\n3. 变更实施前监理应向施工单位进行变更交底；\n4. 变更实施过程中监理应跟踪检查，确保按变更文件施工。", "basis": "《建设工程监理规范》（GB/T 50319）5.2、6\n《建设工程质量管理条例》第三十七条"}, {"seq": 28, "point": "计量与支付审核中的质量控制", "content": "1. 监理工程师应在计量支付审核中结合质量检验评定结果进行；\n2. 未经质量检验评定或评定不合格的工程不得计量；\n3. 对存在质量缺陷的工程，应在整改合格后方可计量；\n4. 计量支付文件应准确反映已完合格工程的数量和质量状况。", "basis": "《建设工程监理规范》（GB/T 50319）5.3\n《建设工程工程量清单计价规范》（GB 50500）"}, {"seq": 29, "point": "竣工验收监理", "content": "1. 总监理工程师应组织专业监理工程师对竣工资料及工程实体质量进行全面检查；\n2. 对检查发现的质量问题应督促施工单位整改，整改合格后方可签署竣工验收意见；\n3. 监理单位应参加建设单位组织的竣工验收，提交监理工作总结和质量评估报告；\n4. 竣工验收中提出的整改意见应跟踪监督施工单位落实。", "basis": "《建设工程监理规范》（GB/T 50319）5.2\n《建设工程质量管理条例》第三十七条"}, {"seq": 30, "point": "质量评估报告编制", "content": "1. 工程竣工预验收合格后，总监理工程师应组织编制工程质量评估报告；\n2. 质量评估报告应客观、真实地反映工程质量状况，包括各分部工程质量评定、质量问题和处理情况等；\n3. 质量评估报告应经总监理工程师签署并加盖监理单位公章；\n4. 质量评估报告应在竣工验收前报送建设单位。", "basis": "《建设工程监理规范》（GB/T 50319）5.2、7.3\n《建设工程质量管理条例》第三十七条"}, {"seq": 31, "point": "危险性较大分部分项工程监理", "content": "1. 监理单位应针对危险性较大的分部分项工程编制专项监理实施细则；\n2. 应审核施工单位提交的危大工程专项施工方案，重点审核计算书、安全技术措施等；\n3. 危大工程施工过程中应实施专项巡视和旁站监理；\n4. 危大工程验收时总监应到场参加，验收合格后方可进入下道工序。", "basis": "《危险性较大的分部分项工程安全管理规定》\n《建设工程监理规范》（GB/T 50319）"}]}, {"name": "1.4 试验检测单位质量管理行为", "items": [{"seq": 1, "point": "检测机构资质管理", "content": "1. 试验检测单位应取得建设工程质量检测机构资质证书，在资质许可范围内开展检测业务；\n2. 资质证书应在有效期内，按期进行资质延续或升级；\n3. 检测机构不得转包检测业务，不得涂改、倒卖、出租或以其他形式非法转让资质证书；\n4. 检测机构变更名称、地址、法定代表人、技术负责人等，应及时办理资质变更手续。", "basis": "《建设工程质量检测管理办法》第四条、第五条"}, {"seq": 2, "point": "检测人员资格管理", "content": "1. 检测人员应经培训考核合格，持证上岗；\n2. 技术负责人应具有相应专业高级职称并从事检测工作一定年限；\n3. 检测报告审核人、签发人应具备相应资格并在授权范围内工作；\n4. 检测人员应定期参加继续教育和业务培训。", "basis": "《建设工程质量检测管理办法》第十条\n《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）"}, {"seq": 3, "point": "质量管理体系", "content": "1. 试验检测单位应建立并有效运行质量管理体系，覆盖全部检测活动；\n2. 质量管理体系应形成文件，包括质量手册、程序文件、操作规程等；\n3. 质量管理体系应定期进行内部审核和管理评审，持续改进；\n4. 应保证检测工作的独立性、公正性和科学性，不受任何行政干预和商业干扰。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 4, "point": "检测合同管理", "content": "1. 试验检测单位应与委托方签订书面检测合同，明确检测项目、标准、方法、频次、费用等；\n2. 检测合同应合法合规，不得签订损害第三方利益的条款；\n3. 合同履行过程中如需变更检测内容，应签订补充协议；\n4. 检测合同及相关凭证应归档保存。", "basis": "《建设工程质量检测管理办法》第十二条\n《中华人民共和国民法典》"}, {"seq": 5, "point": "工地试验室设立", "content": "1. 工地试验室设立前应进行规划，母体机构应对工地试验室进行授权；\n2. 授权内容包括检测项目、检测参数、授权签字人及授权范围等；\n3. 工地试验室应按规定向项目质监机构备案或办理能力核验；\n4. 工地试验室不得对外承揽检测业务。", "basis": "《建设工程质量检测管理办法》第十二条\n《公路水运工程试验检测管理办法》"}, {"seq": 6, "point": "试验室环境条件", "content": "1. 工地试验室面积应满足检测工作需要，功能分区合理（力学室、水泥室、养护室、土工室等）；\n2. 环境条件（温度、湿度、通风、照明、防震等）应符合检测标准要求；\n3. 各试验室应配备温湿度控制设备和监测记录仪表，每日记录环境条件；\n4. 养护室应满足标准养护条件，温湿度自动控制并记录。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 7, "point": "仪器设备配置与管理", "content": "1. 仪器设备的种类、数量、精度、量程等应满足检测工作需要；\n2. 仪器设备应建立台账，一台一档，标明设备名称、型号、编号、检定日期等；\n3. 仪器设备应定期检定/校准，在检定/校准有效期内使用，并粘贴状态标识；\n4. 仪器设备使用应有记录，使用前后应检查运行状态是否正常。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 8, "point": "检测标准与方法管理", "content": "1. 试验检测单位应使用现行有效的检测标准和检测方法；\n2. 应建立检测标准台账，及时跟踪标准更新，废止标准不得使用；\n3. 使用非标准方法时应进行方法确认并经委托方同意；\n4. 检测作业指导书应依据检测标准编写，经审批后使用。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》第十三条"}, {"seq": 9, "point": "样品管理", "content": "1. 试验检测单位应建立样品管理制度，对样品的接收、标识、流转、保存、处置进行全过程管理；\n2. 接收样品时应检查样品状态是否符合检测要求，不符合的应拒收并记录；\n3. 样品应有唯一性标识，流转过程中标识应保持清晰；\n4. 样品的保存条件应符合标准要求，留存期限按规定执行，处置应有记录。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 10, "point": "检测过程质量控制", "content": "1. 检测人员应严格按照检测标准和操作规程进行检测，不得擅自更改检测方法和条件；\n2. 检测原始记录应在检测过程中实时记录，不得事后补记或誊抄；\n3. 应采取质量控制措施，如平行试验、比对试验、留样复测等；\n4. 检测过程中出现异常情况时，检测人员应停止检测，查明原因后重新进行。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》第十三条"}, {"seq": 11, "point": "检测报告管理", "content": "1. 检测报告应内容完整、数据准确、结论明确、签章齐全；\n2. 检测报告应采用法定计量单位，检测结果应按标准要求进行修约；\n3. 检测报告不得涂改，如有错误应按规定程序更正或重新出具；\n4. 检测报告应经检测人、审核人、签发人三级签字并加盖检测机构公章或检测专用章。", "basis": "《建设工程质量检测管理办法》第十四条\n《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）"}, {"seq": 12, "point": "见证取样检测", "content": "1. 检测机构应接收经见证人员见证的样品，并核对见证人员身份；\n2. 见证取样送检的样品应有见证封样，封条完好；\n3. 检测报告应注明见证单位和见证人员信息；\n4. 见证取样检测的项目和频次应符合相关规范和合同要求。", "basis": "《建设工程质量检测管理办法》第十五条\n《房屋建筑和市政基础设施工程见证取样和送检管理规定》"}, {"seq": 13, "point": "不合格检测结果处理", "content": "1. 检测结果不合格的，检测机构应在规定时限内书面通知委托单位和工程质量监督机构；\n2. 不合格报告应单独建立台账，注明处理情况和跟踪结果；\n3. 不得隐瞒或拖延报告不合格检测结果；\n4. 对于复检检测，应注明「复检」字样。", "basis": "《建设工程质量检测管理办法》第十七条"}, {"seq": 14, "point": "检测数据真实性", "content": "1. 检测机构应对检测数据的真实性、准确性负责；\n2. 不得出具虚假检测报告，不得篡改检测数据；\n3. 不得接受委托方或其他利益相关方的要求出具不实报告；\n4. 检测原始记录和报告应具有可追溯性，电子数据应防止被篡改。", "basis": "《建设工程质量检测管理办法》第十八条\n《刑法》第二百二十九条"}, {"seq": 15, "point": "比对试验与能力验证", "content": "1. 试验检测单位应积极参加行业主管部门或行业协会组织的比对试验和能力验证；\n2. 比对试验和能力验证结果应进行分析，不合格的项目应查找原因并采取纠正措施；\n3. 应定期在内部组织人员比对、设备比对等质量控制活动；\n4. 比对试验和能力验证报告应归档保存。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 16, "point": "试验检测信息化管理", "content": "1. 鼓励试验检测单位采用信息化管理系统，实现检测流程的电子化管理；\n2. 检测数据应实时采集并上传系统，减少人为干预；\n3. 信息化系统应具备数据防篡改功能，确保数据安全可靠；\n4. 系统应能自动生成检测报告，实现数据的可追溯。", "basis": "《建设工程质量检测管理办法》\n《关于推进建设工程质量检测信息化管理的指导意见》"}, {"seq": 17, "point": "检测机构自查与整改", "content": "1. 试验检测单位应定期开展自查，检查质量管理体系运行情况和检测工作质量；\n2. 自查发现的问题应制定整改措施并明确责任人和整改期限；\n3. 整改完成后应进行验证，确保整改效果；\n4. 自查和整改记录应归档保存。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 18, "point": "外部检查问题整改", "content": "1. 对主管部门、质监机构等外部检查发现的问题，检测机构应认真整改；\n2. 整改应在规定时限内完成，并及时上报整改报告及佐证材料；\n3. 整改应举一反三，防止类似问题再次发生；\n4. 重大问题的整改应有专项方案并经审批后实施。", "basis": "《建设工程质量检测管理办法》\n《检验检测机构资质认定管理办法》"}, {"seq": 19, "point": "检测档案管理", "content": "1. 试验检测单位应建立检测档案管理制度，明确档案收集、整理、保管和销毁的要求；\n2. 检测档案应包括检测合同、委托单、原始记录、检测报告、仪器设备档案、人员档案等；\n3. 原始记录和检测报告的保存期限一般不少于6年；\n4. 档案保管应有防火、防潮、防虫、防盗措施，电子档案应定期备份。", "basis": "《建设工程质量检测管理办法》第十六条\n《建设工程文件归档规范》（GB/T 50328）"}, {"seq": 20, "point": "检测报告存档与查阅", "content": "1. 检测报告应按编号顺序归档，建立检索目录便于查阅；\n2. 检测报告的调阅应按规定程序进行，遵守保密要求；\n3. 电子检测报告应双重备份，异地保存一份；\n4. 超过保存期限的档案经批准后按规定销毁并记录。", "basis": "《建设工程质量检测管理办法》第十六条\n《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）"}, {"seq": 21, "point": "检测机构诚信管理", "content": "1. 试验检测单位应遵守诚信原则，不得出具虚假检测报告；\n2. 应建立诚信管理制度，对检测人员进行诚信教育；\n3. 不得以不正当手段承揽检测业务，不得进行商业贿赂；\n4. 应按规定公开检测机构的基本信息、资质能力、检测收费等。", "basis": "《建设工程质量检测管理办法》\n《检验检测机构诚信基本要求》（GB/T 31880）"}, {"seq": 22, "point": "检测安全与环保管理", "content": "1. 试验检测单位应建立检测安全和环保管理制度；\n2. 试验室应配备必要的安全防护设施和消防器材；\n3. 危险化学品应按规定采购、储存、使用和处置，建立台账；\n4. 试验废弃物（废液、废渣等）应分类收集、妥善处置，不得随意排放。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《危险化学品安全管理条例》"}, {"seq": 23, "point": "检测分包管理", "content": "1. 当检测机构需要将部分检测项目分包时，分包方应具备相应资质和能力；\n2. 分包前应书面通知委托方并征得委托方同意；\n3. 分包检测项目应在检测报告中注明分包方名称和资质编号；\n4. 检测机构应对分包检测结果负责，并对分包方进行评价和管理。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》"}, {"seq": 24, "point": "检测报告修改与更正管理", "content": "1. 检测报告出具后发现错误的，检测机构应及时书面通知委托方；\n2. 报告更正应按规定程序进行，经审批后重新出具检测报告并注明「更正」字样；\n3. 原检测报告应收回或声明作废，更正后的报告应与原报告一并存档；\n4. 不得以任何方式掩盖或隐瞒检测报告的差错。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》第十四条"}, {"seq": 25, "point": "检测原始记录管理", "content": "1. 原始记录应在检测过程中同步记录，内容应完整、清晰、真实；\n2. 原始记录应使用不易褪色的笔填写，修改应规范（杠改并签名）；\n3. 原始记录不得事后誊抄或伪造，电子记录应有防篡改措施；\n4. 原始记录应按检测项目分类归档，保存期限不少于规定年限。", "basis": "《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）\n《建设工程质量检测管理办法》第十六条"}, {"seq": 26, "point": "检测结果争议处理", "content": "1. 委托方对检测结果有异议时，检测机构应认真复核原始记录和检测过程；\n2. 必要时可在双方见证下重新取样检测或委托第三方检测机构进行仲裁检测；\n3. 争议处理过程应有书面记录，处理结果应及时告知委托方；\n4. 确属检测机构责任的，检测机构应承担相应责任并采取纠正预防措施。", "basis": "《建设工程质量检测管理办法》\n《检验检测机构资质认定能力评价 检验检测机构通用要求》（RB/T 214）"}, {"seq": 27, "point": "检测机构变更管理", "content": "1. 检测机构变更名称、地址、法定代表人、技术负责人等事项的，应及时向资质许可机关申请办理变更手续；\n2. 变更期间不得影响正常检测业务的开展和检测质量；\n3. 关键岗位人员（技术负责人、质量负责人等）变更应确保新任人员资格满足要求；\n4. 检测场所变更的，新场所应经评审合格后方可开展检测业务。", "basis": "《建设工程质量检测管理办法》\n《检验检测机构资质认定管理办法》"}]}]}, {"id": "quality_ch2", "title": "质量篇-第2章-现场施工工艺监督要点", "category": "质量篇", "sheets": [{"name": "2.1.1 路基土石方工程", "items": [{"seq": 1, "point": "清表与基底处理", "content": "原地表清理彻底，清除草皮、树根、腐殖土；基底压实度满足设计要求", "basis": "①清除路基用地范围内的树木、灌木丛，砍伐后的树根应挖除并填平夯实；②清表厚度一般不小于30cm，清表后应碾压密实；③基底有地下水时应采取排水措施，确保基底干燥；④斜坡地段应挖台阶，台阶宽度不小于2m"}, {"seq": 2, "point": "路堑开挖方式", "content": "分层开挖，自上而下逐层施工，严禁掏底开挖", "basis": "①土方路堑开挖采用「横向分层、纵向分段」施工；②每层开挖高度宜为3-5m，开挖一级防护一级；③石方路堑应采用光面爆破或预裂爆破，控制超挖和振动；④爆破后应及时清渣，检查边坡稳定情况"}, {"seq": 3, "point": "边坡坡度控制", "content": "边坡坡率符合设计，坡面平顺、无松石危石", "basis": "①土质边坡坡率允许偏差不大于设计值的±3%；②石质边坡坡面不应有松石，危石需清除或加固；③变坡点位置及平台宽度严格按设计施工；④边坡应随开挖随防护，防止雨水冲刷"}, {"seq": 4, "point": "排水沟设置", "content": "截水沟与开挖同步，临时排水与永久排水结合", "basis": "①路堑顶部截水沟应在开挖前完成，防止地表水流入开挖面；②开挖过程中设置临时排水沟，确保工作面不积水；③排水沟断面尺寸不小于设计值，沟底纵坡满足排水要求"}, {"seq": 5, "point": "基底承载力检验", "content": "挖到设计标高后检验基底承载力", "basis": "①路堑基底到达设计标高后，应核查地质情况是否与设计一致；②基底承载力不足时应采取换填、压实等措施；③基底检测频率每100m不少于2点，关键部位加密"}, {"seq": 6, "point": "填料选择与控制", "content": "填料CBR值、最大粒径符合规范要求", "basis": "①上路床（0-30cm）填料CBR≥8%，下路床（30-80cm）CBR≥5%；②上路堤（80-150cm）填料CBR≥4%，下路堤（>150cm）CBR≥3%；③填料最大粒径：路床≤100mm，路堤≤150mm；④液限大于50%、塑性指数大于26的土不得直接作为路堤填料"}, {"seq": 7, "point": "分层填筑厚度", "content": "严格控制松铺厚度和压实遍数", "basis": "①松铺厚度根据试验段确定，一般土方≤300mm，石方≤500mm；②填石路堤最大粒径不宜超过层厚的2/3；③填土路基每层压实后厚度一般不超过200mm；④不同填料应分层填筑，不得混填"}, {"seq": 8, "point": "压实度检测", "content": "逐层检测压实度，不合格不得上土", "basis": "①压实度检测频率：每1000m²至少检测2点；②上路床压实度≥96%，下路床≥96%，上路堤≥94%，下路堤≥93%（高速公路标准）；③压实度不合格应补压直至合格方可填筑下一层；④灌砂法或环刀法检测，关键部位用核子密度仪辅助快速检测"}, {"seq": 9, "point": "填挖交界处理", "content": "填挖结合部应开挖台阶并加强压实", "basis": "①纵向填挖交界处应开挖宽度不小于2m的台阶；②填挖交界处每填筑一定高度应进行强夯或冲击碾压补强；③横向半填半挖路段应铺设土工格栅加强连接"}, {"seq": 10, "point": "路堤沉降观测", "content": "按规定频率进行沉降和位移观测", "basis": "①高填方路堤、软土路基等应设置沉降观测桩；②填筑期间每填筑一层观测一次，填筑完成后每月不少于1次；③沉降速率：一般路段≤5mm/日，桥头路段≤3mm/日方可进行后续施工"}, {"seq": 11, "point": "砂料质量", "content": "砂料应为中粗砂，含泥量≤5%", "basis": "①砂垫层应采用级配良好的中粗砂，细度模数≥2.3；②含泥量（小于0.075mm颗粒）不得超过5%；③有机质含量不得超过1%；④不得含有草根、树皮等杂物"}, {"seq": 12, "point": "铺设厚度与范围", "content": "砂垫层厚度和宽度满足设计要求", "basis": "①砂垫层厚度一般为30-80cm，偏差不超过±5cm；②铺设宽度应超出路基坡脚每侧各0.5-1.0m；③铺设应均匀平整，无局部凹凸"}, {"seq": 13, "point": "压实与排水", "content": "砂垫层压实并确保排水通畅", "basis": "①砂垫层应分层铺设、分层压实，每层厚度≤300mm；②压实后密实度应达到中密状态（相对密度≥0.67）；③砂垫层应与排水沟或排水管连通，确保排水出路通畅"}, {"seq": 14, "point": "砂垫层保护", "content": "防止砂垫层被污染或破坏", "basis": "①砂垫层铺设后应及时覆盖，防止雨水冲刷和杂物混入；②后续施工机械不得直接在砂垫层上行驶造成扰动；③在砂垫层上铺设土工布时应平整无褶皱"}, {"seq": 15, "point": "砂袋材料质量", "content": "砂袋强度和渗透性符合要求", "basis": "①砂袋宜采用聚丙烯编织布，单位面积质量≥90g/m²；②砂袋抗拉强度：纵向≥10kN/m，横向≥8kN/m；③砂袋的等效孔径O90宜为0.07-0.5mm；④灌入的中粗砂含泥量≤3%"}, {"seq": 16, "point": "砂井直径与间距", "content": "砂井直径、间距和深度符合设计", "basis": "①袋装砂井直径一般为70-120mm；②砂井间距一般为1.0-2.0m，呈梅花形或正方形布置；③砂井深度应穿透软土层，打入下卧硬层≥0.5m；④位置偏差≤50mm，垂直度偏差≤1.5%"}, {"seq": 17, "point": "施工工艺控制", "content": "沉入方式正确，灌砂密实", "basis": "①砂袋灌砂应饱满，灌砂率≥95%；②沉管施工时应严格控制垂直度；③砂袋应沉入到设计深度，管口应设防回带装置；④拔管后砂袋不应有断裂、缩颈现象"}, {"seq": 18, "point": "砂垫层连通", "content": "袋装砂井顶部与水平砂垫层连通良好", "basis": "①砂袋露出砂垫层表面长度≥300mm，并埋入砂垫层中；②确保竖向排水体与水平排水体有效连通，形成完整排水系统"}, {"seq": 19, "point": "排水板材料", "content": "排水板芯板与滤膜质量合格", "basis": "①排水板芯板的通水量≥20cm³/s（侧向压力350kPa条件下）；②滤膜渗透系数≥5×10⁻³cm/s；③滤膜等效孔径O95<0.075mm；④排水板抗拉强度：干态≥1.5kN/100mm，湿态≥1.0kN/100mm"}, {"seq": 20, "point": "排水板间距与深度", "content": "插板间距和深度偏差控制", "basis": "①排水板间距一般为1.0-2.0m，正三角形或正方形布置；②插板深度应穿透软土层进入下卧层≥0.5m；③平面位置偏差≤50mm；④垂直度偏差≤1.5%，深度不应小于设计值"}, {"seq": 21, "point": "插板施工控制", "content": "插板机施工参数控制", "basis": "①插板机锚杆应保证垂直，插板过程中不得扭曲排水板；②回带长度≤300mm，回带严重的应重新补插；③排水板外露长度≥300mm，并埋入砂垫层；④排水板不得接长，如需接长应采用专用接头"}, {"seq": 22, "point": "排水板保护", "content": "防止排水板损坏和污染", "basis": "①排水板在运输和储存过程中应避免阳光直晒和雨淋；②施工中避免机械碾压和杂物堵塞滤膜；③插设后应及时覆盖砂垫层"}, {"seq": 23, "point": "桩体材料", "content": "碎石、砂等粒料级配和强度要求", "basis": "①碎石粒径宜为20-50mm，含泥量≤5%；②碎石的压碎值≤30%；③粒料中可适当掺入砂或石屑以改善级配；④材料进场每批次检验级配和含泥量"}, {"seq": 24, "point": "桩径与桩距", "content": "桩径、桩距和桩长偏差控制", "basis": "①桩径允许偏差：振动沉管法±20mm，锤击沉管法±30mm；②桩距允许偏差≤100mm；③桩长不小于设计值；④桩位偏差≤0.25倍桩径"}, {"seq": 25, "point": "施工工艺控制", "content": "沉管、投料、拔管参数控制", "basis": "①沉管应垂直，倾斜度≤1.5%；②投料应分批进行，每批投料量使管内碎石面高于地面；③拔管速度：振动沉管≤1.0m/min，锤击沉管≤0.8m/min；④拔管过程中应保持管内碎石面高度"}, {"seq": 26, "point": "成桩质量检验", "content": "桩身密实度和承载力检测", "basis": "①成桩后7-14天进行重型动力触探检验桩身密实度；②检验数量：不少于总桩数的2‰且不少于3根；③桩间土加固效果应通过静力触探或标准贯入试验检验"}, {"seq": 27, "point": "褶垫层施工", "content": "桩顶褶垫层铺设质量", "basis": "①褶垫层材料宜采用中粗砂或碎石，厚度一般为300-500mm；②铺设应均匀平整；③褶垫层应分层压实，压实度符合设计要求"}]}, {"name": "2.1.2 排水工程", "items": [{"seq": 1, "point": "管节质量", "content": "管节强度、规格、外观质量检查", "basis": "①管节混凝土强度等级不低于设计值，出厂时提供合格证及强度报告；②管节内外表面应平整、无蜂窝麻面、裂缝；③管节尺寸偏差：内径±5mm，壁厚-3mm/+5mm，长度±10mm；④进场管节逐节检查外观质量，并按批次进行强度抽检"}, {"seq": 2, "point": "管道铺设", "content": "管道基础、坡度、接口质量控制", "basis": "①管道基础应平整密实，地基承载力满足设计要求；②管道坡度偏差≤±0.1%，且不得出现反坡；③管道中心线偏差≤30mm；④管道底高程偏差±20mm"}, {"seq": 3, "point": "管节接口", "content": "接口严密不漏水，柔性接口处理到位", "basis": "①承插接口间隙均匀，橡胶密封圈位置正确、无扭曲；②抹带接口应饱满密实、无裂缝；③接口完成后做闭水试验，渗水量≤设计允许值；④接口处不得有错台，相邻管节错台≤5mm"}, {"seq": 4, "point": "回填土施工", "content": "管道两侧对称回填，分层夯实", "basis": "①管道两侧及管顶以上500mm范围内应对称回填，高差≤200mm；②回填土不得含有石块、硬块；③每层松铺厚度≤200mm，压实度≥90%；④管顶以上500mm后方可采用机械碾压"}, {"seq": 5, "point": "检查与验收", "content": "管道功能性试验", "basis": "①排水管道应逐段进行闭水试验或闭气试验；②闭水试验水头不低于管顶以上2m，渗水量不超过规范允许值；③管道内不得有杂物堵塞，排水通畅"}, {"seq": 6, "point": "井体结构与尺寸", "content": "检查井位置、尺寸符合设计", "basis": "①检查井位置偏差≤20mm；②井身尺寸偏差：圆形井直径±20mm，矩形井边长±20mm；③井底高程偏差±15mm；④井壁垂直度偏差≤0.3%"}, {"seq": 7, "point": "井壁与砌筑", "content": "井壁砌筑质量和强度", "basis": "①砖砌检查井：砂浆饱满度≥80%，水平灰缝≤12mm，竖缝≤10mm；②混凝土检查井：混凝土强度等级≥C25，模板安装牢固；③井壁内外应抹面，抹面厚度≥15mm，表面光滑无裂缝"}, {"seq": 8, "point": "井盖与井座", "content": "井盖承载力等级和安装", "basis": "①车行道检查井盖承载等级≥D400（400kN）；②井盖与井座应配套，安装后井盖面与路面高差：沥青路面≤5mm，其他路面≤10mm；③井盖应设防震圈，行车无跳响"}, {"seq": 9, "point": "流槽与管口连接", "content": "井内流槽砌筑，管口伸入尺寸", "basis": "①检查井内应设流槽，流槽高度应与管内顶平；②管道伸入检查井内壁长度：混凝土管≤50mm，金属管≤100mm；③管口与井壁采用柔性密封，防止渗漏"}, {"seq": 10, "point": "闭水试验", "content": "带井闭水，整体检验", "basis": "①检查井应与管道一同进行闭水试验；②闭水试验时，井内水位不低于井筒高度的1/3；③允许渗水量应符合规范规定"}, {"seq": 11, "point": "沟槽开挖", "content": "断面尺寸和纵坡控制", "basis": "①沟底宽度和深度偏差±30mm；②沟底纵坡应与设计一致，不得出现反坡和积水；③沟壁边坡坡率允许偏差±3%；④不允许超挖，局部超挖应用原状土回填夯实"}, {"seq": 12, "point": "沟底处理", "content": "沟底平整，排水通畅", "basis": "①沟底应平整顺直，不得有松散土块；②沟底应夯实，压实度≥85%；③沟底不得有杂物堵塞，排水断面不受阻碍"}, {"seq": 13, "point": "边坡修整", "content": "沟壁拍实，边坡平顺无坍塌", "basis": "①沟壁边坡应采用人工拍实，坡面平整；②边坡不得有松散土体和裂缝；③草皮护坡应紧贴沟壁，草籽发芽率≥85%"}, {"seq": 14, "point": "与涵洞排水沟衔接", "content": "衔接平顺，水流畅通", "basis": "①土沟与涵洞进出口衔接处应平顺过渡，不得有突变；②衔接处应设铺砌保护，防止冲刷；③汇入天然沟渠时应有消能措施"}, {"seq": 15, "point": "砌体材料", "content": "石料和砂浆质量要求", "basis": "①片石厚度≥150mm，表面洁净无风化；②砂浆强度等级≥M7.5，配合比计量准确；③块石应加工方正，厚度≥200mm；④水泥砂浆随拌随用，超过初凝时间不得使用"}, {"seq": 16, "point": "砌筑质量", "content": "砌筑方法和砂浆饱满度", "basis": "①砌筑前石料应湿润，基底应清理干净；②砂浆饱满度≥80%，上下层错缝≥80mm；③沉降缝设置位置准确，缝宽一致，填缝密实；④面石应平整，大面朝下，砌缝宽度：片石≤40mm，块石≤30mm"}, {"seq": 17, "point": "沟底与沟壁尺寸", "content": "断面尺寸偏差控制", "basis": "①沟底高程偏差±20mm；②沟底宽度偏差±30mm；③沟壁厚度偏差：设计厚度≥400mm时，偏差-20mm/+30mm；④表面平整度：2m直尺检查≤20mm"}, {"seq": 18, "point": "勾缝与养护", "content": "勾缝质量和养护措施", "basis": "①勾缝砂浆强度≥M10，勾缝前应剔缝，缝深≥20mm；②勾缝应光滑、平整、牢固，无脱落和裂缝；③砌筑完成后应及时覆盖洒水养护，养护时间≥7天"}, {"seq": 19, "point": "盲沟材料", "content": "碎石、滤料质量和级配", "basis": "①碎石粒径宜为30-80mm，洁净无风化；②含泥量≤3%，针片状含量≤15%；③反滤层土工布的单位面积质量≥300g/m²，渗透系数≥1×10⁻¹cm/s；④滤料级配应满足保土性和透水性要求"}, {"seq": 20, "point": "盲沟开挖与断面", "content": "沟槽深度、宽度和纵坡", "basis": "①盲沟深度应在地下水最高水位以下≥0.5m；②沟底纵坡≥1%，确保排水通畅；③断面尺寸偏差±20mm；④沟底和沟壁应修整平顺"}, {"seq": 21, "point": "滤料填筑", "content": "滤料分层填筑，厚度均匀", "basis": "①碎石盲沟的碎石分两层填筑，下层为粗碎石，上层为细碎石；②土工布包裹应严密，搭接宽度≥200mm；③滤料填筑应分层进行，每层≤300mm"}, {"seq": 22, "point": "出水口处理", "content": "出水口保护与消能", "basis": "①盲沟出水口应高出排水沟最高水位≥200mm；②出水口应设碎石或砌石保护，防止冲刷；③寒冷地区出水口应设防冻措施"}, {"seq": 23, "point": "跌水结构尺寸", "content": "跌水台阶高度和宽度控制", "basis": "①跌水台阶高度一般≤300mm，偏差±20mm；②跌水宽度偏差±30mm；③跌水底板厚度符合设计，偏差-10mm/+20mm；④消力池深度和长度偏差±50mm"}, {"seq": 24, "point": "砌筑或浇筑质量", "content": "混凝土或圬工施工质量", "basis": "①混凝土强度等级符合设计，浇筑振捣密实；②圬工砌筑砂浆饱满度≥80%；③跌水壁应垂直，垂直度偏差≤0.5%"}, {"seq": 25, "point": "消能设施", "content": "消力池或消力坎施工", "basis": "①消力池底板应水平，高程偏差±20mm；②消力坎高度和位置偏差±20mm；③跌水与上下游沟渠衔接平顺，不产生严重冲刷"}, {"seq": 26, "point": "防冲刷措施", "content": "进出口防护及抛石处理", "basis": "①跌水进、出口应设铺砌防护，长度≥3m；②抛石粒径≥200mm，铺设厚度≥300mm；③有水流跌落的沟底应进行加固处理"}]}, {"name": "2.1.3 涵洞通道工程", "items": [{"seq": 1, "point": "钢筋原材料", "content": "钢筋牌号、规格、外观及力学性能", "basis": "①钢筋应有出厂合格证和复试报告，每60t一批次检验；②钢筋表面不应有裂纹、折叠、结疤、油污；③直径、肋高、间距等尺寸偏差符合国标要求；④屈服强度、抗拉强度、伸长率和冷弯性能满足要求"}, {"seq": 2, "point": "钢筋加工尺寸", "content": "下料长度和弯钩角度精确", "basis": "①受力钢筋下料长度偏差±10mm；②弯起钢筋弯折位置偏差±20mm；③箍筋内净尺寸偏差±5mm；④弯钩角度：一般135°（抗震），末端平直段长度≥10d"}, {"seq": 3, "point": "钢筋连接", "content": "焊接或机械连接质量", "basis": "①焊接接头：外观无裂纹、气孔、烧伤；搭接焊焊缝长度：单面焊≥10d，双面焊≥5d；②机械连接：套筒应有型式检验报告，接头拧紧力矩符合要求；③接头位置应避开受力最大处，同一断面接头百分率≤50%"}, {"seq": 4, "point": "钢筋绑扎与定位", "content": "绑扎牢固，保护层垫块设置", "basis": "①钢筋交叉点均应绑扎牢固，不可松脱；②保护层垫块间距：底板≤1.0m，侧壁≤1.5m；③保护层厚度允许偏差：底板+10mm/-0mm，侧壁+5mm/-0mm；④钢筋间距偏差：排距±5mm，间距±10mm"}, {"seq": 5, "point": "预埋件及预留孔", "content": "预埋件位置准确，预留孔尺寸正确", "basis": "①预埋钢板平整度≤3mm/m，位置偏差≤10mm；②预埋螺栓外露长度偏差+10mm/-0mm，垂直度偏差≤2%；③预留孔中心位置偏差≤10mm，孔径偏差+10mm/-0mm"}, {"seq": 6, "point": "模板安装", "content": "模板强度和刚度，拼缝严密", "basis": "①模板应有足够刚度和稳定性，接缝严密不漏浆；②模板表面平整度≤3mm/2m；③模板垂直度偏差≤H/1000且≤20mm；④模板内净尺寸偏差±10mm"}, {"seq": 7, "point": "混凝土浇筑", "content": "混凝土配合比、振捣和养护", "basis": "①混凝土配合比应经批准，坍落度偏差±20mm；②浇筑自由倾落高度≤2m，分层厚度≤300mm；③振捣应快插慢拔，间距≤振捣半径1.5倍；④浇筑完成后12h内覆盖洒水养护，养护≥7天"}, {"seq": 8, "point": "涵台尺寸偏差", "content": "断面尺寸、垂直度和高程控制", "basis": "①涵台高度偏差±20mm；②涵台顶面高程偏差±10mm；③涵台轴线偏位≤10mm；④涵台断面尺寸偏差±10mm"}, {"seq": 9, "point": "沉降缝设置", "content": "沉降缝位置和填缝质量", "basis": "①沉降缝位置按设计设置，偏差≤20mm；②沉降缝应上下贯通、缝宽一致（一般20-30mm）；③填缝材料应按设计选用（沥青麻絮、橡胶止水带等），填塞密实；④沉降缝处混凝土面应平整，无错台"}, {"seq": 10, "point": "模板与钢筋", "content": "模板就位与钢筋保护层", "basis": "①底模应平整，预拱度按设计设置（一般L/500）；②钢筋保护层垫块梅花形布置，间距≤800mm；③受力钢筋间距偏差±10mm，保护层厚度偏差±5mm"}, {"seq": 11, "point": "混凝土浇筑与养护", "content": "浇筑顺序与养护质量", "basis": "①盖板浇筑应从一端向另一端连续进行，不得留施工缝；②振捣充分，表面收浆抹平；③终凝后覆盖洒水养护≥14天；④混凝土强度达到设计强度75%以上方可拆除底模"}, {"seq": 12, "point": "盖板安装", "content": "吊装就位和支座处理", "basis": "①盖板安装前检查涵台顶面高程和平整度；②支座处应铺设油毛毡或橡胶垫板，平整密贴；③盖板就位后与涵台间缝隙用砂浆填实；④相邻盖板间错台≤10mm"}, {"seq": 13, "point": "盖板尺寸偏差", "content": "外形尺寸检查", "basis": "①盖板长度偏差+10mm/-5mm；②盖板宽度偏差±10mm；③盖板厚度偏差+10mm/-5mm；④盖板底面平整度≤5mm/2m"}, {"seq": 14, "point": "地基与垫层", "content": "基底承载力与垫层施工", "basis": "①基底承载力应达到设计要求，软基应预先处理；②砂砾垫层厚度偏差±20mm，夯实密实；③混凝土垫层强度等级≥C15，厚度偏差±10mm"}, {"seq": 15, "point": "钢筋与模板", "content": "整体式箱涵钢筋骨架质量", "basis": "①钢筋骨架尺寸偏差：长度±10mm，宽度±5mm，高度±5mm；②内外模应有足够刚度，防止胀模；③模板脱模剂涂刷均匀，不得污染钢筋；④倒角模板安装准确"}, {"seq": 16, "point": "混凝土浇筑", "content": "连续浇筑与防裂措施", "basis": "①箱涵分两次浇筑：先底板及部分侧墙，后剩余侧墙及顶板；②施工缝应凿毛并清洗干净，浇筑前铺同标号砂浆10-20mm；③顶板浇筑后应二次收面，防止开裂"}, {"seq": 17, "point": "预制箱涵拼装", "content": "节段拼装精度控制", "basis": "①预制箱涵节段尺寸偏差控制在±10mm以内；②节段拼装时应保证轴线一致，错台≤5mm；③节段间防水胶条应粘贴牢固、位置正确；④拼装后用预应力钢绞线张拉连接，张拉力符合设计"}, {"seq": 18, "point": "涵背回填", "content": "两侧对称回填，压实度控制", "basis": "①涵背回填应在涵体强度达到设计强度100%后方可进行；②两侧应对称分层回填，高差≤300mm；③回填材料宜用砂砾或碎石等透水性材料；④压实度：路堤区≥96%，每层检测不少于2点"}, {"seq": 19, "point": "砌筑材料", "content": "石料、砂浆质量控制", "basis": "①料石厚度≥200mm，强度等级≥MU30；②砂浆强度等级≥M10，配合比计量准确；③砌筑前石料湿润，砂浆随拌随用"}, {"seq": 20, "point": "墙体尺寸", "content": "墙身尺寸和位置偏差", "basis": "①墙体长度偏差±30mm；②墙体厚度偏差：设计厚度≥400mm时，偏差-20mm/+30mm；③墙顶高程偏差±20mm；④墙面垂直度偏差≤0.5%墙高"}, {"seq": 21, "point": "砌筑质量", "content": "砌缝与砂浆饱满度", "basis": "①砂浆饱满度≥80%，上下错缝≥80mm；②面石平整，大面朝下；③砌缝宽度：片石≤40mm，块石≤30mm；④沉降缝设置位置准确，缝宽一致"}, {"seq": 22, "point": "与涵台衔接", "content": "衔接紧密，整体性好", "basis": "①一字墙/八字墙与涵台连接处的砌筑应紧密，无通缝；②连接处钢筋或锚栓按设计设置；③墙后回填应分层夯实"}, {"seq": 23, "point": "填土时机", "content": "涵洞强度达到要求后方可填土", "basis": "①盖板涵和箱涵的涵身混凝土强度达到设计强度100%后方可填土；②拱涵的拱圈强度达到设计强度100%后填土，且拱上填土高度≥1m前不得机械碾压"}, {"seq": 24, "point": "填土材料", "content": "填土材料要求", "basis": "①涵洞两侧及顶部的填土应采用透水性良好的砂砾或碎石；②填料最大粒径≤50mm，且不应有尖锐棱角；③不得使用膨胀土、腐殖土和冻土"}, {"seq": 25, "point": "填筑方法", "content": "分层对称填筑，高差控制", "basis": "①涵洞两侧应对称分层填筑，每层≤200mm，两侧高差≤300mm；②压实机具：两侧用小型夯实机，顶部≥1m后可上压路机；③涵洞顶部填土厚度≥1m方可允许重型车辆通行"}, {"seq": 26, "point": "压实度控制", "content": "逐层检测压实度", "basis": "①高速公路、一级公路涵洞回填压实度≥96%；②每层每侧至少检测2个点；③涵顶填土50cm范围内压实度≥90%"}, {"seq": 27, "point": "沉降观测", "content": "高填方涵洞的沉降监测", "basis": "①高填方涵洞（填土高度>8m）应设置沉降观测点；②填筑期间每填筑2m观测一次，填筑完成后每月观测一次；③月沉降量≤3mm认为稳定"}]}, {"name": "2.1.4 防护支挡工程", "items": [{"seq": 1, "point": "基底检验", "content": "基底承载力与埋置深度", "basis": "①基底承载力应不小于设计值，达不到时应进行换填或加固；②基底埋置深度：土质地基≥1.0m，软岩≥0.5m，硬岩≥0.3m；③基底倾斜度≤2%，基底不得浸水"}, {"seq": 2, "point": "墙身砌筑/浇筑", "content": "砌石或混凝土施工质量", "basis": "①浆砌片石挡墙：砂浆饱满度≥80%，上下错缝≥80mm；②混凝土挡墙：强度等级符合设计，浇筑分层厚度≤300mm；③墙身表面平整度≤30mm/2m；④泄水孔应按设计设置，间距2-3m，孔径≥50mm，向外坡度≥4%"}, {"seq": 3, "point": "墙背回填", "content": "回填材料与压实", "basis": "①墙背回填应采用透水性好的砂砾或碎石；②分层回填厚度≤200mm，压实度≥95%；③泄水孔附近应设反滤层，粒径自上而下由细到粗；④回填与墙体砌筑协调进行"}, {"seq": 4, "point": "沉降缝与伸缩缝", "content": "缝的设置与填缝", "basis": "①沉降缝间距：砌石挡墙10-15m，混凝土挡墙15-20m；②缝宽20-30mm，缝内填塞沥青麻絮或橡胶止水带；③缝应上下贯通，缝宽一致"}, {"seq": 5, "point": "墙身尺寸偏差", "content": "几何尺寸检查", "basis": "①墙顶高程偏差±20mm；②墙身断面尺寸偏差±30mm；③墙面垂直度偏差≤0.5%墙高且≤30mm；④轴线偏位≤20mm"}, {"seq": 6, "point": "锚杆/锚索材料", "content": "材料规格和力学性能", "basis": "①锚杆钢筋型号、直径符合设计，抗拉强度≥设计值；②锚索钢绞线强度等级一般为1860MPa，松弛率≤2.5%；③锚具、夹片应有出厂合格证和检验报告；④防腐保护层完好，油脂饱满"}, {"seq": 7, "point": "钻孔施工", "content": "孔位、孔深、孔径和倾角控制", "basis": "①孔位偏差≤50mm；②孔深≥设计值，孔径≥设计值；③钻孔倾角偏差≤±1°；④钻孔后应清孔，孔内不得残留岩粉和积水"}, {"seq": 8, "point": "锚杆/锚索安装与注浆", "content": "安装质量和注浆密实度", "basis": "①锚杆应居中放置，每隔2m设一个对中支架；②注浆管随锚杆一同放入孔底，由孔底向上注浆；③注浆压力0.3-0.5MPa，灌浆应饱满，注浆量≥理论值的1.2倍；④浆液强度等级≥M30，水灰比0.38-0.45"}, {"seq": 9, "point": "张拉与锁定", "content": "张拉力控制和锁定", "basis": "①注浆体强度达到设计强度75%后方可张拉；②张拉分级：0→10%→50%→100%→110%→锁定（110%持荷5-10min）；③锁定荷载偏差≤±5%；④张拉后48h内观测预应力损失，损失≥10%应补张拉"}, {"seq": 10, "point": "封锚与防护", "content": "锚头保护", "basis": "①张拉锁定后48h内切除多余的钢绞线，外留≥30mm；②锚头用混凝土封闭保护，厚度≥100mm；③混凝土保护层强度等级≥C30，并进行防腐处理"}, {"seq": 11, "point": "桩孔开挖", "content": "开挖方法与安全措施", "basis": "①抗滑桩应采用人工挖孔或机械成孔，严禁爆破；②孔口应设锁口，锁口高出地面≥200mm；③开挖深度每开挖1m应及时支护，护壁混凝土强度≥C20；④孔内通风、照明和排水措施到位"}, {"seq": 12, "point": "钢筋笼制作安装", "content": "钢筋笼质量和就位精度", "basis": "①钢筋笼尺寸偏差：长度±50mm，直径±10mm；②主筋间距偏差±10mm，箍筋间距偏差±20mm；③钢筋笼入孔应垂直，保护层厚度≥50mm；④钢筋笼接长采用焊接或机械连接，接头错开"}, {"seq": 13, "point": "桩身混凝土浇筑", "content": "连续浇筑与桩身质量", "basis": "①浇筑前孔底清理干净，无积水和杂物；②导管法浇筑，导管底距孔底300-500mm；③连续浇筑不得中断，导管埋深2-6m；④每桩至少留3组试块"}, {"seq": 14, "point": "桩身完整性检测", "content": "低应变检测或超声波检测", "basis": "①每根抗滑桩均应进行低应变完整性检测；②检测龄期不少于7天；③Ⅰ类桩≥95%，无Ⅲ、Ⅳ类桩；④缺陷桩应进行取芯验证或补强处理"}, {"seq": 15, "point": "桩间挡土板", "content": "挡土板安装与回填", "basis": "①挡土板预制质量符合设计，强度达到100%后方可安装；②挡土板与桩的连接牢固，缝隙用砂浆填实；③板后回填分层夯实，压实度≥95%"}, {"seq": 16, "point": "筋带材料", "content": "筋带（土工格栅/钢带）质量", "basis": "①土工格栅抗拉强度、延伸率符合设计，老化试验合格；②钢带镀锌厚度≥85μm，焊缝强度≥母材；③筋带不应有破损、老化、锈蚀等缺陷；④每批次进场材料抽样检验"}, {"seq": 17, "point": "面板安装", "content": "预制面板质量和安装精度", "basis": "①面板混凝土强度等级≥C30，尺寸偏差±5mm；②面板安装垂直度偏差≤H/500且≤15mm；③面板间接缝宽度≤10mm，缝内填塞沥青麻絮；④面板后应设反滤层"}, {"seq": 18, "point": "筋带铺设", "content": "筋带长度、间距和铺设方向", "basis": "①筋带长度不小于设计值，间距偏差±20mm；②筋带应垂直于墙面铺设，方向偏差≤±2°；③筋带应拉紧铺设，不可有松弛和扭曲；④筋带搭接长度≥1.0m，用连接棒穿连"}, {"seq": 19, "point": "填料与压实", "content": "加筋区填料和压实", "basis": "①填料应选砂性土或碎石土，最大粒径≤2/3层厚且≤150mm；②分层铺设厚度≤300mm，距面板1.5m范围内用小型机具压实；③压实度≥95%，每层每500m²检测不少于2点"}, {"seq": 20, "point": "墙面排水", "content": "排水系统有效性", "basis": "①墙后应设排水层（碎石或土工复合排水材料），厚度≥300mm；②泄水孔间距2-3m，底部第一排泄水孔距地面≥200mm；③排水设施通畅，墙后不得积水"}, {"seq": 21, "point": "锚杆施工", "content": "锚杆孔位、深度和注浆", "basis": "①锚杆孔位偏差≤50mm，孔径≥设计值；②锚杆深度≥设计值，倾角偏差≤±2°；③注浆饱满，M30水泥浆，水灰比0.38-0.45；④锚杆拉拔力试验：每300根抽检不少于3根，拉拔力≥设计值"}, {"seq": 22, "point": "支撑绳安装", "content": "支撑绳规格和张拉", "basis": "①钢丝绳规格符合设计（一般ϕ16-ϕ18），无断丝和锈蚀；②支撑绳用不少于3个绳卡固定，绳卡间距≥钢丝绳直径6倍；③张力适度，不松弛也不过紧"}, {"seq": 23, "point": "防护网铺设", "content": "网片搭接和连接", "basis": "①防护网片应覆盖整个防护区域，搭接宽度≥100mm；②网片与支撑绳用缝合绳或卸扣连接，间距≤500mm；③网片应紧贴坡面，不得悬空；④格栅网孔径及钢丝直径符合设计"}, {"seq": 24, "point": "覆盖范围与锚固", "content": "防护范围及边界锚固", "basis": "①防护范围应超出不稳定区域每侧≥2.0m；②边界锚杆或锚索的间距≤1.5m；③防护网底部应埋入坡脚沟槽中，深度≥300mm"}]}, {"name": "2.2 路面工程", "items": [{"seq": 1, "point": "材料质量", "content": "砂砾或碎石级配和含泥量", "basis": "①天然砂砾：最大粒径≤53mm，通过0.075mm筛孔的含量≤8%；②碎石：压碎值≤40%，含泥量≤5%；③塑性指数≤6；④材料应按批次检验级配"}, {"seq": 2, "point": "摊铺与整平", "content": "松铺系数和摊铺平整度", "basis": "①松铺系数根据试验段确定，一般为1.3-1.5；②厚度允许偏差：代表值-10mm，合格值-25mm；③表面平整度≤15mm/3m直尺；④宽度不小于设计值"}, {"seq": 3, "point": "压实控制", "content": "碾压遍数和压实度", "basis": "①先用轻型压路机稳压，再用重型压路机碾压；②碾压遍数按试验段确定，压实度≥96%（高速公路）；③碾压从路肩向路中心进行，轮迹重叠1/3-1/2轮宽；④表面无明显轮迹和松散"}, {"seq": 4, "point": "混合料配合比", "content": "配合比计量和含水量控制", "basis": "①水泥稳定类：水泥剂量偏差±0.5%，含水量+1%/-0.5%；②石灰稳定类：石灰剂量偏差±1%，含水量±1%；③级配碎石：级配偏差不超过规范范围；④每工班至少检验1次配合比"}, {"seq": 5, "point": "摊铺施工", "content": "连续摊铺，控制离析", "basis": "①摊铺厚度按松铺系数控制，松铺系数由试验段确定；②横向接缝应垂直相接，纵向接缝采用热接缝；③摊铺过程中避免离析，粗集料窝应人工翻拌；④摊铺宽度：每幅3.5-8m，多幅搭接100-200mm"}, {"seq": 6, "point": "压实与养生", "content": "压实度检测与养生管理", "basis": "①碾压应在水泥初凝前完成；②压实度检测频率：每200m每年道1处，压实度代表值≥98%；③水泥稳定类养生期≥7天，养生期间封闭交通洒水保湿；④石灰稳定类养生期≥7天，不得用水浸泡"}, {"seq": 7, "point": "弯沉值检测", "content": "弯沉代表值满足设计要求", "basis": "①基层养生期满后进行弯沉检测；②弯沉代表值≤设计值；③检测频率：每车道每20m测1点；④不合格路段应进行补强处理"}, {"seq": 8, "point": "层间结合", "content": "透层/封层施工", "basis": "①半刚性基层顶面应喷洒透层油，渗透深度≥5mm；②沥青面层间喷洒粘层油，用量0.3-0.5L/m²；③封层厚度均匀，石料覆盖率≥80%"}, {"seq": 9, "point": "原材料质量", "content": "沥青、集料和填料检验", "basis": "①道路石油沥青针入度、软化点、延度等指标符合标号要求；②粗集料压碎值≤26%（上面层）或28%（中下面层），磨光值≥42；③细集料砂当量≥60%；④矿粉亲水系数<1，塑性指数<4"}, {"seq": 10, "point": "配合比设计", "content": "目标配合比与生产配合比", "basis": "①马歇尔试验确定最佳油石比，空隙率3-5%；②车辙试验动稳定度：普通路段≥1000次/mm，上坡路段≥3000次/mm；③浸水马歇尔残留稳定度≥80%，冻融劈裂强度比≥75%"}, {"seq": 11, "point": "拌和与运输", "content": "拌和温度与时间控制", "basis": "①普通沥青混合料拌和温度150-170℃，改性沥青170-185℃；②干拌时间≥5s，湿拌时间≥30s；③运输车应覆盖保温，到场温度≥145℃；④不得有花白料和结团"}, {"seq": 12, "point": "摊铺与碾压", "content": "连续摊铺与碾压工艺", "basis": "①摊铺温度≥135℃（普通）或≥155℃（改性）；②初压温度≥130℃（普通）或≥150℃（改性），终压温度≥80℃；③碾压组合：初压钢轮2遍→复压胶轮4-6遍→终压钢轮2遍；④压实度≥96%（马氏标准密度），平整度σ≤1.2mm"}, {"seq": 13, "point": "接缝处理", "content": "纵横接缝质量", "basis": "①纵向热接缝：跨缝碾压，必要时加热软化；②横向接缝：垂直平接，接缝处涂粘层油并加热；③接缝处平整度≤3mm/3m直尺"}, {"seq": 14, "point": "原材料与配合比", "content": "水泥、集料、外加剂质量", "basis": "①水泥：道路硅酸盐水泥或普通硅酸盐水泥，强度≥42.5MPa；②粗集料压碎值≤15%，针片状≤15%；③水灰比≤0.44，水泥用量≥300kg/m³（无抗冰冻要求）或320kg/m³（有抗冰冻要求）；④弯拉强度标准值≥5.0MPa"}, {"seq": 15, "point": "模板与传力杆", "content": "模板安装和钢筋设置", "basis": "①模板安装牢固、顺直，高程偏差±5mm，宽度偏差±10mm；②传力杆、拉杆位置偏差：间距±20mm，距板边±10mm；③传力杆应与路面中心线平行，拉杆应与路面中心线垂直"}, {"seq": 16, "point": "混凝土浇筑与振捣", "content": "浇筑连续性及振捣质量", "basis": "①浇筑应连续，间断时间≤混凝土初凝时间；②振捣应充分，振动棒间距≤450mm，振捣时间15-30s/点；③三辊轴整平机或滑模摊铺机施工；④表面应做抗滑构造，纹理深度0.8-1.2mm"}, {"seq": 17, "point": "切缝与养护", "content": "切缝时机与养护方式", "basis": "①切缝应在混凝土强度达到设计强度25-30%时进行（一般8-24h）；②切缝深度：设传力杆时≥1/3板厚，不设时≥1/4板厚；③养护：喷洒养护剂或覆盖洒水，养护期≥14天"}, {"seq": 18, "point": "填缝与质量检验", "content": "填缝材料与成品检验", "basis": "①填缝槽应干燥清洁，填缝料灌注饱满、与缝壁粘结良好；②板厚代表值偏差-5mm；③平整度σ≤1.5mm；④相邻板高差≤3mm；⑤弯拉强度28天龄期≥设计值"}, {"seq": 19, "point": "路缘石预制/现浇", "content": "路缘石尺寸和安装", "basis": "①预制路缘石强度≥C25，尺寸偏差：长±5mm，宽±3mm，高±3mm；②安装顺直度：10m拉线偏差≤5mm；③相邻块高差≤3mm；④现浇路缘石模板顺直，混凝土振捣密实"}, {"seq": 20, "point": "路缘石线形", "content": "平面位置与高程控制", "basis": "①路缘石顶面高程偏差±10mm；②路缘石平面位置偏差≤20mm；③圆角处路缘石切割安装平顺，曲线过渡自然"}, {"seq": 21, "point": "路肩施工", "content": "土路肩和硬路肩质量", "basis": "①土路肩压实度≥90%，高于路面部分应铲平；②硬路肩（沥青或水泥）施工质量同主线面层；③路肩横坡应大于路面横坡0.5-1%，不得存水；④路肩边缘应整齐，宽度偏差+50mm/-20mm"}, {"seq": 22, "point": "培土路肩与植草", "content": "路肩培土和绿化", "basis": "①培土路肩填土压实度≥90%；②草皮铺设应紧贴土面，缝隙用土填实；③草籽撒播均匀，覆盖率≥90%"}]}, {"name": "2.3.1 桥梁-基础及下部构造", "items": [{"seq": 1, "point": "钢筋原材料", "content": "钢筋牌号、规格、性能检验", "basis": "①钢筋应有出厂合格证和复试报告，每60t一批次；②钢筋外观无裂纹、结疤、油污；③HRB400钢筋：屈服强度≥400MPa，抗拉强度≥540MPa，伸长率≥16%；④环氧涂层钢筋涂层厚度0.18-0.30mm，无破损"}, {"seq": 2, "point": "钢筋加工", "content": "下料、弯制和连接", "basis": "①受力钢筋下料长度偏差±10mm；②弯起钢筋弯起点位置偏差±20mm；③箍筋弯钩角度135°，平直段长度≥10d且≥75mm；④机械连接接头等级Ⅰ级或Ⅱ级，现场抽检合格"}, {"seq": 3, "point": "钢筋安装", "content": "间距、保护层及绑扎", "basis": "①受力钢筋间距偏差：两排以上排距±5mm，同排±10mm；②箍筋间距偏差±20mm；③保护层厚度偏差：基础±10mm，墩台±5mm；④垫块密度：每平米≥4个，梅花形布置"}, {"seq": 4, "point": "预埋件", "content": "预埋螺栓和钢板", "basis": "①预埋螺栓中心位置偏差≤5mm，外露长度偏差+10mm/-0mm；②预埋钢板平整度≤3mm/m，与混凝土面贴合紧密"}, {"seq": 5, "point": "钢绞线/精轧螺纹钢", "content": "材料检验与存放", "basis": "①钢绞线每批≤60t，检验抗拉强度、屈服强度、伸长率、松弛率；②精轧螺纹钢每批≤100t，检验力学性能；③存放应架空防潮，不得锈蚀和污染；④下料长度偏差：钢绞线±30mm，精轧螺纹钢±10mm"}, {"seq": 6, "point": "波纹管安装", "content": "管道位置和密封", "basis": "①波纹管位置偏差：梁长方向±30mm，梁高方向±10mm；②波纹管接头用大一号的波纹管套接，密封胶带封严；③管道应平顺，弯折处曲率半径≥设计值；④灌浆孔和排气孔设置位置正确"}, {"seq": 7, "point": "预应力张拉", "content": "张拉力和伸长量双控", "basis": "①张拉时混凝土强度≥设计强度的90%且龄期≥7天；②张拉顺序按设计，先中心后两侧，先下后上；③张拉控制应力σcon≤0.75fpk；④实测伸长值与理论值偏差≤±6%；⑤持荷时间≥5min"}, {"seq": 8, "point": "孔道压浆", "content": "压浆密实度和强度", "basis": "①压浆应在张拉后48h内完成；②浆液水灰比0.26-0.28，流动度10-17s；③压浆压力：一般0.5-0.7MPa，排气孔流出浓浆后封闭持压≥3min；④压浆强度≥M40，饱满无空洞"}, {"seq": 9, "point": "封锚", "content": "锚头封闭保护", "basis": "①切割钢绞线外留长度≥30mm；②锚穴凿毛清洗干净；③封锚混凝土强度等级不低于构件，分层捣实；④封锚后不得有裂纹"}, {"seq": 10, "point": "桩位与护筒", "content": "桩位放样与护筒埋设", "basis": "①桩位偏差：群桩≤100mm，排架桩≤50mm；②护筒内径大于桩径200-300mm；③护筒埋深：黏土≥1.0m，砂土≥2.0m，高出地面0.3m；④护筒中心偏差≤50mm，倾斜度≤1%"}, {"seq": 11, "point": "钻孔施工", "content": "泥浆指标与钻孔控制", "basis": "①泥浆比重：正循环1.10-1.30，反循环1.05-1.15；②黏度：一般地层16-22s，松散地层19-28s；③含砂率：新制泥浆≤4%；④孔深≥设计值，孔径≥设计值；⑤钻孔倾斜度≤1%"}, {"seq": 12, "point": "清孔", "content": "孔底沉渣厚度控制", "basis": "①摩擦桩沉渣厚度≤200mm；②端承桩（含嵌岩桩）沉渣厚度≤50mm；③清孔后泥浆含砂率≤2%，比重1.03-1.10；④二次清孔后30min内浇筑混凝土"}, {"seq": 13, "point": "钢筋笼与混凝土浇筑", "content": "钢筋笼下放与水下混凝土", "basis": "①钢筋笼接长时主筋焊接轴线一致；②导管水密试验合格，导管底距孔底300-500mm；③混凝土坍落度180-220mm，初始流动性好；④导管埋深2-6m，连续浇筑不中断；⑤桩顶超灌高度≥0.5m"}, {"seq": 14, "point": "成桩检测", "content": "桩身完整性检测", "basis": "①每根桩做低应变动测，必要时做超声波检测；②Ⅰ类桩≥95%，无Ⅲ/Ⅳ类桩；③检测龄期≥7天；④承载力有疑问时做静载试验或高应变检测"}, {"seq": 15, "point": "孔口防护", "content": "锁口施工与安全防护", "basis": "①锁口混凝土强度≥C20，高出地面≥200mm，宽度≥400mm；②孔口周围设防护栏杆，高度≥1.2m；③孔内设爬梯或安全绳，照明电压≤12V；④每日开工前通风检测，CO₂浓度≤0.5%，无有毒气体"}, {"seq": 16, "point": "挖孔与护壁", "content": "分段开挖与护壁质量", "basis": "①每节开挖深度≤1.0m，开挖后及时支护；②护壁混凝土强度≥C20，厚度≥100mm；③护壁应高出上一节≥50mm搭接；④孔壁岩石较好时可不支护，但需设计确认"}, {"seq": 17, "point": "终孔检验", "content": "孔底地质核查与尺寸", "basis": "①孔深≥设计值，孔径≥设计值；②孔底岩土层与设计一致，必要时由地勘确认；③倾斜度≤0.5%，孔底平整无松散物；④孔内无积水"}, {"seq": 18, "point": "桩身混凝土", "content": "干浇混凝土质量控制", "basis": "①浇筑前孔底晾干或抽干，不得有积水；②自由倾落高度≤2m，否则设串筒；③分层浇筑，每层≤500mm，振捣密实；④桩顶超灌高度≥0.3m，凿除浮浆"}, {"seq": 19, "point": "成桩检测", "content": "桩身完整性与承载力", "basis": "①每根桩做完整性检测；②桩位偏差≤50mm；③桩径偏差≥设计值；④桩身混凝土强度达到设计要求"}, {"seq": 20, "point": "基坑开挖与检验", "content": "基坑尺寸与基底处理", "basis": "①基坑尺寸大于承台尺寸每侧≥0.5m（有模板）或≥0.3m（无模板）；②基底承载力满足设计要求；③基坑排水设施到位，基底不得浸泡；④超挖部分不得用虚土回填"}, {"seq": 21, "point": "钢筋绑扎", "content": "钢筋位置和保护层", "basis": "①受力钢筋间距偏差±20mm；②桩头钢筋锚入承台长度≥设计值；③保护层垫块间距≤1.0m，梅花形布置；④预埋墩身钢筋位置偏差≤10mm"}, {"seq": 22, "point": "模板与混凝土", "content": "大体积混凝土温控", "basis": "①模板安装牢固，接缝严密；②大体积承台应分层浇筑，每层≤500mm；③应埋设冷却管（厚度≥2m时），进水温度与混凝土内部温差≤20℃；④混凝土内外温差≤25℃，升降温速率≤2℃/d"}, {"seq": 23, "point": "尺寸偏差", "content": "承台外形尺寸", "basis": "①承台断面尺寸偏差±30mm；②承台顶面高程偏差±20mm；③轴线偏位≤15mm；④表面平整度≤8mm/2m"}, {"seq": 24, "point": "模板安装", "content": "模板精度与预埋件", "basis": "①墩身模板采用定型钢模，拼缝严密；②垂直度偏差≤H/1000且≤20mm；③模板轴线偏位≤10mm；④预埋件位置偏差≤10mm"}, {"seq": 25, "point": "混凝土浇筑", "content": "浇筑方法与养护", "basis": "①墩身自由倾落高度≤2m，设串筒或减速装置；②分层浇筑厚度≤300mm，振捣密实；③混凝土浇筑应连续，施工缝按设计设置；④拆模后即用塑料薄膜包裹或涂层养护，养护≥7天"}, {"seq": 26, "point": "墩台外观", "content": "表面质量和色差控制", "basis": "①表面平整、色泽均匀，无明显色差；②无蜂窝麻面、砂线、冷缝等缺陷；③模板接缝处无错台，错台≤2mm；④表面气泡面积≤20cm²/m²"}, {"seq": 27, "point": "尺寸偏差", "content": "墩台外形尺寸检查", "basis": "①墩台高度偏差±20mm；②断面尺寸偏差±20mm；③顶面高程偏差±10mm；④轴线偏位≤10mm（墩）或15mm（台）"}, {"seq": 28, "point": "支座垫石", "content": "垫石尺寸与平整度", "basis": "①垫石混凝土强度≥C40；②垫石顶面高程偏差±5mm；③垫石四角高差≤1mm；④垫石顶面平整度≤2mm/m²；⑤预留锚栓孔位置偏差≤5mm"}]}, {"name": "2.3.2-2.3.3 桥梁-上部构造", "items": [{"seq": 1, "point": "预制场地与台座", "content": "台座强度和反拱", "basis": "①台座基础应牢固，不均匀沉降≤2mm；②台座反拱值按设计设置（一般L/2000-L/3000）；③台座表面平整度≤2mm/2m；④底模每次使用前应清理并涂脱模剂"}, {"seq": 2, "point": "钢筋与预应力", "content": "钢筋绑扎及预应力施工", "basis": "①钢筋保护层垫块间距≤500mm，梅花形布置；②波纹管线形顺直，定位筋间距：直线段≤1m，曲线段≤0.5m；③张拉采用双控，伸长量偏差≤±6%；④孔道压浆饱满密实"}, {"seq": 3, "point": "混凝土浇筑与养护", "content": "浇筑工艺与养生", "basis": "①浇筑方向：从一端向另一端斜向分层；②振捣充分，特别注意锚下和波纹管周围；③顶板应拉毛处理，粗糙度≥2mm；④蒸汽养护时升降温速率≤10℃/h，恒温≤60℃"}, {"seq": 4, "point": "梁板安装", "content": "吊装就位和支座安放", "basis": "①梁板起吊时混凝土强度≥设计强度的90%；②支座垫石应清洁，支座就位准确、平稳；③梁板安装后相邻梁板顶面高差≤10mm；④伸缩缝处梁端间距符合设计"}, {"seq": 5, "point": "湿接缝/横隔板", "content": "现浇连接质量", "basis": "①湿接缝钢筋焊接或连接前应除锈；②模板与预制梁板密贴，不漏浆；③混凝土强度等级不低于预制梁板，浇筑振捣密实；④养护及时，保持湿润≥7天"}, {"seq": 6, "point": "支架搭设", "content": "支架基础和搭设质量", "basis": "①支架基础应坚实，必要时做硬化处理；②支架搭设应符合专项方案，间距、步距偏差≤50mm；③可调托撑伸出长度≤300mm，插入立杆长度≥150mm；④预压：预压荷载≥1.1倍梁体自重，预压时间≥48h"}, {"seq": 7, "point": "模板与钢筋", "content": "模板安装精度", "basis": "①底模高程偏差±10mm（考虑支架变形和预拱度）；②侧模垂直度偏差≤H/1000且≤10mm；③钢筋安装位置偏差符合规范要求；④模板接缝严密不漏浆"}, {"seq": 8, "point": "混凝土浇筑", "content": "浇筑顺序与防裂", "basis": "①浇筑应从跨中向两端或由低向高进行；②分层厚度≤300mm，连续浇筑不中断；③浇筑后二次收面压实，初凝前覆盖保湿；④养护用水温度与混凝土表面温差≤15℃"}, {"seq": 9, "point": "预应力施工", "content": "张拉与压浆", "basis": "①张拉时混凝土强度≥设计强度90%且弹性模量≥设计值80%；②张拉顺序按设计，一般为对称张拉；③压浆应在张拉完成后48h内完成"}, {"seq": 10, "point": "支架拆除", "content": "落架顺序与安全", "basis": "①落架时混凝土强度≥设计强度100%；②落架应分级、对称、均匀进行；③先跨中后两端或先从一端向另一端逐步卸落；④落架过程中监测梁体位移和裂缝"}, {"seq": 11, "point": "墩顶0#块施工", "content": "临时锚固与0#块质量", "basis": "①墩顶临时锚固（固结）按设计实施，预应力筋张拉到位；②0#块模板支撑牢固，尺寸偏差±10mm；③0#块混凝土一次浇筑或按设计分段，振捣密实"}, {"seq": 12, "point": "挂篮拼装与行走", "content": "挂篮安全和使用", "basis": "①挂篮安装后应进行加载试验，加载≥1.2倍施工荷载；②挂篮行走前确认锚固体系安全可靠；③行走速度≤1.0m/min，两侧对称同步；④挂篮就位后及时锚固"}, {"seq": 13, "point": "节段混凝土浇筑", "content": "节段对称施工", "basis": "①两端悬臂节段应同时对称浇筑，不平衡荷载≤设计值；②节段接缝应凿毛清洗干净，混凝土浇筑振捣密实；③预应力管道位置精确，接口严密不漏浆"}, {"seq": 14, "point": "合龙段施工", "content": "合龙温度与锁定", "basis": "①合龙段长度一般为2m，合龙前两侧梁端高差≤10mm；②合龙温度宜在设计合龙温度（一般15-18℃）下进行；③合龙段锁定劲性骨架安装牢固，焊接迅速完成；④合龙段混凝土应用微膨胀混凝土，浇筑后及时养护"}, {"seq": 15, "point": "线形监控", "content": "施工过程线形控制", "basis": "①每个节段浇筑和张拉后测量高程和轴线；②梁体线形偏差：高程±20mm，轴线±10mm；③发现偏差超限应及时分析原因并调整下一节段立模标高"}, {"seq": 16, "point": "拱架/拱胎", "content": "拱架搭设与预压", "basis": "①拱架应有足够刚度和稳定性，基础坚实；②拱架预压荷载≥1.1倍拱圈自重+施工荷载；③拱架按设计预留拱度（一般为L/500-L/800）；④预压后调整拱架线形至设计线形"}, {"seq": 17, "point": "拱圈（主拱）浇筑", "content": "分段对称浇筑", "basis": "①拱圈浇筑应分段、对称、均衡进行；②分段长度和浇筑顺序按方案执行；③分段间间隔槽应在各段混凝土达到设计强度75%后浇筑；④拱圈合龙温度宜在5-15℃"}, {"seq": 18, "point": "钢管拱（如有）", "content": "钢管加工与混凝土灌注", "basis": "①钢管焊缝应100%超声波检测，节段拼接精度控制；②管内混凝土应采用微膨胀混凝土（膨胀率0.02%-0.04%）；③管内混凝土泵送顶升，应连续施工，确保密实无空洞"}, {"seq": 19, "point": "拱上建筑", "content": "立柱/横墙与拱上填料", "basis": "①拱上建筑应在拱圈合龙且强度达到100%后施工；②拱上立柱/横墙应对称施工；③拱上填料应分层夯实，压实度≥90%；④施工过程中监测拱圈变形"}]}, {"name": "2.3.4 桥梁-桥面系及附属", "items": [{"seq": 1, "point": "基层处理", "content": "桥面基层清理与修补", "basis": "①桥面基层应清洁干燥，无浮浆、油污和松散物；②用抛丸机或高压水枪处理，粗糙度0.5-1.5mm；③基层裂缝、孔洞应修补平整；④阴阳角处应做圆弧过渡（R≥50mm）"}, {"seq": 2, "point": "防水涂料施工", "content": "涂料喷涂质量", "basis": "①防水涂料按产品说明配制，用量≥设计值；②喷涂应均匀覆盖、无漏涂、无气泡；③涂层厚度：一般≥1.5mm（分2-3遍涂刷）；④每遍间隔时间：表干不粘手即可下一遍"}, {"seq": 3, "point": "防水卷材施工", "content": "卷材铺设质量", "basis": "①卷材铺设方向：纵桥向顺水搭接，搭接宽度≥100mm；②搭接部位应热熔或粘结牢固，无空鼓翘边；③卷材应与基层满粘，黏结面积≥90%；④接缝处应做附加层处理"}, {"seq": 4, "point": "防水层检测", "content": "粘结强度和闭水试验", "basis": "①粘结强度检测：每500m²测1处，粘结强度≥0.3MPa；②闭水试验：蓄水深度≥20mm，24h无渗漏；③防水层完成后及时覆盖沥青铺装层保护"}, {"seq": 5, "point": "混凝土铺装", "content": "钢筋网与混凝土施工", "basis": "①钢筋网保护层厚度：上侧≥20mm，下侧≥30mm；②混凝土强度等级≥C40，坍落度100-140mm；③铺装层厚度偏差：-5mm/+10mm；④表面平整度≤3mm/3m直尺"}, {"seq": 6, "point": "沥青铺装", "content": "沥青混合料摊铺与碾压", "basis": "①粘层油喷洒均匀，用量0.3-0.5L/m²；②摊铺温度≥150℃（改性沥青）；③压实度≥96%，平整度σ≤1.2mm；④横坡偏差±0.3%"}, {"seq": 7, "point": "铺装层与桥面结合", "content": "层间粘结质量", "basis": "①混凝土桥面板顶面应凿毛或拉毛，粗糙度≥2mm；②防水粘结层喷洒均匀，用量准确；③铺装层不得有空鼓和脱层现象"}, {"seq": 8, "point": "泄水孔设置", "content": "泄水管安装与排水坡度", "basis": "①泄水管位置和数量按设计设置；②泄水管管口应低于铺装层表面5-10mm；③铺装层排水坡度按设计，不得积水"}, {"seq": 9, "point": "支座进场检验", "content": "支座类型、规格及外观", "basis": "①支座应有出厂合格证和型式检验报告；②板式橡胶支座：外观无裂纹、气泡、钢板外露；③盆式支座：滑动面清洁无锈蚀，聚四氟乙烯板完好；④每批支座抽样进行力学性能检验"}, {"seq": 10, "point": "支座安装", "content": "支座就位和调平", "basis": "①支座垫石高程偏差±5mm，四角高差≤1mm；②支座就位后中心位置偏差≤5mm；③支座与垫石之间用环氧砂浆找平或座浆；④支座安装温度考虑温度修正量"}, {"seq": 11, "point": "支座上下连接", "content": "支座与梁底及垫石连接", "basis": "①板式橡胶支座：与梁底和垫石密贴，无脱空；②盆式支座：上下钢板与混凝土面用螺栓或套筒连接牢固；③支座安装后应立即灌注地脚螺栓孔或锚栓孔"}, {"seq": 12, "point": "支座功能检验", "content": "支座受力与变形", "basis": "①安装后检查支座受力均匀，无偏压；②活动支座滑动面应涂硅脂润滑；③落梁后支座压缩变形均匀，无异常变形"}, {"seq": 13, "point": "伸缩缝进场", "content": "型号、规格与外观", "basis": "①伸缩缝型号与设计图纸一致；②型钢材质满足要求，焊缝无裂纹；③伸缩缝出厂时预压缩或预拉伸量标识清晰；④附件（锚固钢筋、密封条等）齐全"}, {"seq": 14, "point": "预埋与安装", "content": "预留槽口处理与安装精度", "basis": "①预留槽口宽度和深度符合产品要求；②伸缩缝中心线偏差≤10mm；③型钢顶面与桥面铺装面高差≤2mm；④锚固钢筋与预留钢筋焊接牢固"}, {"seq": 15, "point": "混凝土浇筑", "content": "槽口混凝土回填", "basis": "①槽口混凝土强度等级≥C50钢纤维混凝土或环氧混凝土；②浇筑前槽口应凿毛清理干净，涂界面剂；③浇筑振捣密实，与沥青铺装接缝平顺；④混凝土养护≥7天，强度达到100%后方可通车"}, {"seq": 16, "point": "功能检验", "content": "伸缩量及行车舒适性", "basis": "①安装后伸缩量满足设计要求；②行车通过时无明显跳车，伸缩缝两侧高差≤2mm；③止水密封条安装牢固，不渗水"}, {"seq": 17, "point": "护栏钢筋与模板", "content": "钢筋绑扎和模板安装", "basis": "①护栏钢筋与梁体预埋钢筋焊接或连接牢固；②钢筋间距和保护层符合设计要求；③模板拼缝严密，线形顺直，10m拉线偏差≤5mm"}, {"seq": 18, "point": "混凝土浇筑", "content": "护栏混凝土施工", "basis": "①护栏混凝土一般与桥面铺装同时或先后浇筑；②分层浇筑振捣，特别注意模板边角处振捣密实；③表面收浆抹平，气泡≤10个/m²；④养护及时，覆盖保湿≥7天"}, {"seq": 19, "point": "线形与外观", "content": "护栏外观质量", "basis": "①护栏线形顺直，圆角过渡自然；②表面光滑，无蜂窝麻面和裂缝；③接缝处错台≤2mm；④高度偏差±5mm，宽度偏差±3mm"}, {"seq": 20, "point": "伸缩缝与断开", "content": "护栏断开与过渡", "basis": "①护栏在桥梁伸缩缝处应断开，断开宽度与伸缩缝一致；②护栏与路基护栏应过渡衔接；③护栏断口处应有圆角处理"}]}, {"name": "2.4 隧道工程", "items": [{"seq": 1, "point": "边仰坡开挖", "content": "自上而下开挖，及时防护", "basis": "①洞口边仰坡开挖应符合设计要求，严禁掏底开挖；②开挖一级、防护一级，不得一挖到底；③边坡稳定监测：位移速率≤2mm/d；④截水沟应在边仰坡开挖前施工完成"}, {"seq": 2, "point": "套拱与管棚", "content": "套拱施工和管棚超前支护", "basis": "①套拱混凝土强度等级≥C25，基础承载力满足要求；②管棚钢管直径一般为89-159mm，壁厚≥5mm；③管棚钻孔偏斜≤1%，方向与隧道轴线平行；④管棚注浆压力0.5-1.0MPa，注浆饱满"}, {"seq": 3, "point": "明洞施工", "content": "明洞开挖、衬砌和回填", "basis": "①明洞开挖基底承载力满足设计要求；②明洞衬砌厚度和钢筋符合设计；③明洞两侧回填应对称进行，压实度≥85%；④洞顶回填土厚度≥1.5m方可恢复植被"}, {"seq": 4, "point": "洞口防护", "content": "洞口排水与坡面防护", "basis": "①洞口截排水系统完善，无积水；②坡面防护（喷锚、植草等）质量合格；③洞口边坡无开裂和变形"}, {"seq": 5, "point": "开挖方法", "content": "台阶法/CRD/CD法等", "basis": "①开挖方法应符合经批准的专项方案；②台阶长度：上台阶≤5m，下台阶≤8m；③CD法/CRD法中隔壁厚度≥200mm，喷射混凝土密实；④各分部开挖掌子面间距≥3m"}, {"seq": 6, "point": "爆破控制", "content": "光面爆破和预裂爆破", "basis": "①周边眼间距：Ⅳ级围岩≤400mm，Ⅲ级围岩≤450mm，Ⅱ级围岩≤500mm；②光面爆破炮眼痕迹率：硬岩≥80%，中硬岩≥60%；③超挖值：拱部≤150mm，边墙≤100mm；④爆破振动速度≤设计值（一般≤30mm/s）"}, {"seq": 7, "point": "初期支护", "content": "锚杆+钢拱架+喷射混凝土", "basis": "①锚杆长度、间距符合设计，锚杆安装后24h内注浆；②钢拱架间距偏差±50mm，拱脚基础坚实；③喷射混凝土厚度≥设计值，平均厚度≥设计厚度，最小厚度≥0.5倍设计厚度；④喷射混凝土强度等级≥C25，与围岩粘结强度≥0.5MPa"}, {"seq": 8, "point": "监控量测", "content": "必测项目与频率", "basis": "①必测项目：洞内外观察、拱顶下沉、周边收敛、地表沉降；②量测频率：距掌子面0-1B时2次/d，1-2B时1次/d，2-5B时1次/2d，>5B时1次/周；③拱顶下沉速率≤3mm/d，累计≤100mm（根据围岩级别调整）"}, {"seq": 9, "point": "超前地质预报", "content": "地质预报方法", "basis": "①TSP超前地质预报：每100-150m一次；②超前钻探：每30-50m一次，钻孔深度≥30m；③地质雷达：短距离预报，每次探测20-30m；④发现异常地质应及时反馈并调整施工方案"}, {"seq": 10, "point": "防水层施工", "content": "防水板铺设质量", "basis": "①防水板厚度≥1.2mm（EVA/ECB等），进场检验合格；②铺设前基面平整度：D/L≤1/6（矢跨比）；③防水板搭接宽度≥100mm，双焊缝焊接，充气检验0.25MPa/15min不降；④防水板无破损，修补处贴补丁"}, {"seq": 11, "point": "钢筋施工", "content": "衬砌钢筋绑扎", "basis": "①主筋间距偏差±10mm，两层钢筋间距偏差±5mm；②保护层垫块间距≤1.0m，保护层厚度偏差：内侧-5mm/+10mm，外侧+5mm/-10mm；③钢筋与防水板间设保护垫块，防止刺破防水板"}, {"seq": 12, "point": "模板台车", "content": "模板台车就位和精度", "basis": "①台车模板表面平整清洁，脱模剂涂刷均匀；②台车就位：中心线偏差≤10mm，高程偏差±10mm；③台车模板与已衬砌搭接长度≥100mm，搭接处严密不漏浆"}, {"seq": 13, "point": "混凝土浇筑", "content": "浇筑和振捣", "basis": "①混凝土坍落度160-200mm，泵送浇筑；②两侧对称浇筑，高差≤500mm；③拱顶采用挤压式灌注，确保拱顶密实无空洞；④脱模强度：不承受荷载时≥5MPa，承受荷载时≥设计强度70%"}, {"seq": 14, "point": "衬砌质量检测", "content": "厚度、密实度和强度检测", "basis": "①衬砌厚度用地质雷达检测，每10m一组，厚度≥设计值；②回弹法或钻芯法检测混凝土强度≥设计值；③拱顶空洞检测：每20m检测一次，空洞高度≤100mm"}, {"seq": 15, "point": "环向/纵向排水管", "content": "排水管安装", "basis": "①环向排水管间距按设计（一般5-10m），布置在防水板背后；②纵向排水管坡度≥1%，与环向排水管三通连接畅通；③排水管接头严密不渗漏，包裹无纺布作反滤层"}, {"seq": 16, "point": "中心排水沟", "content": "中心排水沟施工", "basis": "①中心排水沟位置偏差≤20mm，坡度与隧道纵坡一致；②排水管/沟接头严密，管底高程偏差±10mm；③检查井间距按设计，一般50-100m"}, {"seq": 17, "point": "止水带设置", "content": "施工缝和沉降缝止水", "basis": "①环向施工缝设中埋式止水带+背贴式止水带；②止水带应居中放置，中线偏差≤10mm；③止水带接头应热硫化连接，搭接长度≥100mm；④浇筑混凝土时防止止水带移位和破损"}, {"seq": 18, "point": "排水效果检验", "content": "隧道防排水效果", "basis": "①隧道内无渗漏、无滴漏、无湿渍；②排水系统通畅，排水量满足设计要求；③防水板充气试验和闭水试验合格"}, {"seq": 19, "point": "基层施工", "content": "隧道内路面基层", "basis": "①隧道内路面基层材料与洞外一致，配合比准确；②摊铺和压实符合规范要求，压实度≥98%；③基层平整度≤10mm/3m直尺"}, {"seq": 20, "point": "面层施工", "content": "水泥混凝土或沥青面层", "basis": "①水泥混凝土路面：弯拉强度≥5.0MPa，抗滑构造深度0.8-1.2mm；②沥青路面：压实度≥96%，平整度σ≤1.2mm；③隧道进出口段路面抗滑性能应加强；④施工期间隧道内通风换气≥3次/h"}, {"seq": 21, "point": "路面排水", "content": "路面排水设施", "basis": "①路面横坡1.5-2%，汇入边沟；②边沟盖板安装平整，承载力满足要求；③清洗时应检查排水边沟是否堵塞"}, {"seq": 22, "point": "与洞外路面衔接", "content": "过渡段处理", "basis": "①隧道进出口路面应与洞外路面平顺衔接；②衔接处平整度≤3mm/3m直尺；③进出口路面颜色和抗滑性能与洞外协调"}]}, {"name": "2.5-2.6 声屏障及交通安全设施", "items": [{"seq": 1, "point": "标志板材料", "content": "反光膜等级与铝板质量", "basis": "①标志板铝板厚度≥设计值（一般2-3mm），表面平整无划痕；②反光膜等级：高速公路一般用Ⅳ类或Ⅴ类（超强级或钻石级），国省道用Ⅲ类及以上；③反光膜粘贴平整无气泡，粘结牢固"}, {"seq": 2, "point": "标志立柱与基础", "content": "立柱垂直度和基础质量", "basis": "①标志立柱垂直度偏差≤10mm/m；②基础混凝土强度≥C25，顶面平整；③法兰盘与基础螺栓连接紧固；④立柱镀锌层厚度≥85μm，无漏镀"}, {"seq": 3, "point": "标志安装位置", "content": "位置和角度控制", "basis": "①标志位置偏差：里程方向≤30m，横向≤100mm；②标志板内缘距土路肩边缘≥250mm；③标志板安装角度：垂直于行车方向，路侧标志板面法线与道路中线夹角：指路标志0°，警告/禁令标志3-5°"}, {"seq": 4, "point": "标志视认性", "content": "视认距离和净空高度", "basis": "①标志板下缘距路面高度：悬臂式5.5-6.0m，门架式≥5.5m；②标志视认距离应满足在相应车速下能清晰辨认；③标志不得被树木、广告牌等遮挡"}, {"seq": 5, "point": "标线材料", "content": "热熔/冷喷/双组分材料", "basis": "①热熔标线涂料软化点90-120℃，密度1.8-2.3g/cm³；②玻璃珠折射率≥1.5，成圆率≥80%；③冷喷标线涂料黏度适宜，干燥时间≤15min（常温）；④每批材料应提供检测报告"}, {"seq": 6, "point": "标线施工", "content": "标线施划质量", "basis": "①标线施划前路面应清洁干燥；②热熔标线施工温度180-220℃；③标线厚度：热熔型1.5-2.5mm，冷喷型0.3-0.4mm；④玻璃珠撒布均匀，嵌入深度≥玻璃珠直径的50%"}, {"seq": 7, "point": "标线线形与尺寸", "content": "线形和位置控制", "basis": "①标线线形顺直，宽度偏差：设计宽度≤150mm时±5mm，>150mm时±10mm；②纵向间距偏差：实线±10mm/10m，虚线±20mm/10m；③标线位置偏差±20mm"}, {"seq": 8, "point": "逆反射性能", "content": "反光标线亮度检测", "basis": "①白色标线逆反射亮度系数≥150mcd·m⁻²·lx⁻¹（干燥状态）；②黄色标线逆反射亮度系数≥100mcd·m⁻²·lx⁻¹（干燥状态）；③标线磨损后应重新施划"}, {"seq": 9, "point": "波形梁护栏", "content": "立柱和护栏板安装", "basis": "①立柱埋深≥设计值（一般1400mm），间距偏差±20mm；②立柱垂直度偏差≤10mm/m；③波形梁板搭接方向应与行车方向一致；④护栏板中心高度偏差±10mm；⑤螺栓连接紧固，扭矩符合要求"}, {"seq": 10, "point": "混凝土护栏", "content": "滑模或预制安装", "basis": "①混凝土强度等级≥C30，钢筋位置和保护层符合设计；②混凝土护栏线形顺直，10m拉线偏差≤10mm；③接缝处无错台，错台≤5mm；④伸缩缝处护栏应断开，与桥梁伸缩缝协调"}, {"seq": 11, "point": "护栏端头处理", "content": "端头和外展处理", "basis": "①护栏起始端应设外展式端头或防撞消能端头；②端头锚固牢固，螺栓连接可靠；③端头应贴反光膜，夜间视认性良好"}, {"seq": 12, "point": "护栏过渡段", "content": "不同护栏形式衔接", "basis": "①波形梁与混凝土护栏过渡段长度≥设计值；②桥梁护栏与路基护栏应设过渡段连接；③过渡段护栏强度不应低于相邻护栏"}, {"seq": 13, "point": "防眩板/网", "content": "材料与尺寸", "basis": "①防眩板厚度≥2.5mm，高度按设计（一般700-900mm）；②防眩板颜色一般为绿色或灰黑色，耐候性良好；③防眩网网孔尺寸和丝径按设计，表面热浸镀锌处理"}, {"seq": 14, "point": "安装质量", "content": "间距和垂直度", "basis": "①防眩板间距偏差±10mm；②防眩板垂直度偏差≤5mm/m；③防眩板安装高度偏差±10mm；④与护栏或桥梁连接螺栓紧固不松动"}, {"seq": 15, "point": "防眩效果", "content": "遮光角和连续遮蔽", "basis": "①防眩设施安装后遮光角≥设计值（一般8-15°）；②防眩设施不得出现漏光段；③曲线段防眩设施应加密设置"}, {"seq": 16, "point": "隔离栅材料", "content": "网片和立柱质量", "basis": "①编织网/焊接网丝径和网孔尺寸符合设计；②立柱壁厚≥设计值（一般≥2.5mm），热浸镀锌≥275g/m²；③刺铁丝规格：主丝ϕ2.8mm，刺丝ϕ2.2mm，刺距100mm"}, {"seq": 17, "point": "立柱基础与安装", "content": "基础施工和网片张拉", "basis": "①立柱埋深≥设计值（一般500mm），间距偏差±20mm；②混凝土基础尺寸符合设计；③网片张拉紧绷，与立柱连接牢固；④隔离栅高度偏差±20mm"}, {"seq": 18, "point": "隔离栅线形", "content": "平面位置与线形", "basis": "①隔离栅中心线平面位置偏差≤50mm；②隔离栅线形顺直，10m拉线偏差≤20mm；③纵向坡度与地形协调，底部距地面≤50mm"}, {"seq": 19, "point": "出入口与搭接", "content": "门洞和端头处理", "basis": "①隔离栅每个养护工区设可开启门，门扇开关灵活；②隔离栅端头应锚固于建筑物或专门设置的端柱；③隔离栅与桥梁、涵洞等结构物有效连接"}, {"seq": 20, "point": "基础施工", "content": "条形基础或桩基础", "basis": "①基础承载力满足设计要求，开挖尺寸准确；②钢筋绑扎和预埋件位置偏差≤10mm；③混凝土强度等级≥C25，振捣密实；④基础顶面高程偏差±10mm，预埋螺栓垂直度≤2%"}, {"seq": 21, "point": "立柱安装", "content": "H型钢立柱就位", "basis": "①立柱垂直度偏差≤H/1000且≤5mm；②立柱间距偏差≤10mm；③立柱与基础预埋螺栓紧固，螺母不少于双帽；④立柱镀锌层完好，无锈蚀"}, {"seq": 22, "point": "声屏障板安装", "content": "吸声/隔声板安装", "basis": "①声屏障板型号和性能（吸声系数、隔声量）符合设计要求；②板与立柱间用弹性胶条密封，板缝严密；③板安装垂直，相邻板高差≤3mm；④透明声屏障板应选用安全夹胶玻璃或PC板"}, {"seq": 23, "point": "声屏障密封", "content": "底部和端部密封", "basis": "①声屏障底部与基础之间的缝隙用砂浆或橡胶条密封；②端部采用渐变段向地面过渡；③不得有漏声缝隙"}]}, {"name": "2.7 机电工程", "items": [{"seq": 1, "point": "监控外场设备基础", "content": "设备基础与接地", "basis": "①摄像机、可变情报板等设备基础位置偏差≤200mm；②基础混凝土强度≥C25，预埋地脚螺栓位置准确；③接地电阻≤4Ω，独立防雷接地≤10Ω；④基础顶面平整，高于周边地面≥200mm"}, {"seq": 2, "point": "摄像机安装", "content": "摄像机立柱和角度", "basis": "①立柱垂直度≤3mm/m，高度按设计；②摄像机安装高度≥6m（主线），视野覆盖范围满足监控要求；③图像清晰度≥设计指标（一般≥720P）；④夜间低照度下图像质量满足要求"}, {"seq": 3, "point": "可变情报板", "content": "显示屏安装与显示效果", "basis": "①显示屏安装高度按设计，俯仰角可调；②显示亮度≥8000cd/m²，亮度可自动调节；③显示内容清晰完整，无坏点、缺笔、闪烁；④屏体防护等级≥IP65"}, {"seq": 4, "point": "车辆检测器", "content": "线圈/雷达/视频检测", "basis": "①环形线圈埋设：深度40-60mm，密封防水，电感量50-500μH；②微波/雷达检测器的检测精度：流量≥95%，速度≥90%；③视频检测器设置虚拟线圈准确，白天和夜间检测精度满足要求"}, {"seq": 5, "point": "监控中心设备", "content": "服务器、存储、大屏", "basis": "①服务器/工作站配置和软件版本符合合同要求；②大屏拼接缝隙≤1mm，亮度均匀性≥90%；③系统联网通信功能正常，数据传输延迟≤1s"}, {"seq": 6, "point": "通信管道", "content": "管道敷设质量", "basis": "①通信管道管材：HDPE硅芯管或钢管，壁厚符合设计；②管道埋深：人行道下≥0.5m，车行道下≥0.7m；③管道接头密封，过桥管箱安装牢固；④管道试通：用ϕ80mm试通棒通过率100%"}, {"seq": 7, "point": "光缆敷设", "content": "光缆架设和接续", "basis": "①光缆敷设张力≤允许张力，弯曲半径≥光缆外径20倍；②光缆接续用专用接头盒，接续损耗单模≤0.08dB/处（平均值）；③光缆终端ODF架上标识清晰，盘纤整齐；④中继段光纤衰减测试：1310nm≤0.35dB/km，1550nm≤0.22dB/km"}, {"seq": 8, "point": "通信机房", "content": "设备安装与布线", "basis": "①机柜安装垂直度≤3mm，排列整齐；②设备接地：工作地≤4Ω，保护地≤4Ω；③线缆布线整齐，强弱电分离，标签完整；④程控交换/传输设备开通测试，功能正常"}, {"seq": 9, "point": "紧急电话系统", "content": "紧急电话安装与通话质量", "basis": "①紧急电话安装间距：隧道内≤200m，主线≤2km；②通话清晰度≥3级（5级制）；③紧急电话标识明显，夜间有照明"}, {"seq": 10, "point": "收费岛/收费亭", "content": "收费岛施工尺寸", "basis": "①收费岛长度、宽度偏差±20mm；②收费岛高度：岛面高程偏差±10mm；③收费亭安装水平，门窗密封良好；④收费岛防撞护拦安装牢固"}, {"seq": 11, "point": "收费车道设备", "content": "栏杆机、车牌识别、称重等", "basis": "①栏杆机抬落杆时间≤1.5s，运行可靠无卡滞；②车牌识别准确率：白天≥98%，夜间≥95%；③ETC天线RSU读写范围正确，交易成功率≥99.5%；④计重收费：动态称重精度≤±5%（整车），传感器安装规范"}, {"seq": 12, "point": "收费网络与软件", "content": "收费软件功能", "basis": "①收费软件功能齐全：入口发卡、出口收费、ETC、移动支付等；②收费数据上传及时准确，数据丢包率≤1‰；③收费系统时间与北斗/GPS同步，偏差≤1s；④费率版本管理和下发功能正常"}, {"seq": 13, "point": "收费广场照明", "content": "照明灯安装和照度", "basis": "①收费广场照明灯杆垂直度≤3mm/m；②平均照度：收费车道≥100lx，收费广场≥40lx；③照明均匀度≥0.4；④应急照明切换时间≤5s"}, {"seq": 14, "point": "变配电设备", "content": "变压器和配电柜安装", "basis": "①变压器安装水平，基础槽钢平直；②变压器中性点接地电阻≤4Ω；③高低压配电柜排列整齐，柜内接线规范；④绝缘电阻测试：高压≥1000MΩ，低压≥500MΩ"}, {"seq": 15, "point": "电缆敷设", "content": "电力电缆施工", "basis": "①电缆敷设弯曲半径≥电缆外径15倍（铠装）或20倍（非铠装）；②电缆接头用专用附件，绝缘处理合格；③电缆标识清晰，路径标识桩齐全；④电缆绝缘测试合格方可送电"}, {"seq": 16, "point": "柴油发电机组", "content": "发电机安装和试运行", "basis": "①发电机基础牢固，减振措施到位；②自动切换时间≤15s；③满载试运行≥4h，各项参数正常；④储油间通风良好，消防设施齐全"}, {"seq": 17, "point": "UPS/EPS", "content": "不间断电源安装", "basis": "①UPS安装间距满足散热要求，进出风口通畅；②蓄电池组接线正确，单体电压偏差≤±2%；③UPS切换时间≤10ms（在线式），备用时间≥设计值（一般≥30min）；④EPS应急供电切换时间≤0.25s"}, {"seq": 18, "point": "路灯基础与灯杆", "content": "灯杆基础和安装", "basis": "①灯杆基础混凝土强度≥C25，地脚螺栓位置偏差≤3mm；②灯杆垂直度偏差≤3mm/m；③灯杆高度和臂长符合设计；④灯杆镀锌层厚度≥85μm，无损伤"}, {"seq": 19, "point": "灯具安装", "content": "灯具安装角度和防护等级", "basis": "①灯具安装高度和间距按设计；②灯具仰角按道路宽度和灯杆高度确定；③灯具防护等级≥IP65；④LED灯具色温：快速路4000-5000K，一般道路3000-4000K"}, {"seq": 20, "point": "照度与均匀度", "content": "路面照明指标检测", "basis": "①主干路/高速公路：平均照度≥30lx，均匀度≥0.4；②次干路：平均照度≥20lx，均匀度≥0.35；③眩光限制阈值增量TI≤10%"}, {"seq": 21, "point": "智能控制", "content": "调光和远程控制", "basis": "①照明控制支持手动/自动/远程控制模式；②根据车流量和时间自动调光功能正常；③单灯控制或分组控制功能可靠"}, {"seq": 22, "point": "隧道通风", "content": "射流风机安装", "basis": "①风机安装位置、方向符合设计，螺栓紧固；②风机运转平稳，振动值≤4.6mm/s；③正反转切换正常，风量/风速达到设计值；④风机控制柜接线规范，联动控制正常"}, {"seq": 23, "point": "隧道照明", "content": "隧道照明灯和应急照明", "basis": "①隧道入口段亮度：白天≥设计值（一般100-200cd/m²），夜间渐变；②隧道基本段照明：亮度≥设计值（一般2.5-10cd/m²）；③应急照明：供电中断后自动切换，持续供电时间≥30min；④灯具防护等级≥IP65，耐腐蚀"}, {"seq": 24, "point": "隧道消防", "content": "消防设施安装", "basis": "①消火栓间距≤50m（车行方向），箱体安装牢固；②灭火器配置数量和类型符合设计；③火灾报警：感温光纤或双波长火焰探测器灵敏可靠；④消防供水系统压力正常，水泵运转正常"}, {"seq": 25, "point": "隧道监控与广播", "content": "CO/VI检测和广播系统", "basis": "①CO/VI检测仪安装位置正确，读数准确（误差≤±5%）；②风速风向仪精度：风速±0.2m/s，风向±3°；③隧道广播扬声器布置无盲区，声压级≥背景噪声+15dB；④紧急电话和广播功能联动正常"}, {"seq": 26, "point": "隧道供配电", "content": "隧道专用变配电", "basis": "①双回路供电，自动切换时间≤0.5s；②隧道内电缆采用阻燃耐火型，敷设在电缆沟或桥架中；③配电箱/柜防护等级≥IP55；④接地系统：联合接地电阻≤1Ω"}]}]}, {"id": "quality_ch3", "title": "质量篇-第3章-专项工作监督要点", "category": "质量篇", "sheets": [{"name": "3.1 岗位责任登记监督要点", "items": [{"seq": 1, "point": "建设单位线下登记管理", "content": "1. 建设单位应在工程开工前组织各参建单位完成岗位责任登记纸质台账的建立，台账须经单位负责人签字确认。\n2. 纸质登记表应列明项目名称、标段、岗位名称、责任人姓名、身份证号、职称/资格证书编号、联系方式等基本信息。\n3. 建设单位档案管理部门应对纸质登记材料统一编号、归档保存，确保可追溯。\n4. 岗位发生变更时，应在3个工作日内更新纸质台账并由新任人员签字确认。", "basis": "《建设工程质量管理条例》第二十六条；《公路水运工程质量监督管理规定》第十二条；建设单位质量管理制度"}, {"seq": 2, "point": "建设单位线上登记管理", "content": "1. 建设单位应在质量监督管理系统平台中同步录入岗位责任信息，确保线上线下数据一致。\n2. 线上登记信息应包括人员电子签名或数字证书认证，确保登记信息的法律效力。\n3. 系统应具备自动预警功能，对证书到期、人员变更未更新等情况进行提醒。\n4. 建设单位应指定专人负责系统维护和数据更新，每月至少核查一次数据准确性。", "basis": "《建设工程质量信息化管理办法》；交通运输部关于推进工程质量信息化管理的通知；建设单位信息化管理制度"}, {"seq": 3, "point": "从业单位线下登记管理", "content": "1. 施工、监理、检测等从业单位应建立本单位项目管理人员岗位责任登记台账。\n2. 登记内容应包括项目经理、技术负责人、质检员、安全员、试验检测人员等关键岗位人员信息。\n3. 从业单位应将登记表报建设单位备案，备案后方可进场开展工作。\n4. 特种作业人员须持有效操作证，证书复印件应纳入登记台账附件。", "basis": "《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》；《建设工程安全生产管理条例》第二十三条"}, {"seq": 4, "point": "从业单位线上登记管理", "content": "1. 从业单位应在项目管理信息系统或质量监管平台上完成岗位责任登记，登记信息应与纸质台账保持一致。\n2. 线上登记范围应覆盖项目部全部管理人员及关键工序操作人员。\n3. 人员进退场信息应及时在系统中更新，退场人员应标注退场日期和原因。\n4. 从业单位应定期对线上登记数据进行自查，确保信息的完整性和时效性。", "basis": "交通运输部质量监管平台使用管理办法；从业单位信息化管理要求"}, {"seq": 5, "point": "岗位责任公示", "content": "1. 施工现场应在醒目位置设置岗位责任公示牌，公示项目主要管理人员姓名、岗位、职责范围、联系电话等信息。\n2. 公示牌应采用统一格式，尺寸不小于120cm×90cm，字体清晰，防雨防晒。\n3. 公示内容应与登记台账一致，人员变更后应在5个工作日内更新公示牌。\n4. 监理单位应对公示内容的真实性和完整性进行核查。", "basis": "《建设工程施工现场管理规定》；《建筑施工安全检查标准》(JGJ 59)；建设单位现场管理要求"}, {"seq": 6, "point": "关键岗位人员履职监督", "content": "1. 项目经理应常驻施工现场，每月驻场天数不少于规定要求，离开现场须履行请假手续。\n2. 技术负责人应主持图纸会审、技术交底、重大方案论证等技术管理工作，形成书面记录。\n3. 质检负责人应对每道工序质量进行检查验收，签署质量验收记录。\n4. 监理工程师应按规定进行旁站、巡视和平行检验，填写监理日志。", "basis": "《建设工程项目管理规范》(GB/T 50326)；《建设工程监理规范》(GB/T 50319)；合同约定及岗位职责文件"}, {"seq": 7, "point": "人员变更管理", "content": "1. 关键岗位人员变更须经建设单位书面批准，并报质量监督机构备案。\n2. 变更后人员资质不得低于原人员资质等级和工作经验要求。\n3. 变更交接期间原人员应继续履职，直至新任人员完成工作交接并到岗。\n4. 变更信息应在3个工作日内在线上线下同步更新，变更记录纳入档案管理。", "basis": "《公路水运工程质量监督管理规定》第十三条；合同专用条款关于人员变更的约定"}, {"seq": 8, "point": "岗位责任考核", "content": "1. 建设单位应建立岗位责任考核制度，明确考核周期（一般每季度一次）和考核标准。\n2. 考核内容包括到岗率、履职情况、工作质量、问题整改闭合等方面。\n3. 考核结果应与人员绩效、信用评价挂钩，不称职人员应予以更换。\n4. 考核记录应纳入工程档案管理，作为质量责任追溯的重要依据。", "basis": "《建设工程质量责任主体和有关机构不良记录管理办法》；建设单位考核管理制度"}, {"seq": 9, "point": "外聘人员及劳务队伍岗位责任", "content": "1. 施工总承包单位应对劳务分包队伍的人员素质和岗位责任承担连带管理责任。\n2. 劳务队伍负责人、班组长等关键岗位人员应纳入项目部统一管理，进行实名登记。\n3. 劳务人员上岗前必须经过安全技术交底和岗位技能培训，培训记录归档备查。\n4. 外聘专家、咨询人员应具备相应资质，其出具的意见和建议应签署姓名并承担责任。\n5. 劳务人员考勤和工时记录应完整，工资支付台账纳入农民工工资管理档案。", "basis": "《保障农民工工资支付条例》；《建筑工人实名制管理办法》；施工总承包合同相关条款"}, {"seq": 10, "point": "质量责任终身制落实", "content": "1. 工程开工前，所有参建单位法定代表人和项目负责人应签署工程质量终身责任承诺书。\n2. 承诺书应明确质量责任范围、责任期限和追责条款，承诺书原件应存档保存。\n3. 建筑物或构筑物明显部位应设置永久性质量责任标牌，载明参建单位和主要责任人。\n4. 工程质量责任信息档案应随工程竣工验收一并移交城建档案管理机构。", "basis": "《建筑工程五方责任主体项目负责人质量终身责任追究暂行办法》；《建设工程质量管理条例》"}, {"seq": 11, "point": "数字化登记及电子档案管理", "content": "1. 鼓励采用区块链、二维码等技术手段进行岗位责任登记和信息追溯。\n2. 电子登记档案应符合电子签名法和电子档案管理相关标准，确保法律效力。\n3. 数字化管理系统应具备数据备份、权限管理、防篡改等安全功能。\n4. 电子档案应与纸质档案并行管理，定期进行数据一致性校验。", "basis": "《中华人民共和国电子签名法》；《电子文件归档与电子档案管理规范》(GB/T 18894)；行业信息化建设指导意见"}]}, {"name": "3.2 隐蔽工程影像管理监督要点", "items": [{"seq": 1, "point": "影像管理制度建立", "content": "1. 建设单位应制定项目隐蔽工程影像资料管理办法，明确管理机构、职责分工和工作流程。\n2. 办法应规定影像资料采集的范围、频率、技术要求、存储格式和归档标准。\n3. 各参建单位应根据项目管理办法制定本单位实施细则。\n4. 影像管理制度应纳入项目质量保证体系，作为内审和外审的检查内容。", "basis": "《建设工程文件归档规范》(GB/T 50328)；建设单位质量管理体系文件"}, {"seq": 2, "point": "隐蔽工程清单管理", "content": "1. 施工单位应根据设计图纸和施工组织设计，编制隐蔽工程清单，报监理审核、建设单位确认。\n2. 清单应逐项列明隐蔽工程名称、部位、施工时间、技术要求、验收标准等。\n3. 清单中的每项隐蔽工程均应明确影像资料采集的具体要求和关键拍摄节点。\n4. 隐蔽工程清单实行动态管理，随施工进度及时更新和补充。", "basis": "《建筑工程施工质量验收统一标准》(GB 50300)；设计文件和施工规范"}, {"seq": 3, "point": "隐蔽工程验收程序", "content": "1. 隐蔽工程覆盖前，施工单位应提前24小时书面通知监理单位进行验收。\n2. 验收由监理工程师主持，施工、建设（必要时设计、勘察）单位共同参加。\n3. 验收过程中应同步进行影像资料采集，记录验收全过程。\n4. 验收合格后方可进入下一道工序，验收不合格须整改后重新验收并重新采集影像。", "basis": "《建设工程质量管理条例》第三十条；《建筑工程施工质量验收统一标准》(GB 50300)"}, {"seq": 4, "point": "影像拍摄设备要求", "content": "1. 拍摄设备应具备高清摄像功能，分辨率不低于1920×1080，配备防抖功能。\n2. 设备应定期校准和检测，确保日期时间戳准确无误。\n3. 关键部位拍摄应使用三脚架或稳定器，确保画面清晰、稳定。\n4. 备用设备和电池应充足，确保现场拍摄不因设备原因中断。", "basis": "项目影像资料管理办法；设备使用说明书及维护记录"}, {"seq": 5, "point": "影像拍摄内容要求", "content": "1. 拍摄内容应包括被隐蔽部位的全景、近景和细部特写，全面反映工程质量状态。\n2. 全景照片应展示隐蔽部位在整体结构中的位置和周围环境。\n3. 近景和特写应清晰展示钢筋规格、间距、保护层厚度、预埋件位置、焊缝质量等关键要素。\n4. 照片中应放置标尺或参照物，标明工程部位、桩号、标高、日期等信息牌。", "basis": "《建筑工程施工质量验收统一标准》(GB 50300)；各专业施工质量验收规范"}, {"seq": 6, "point": "影像拍摄时机要求", "content": "1. 隐蔽工程施工过程中应在关键节点及时拍摄，不得事后补拍或造假。\n2. 钢筋绑扎完成后、模板安装前各拍摄一组影像。\n3. 混凝土浇筑前所有预埋件、预留孔洞应逐项拍摄记录。\n4. 浇筑过程中应对浇筑顺序、振捣情况进行记录拍摄。\n5. 防水层、保温层等各层施工均应在隐蔽前完成拍摄。", "basis": "各专业施工规范及验收标准；项目影像资料管理办法"}, {"seq": 7, "point": "影像资料编号与标识", "content": "1. 每张照片和每段视频应有唯一编号，编号规则应统一并在管理办法中明确。\n2. 编号应包含工程名称、标段、部位、工序、拍摄日期等信息要素。\n3. 影像文件元数据中应嵌入拍摄时间、GPS坐标、拍摄人等信息。\n4. 拍摄记录台账应与影像文件一一对应，记录拍摄时间、内容、拍摄人、审核人。", "basis": "《建设工程文件归档规范》(GB/T 50328)；项目影像资料编号规则"}, {"seq": 8, "point": "影像资料审核", "content": "1. 监理单位应在隐蔽工程验收后24小时内对影像资料进行审核。\n2. 审核内容包括：影像是否清晰、内容是否完整、是否满足关键技术要求、编号标识是否正确。\n3. 审核不合格的影像资料应退回重拍，并在审核台账中注明退回原因。\n4. 审核通过的影像资料由监理工程师签字确认，方可作为正式档案归档。", "basis": "监理规范及监理合同约定；项目影像资料管理办法"}, {"seq": 9, "point": "影像资料存储与备份", "content": "1. 影像资料应采用“在线+离线”双重存储模式，在线存储至少保留至工程竣工验收后两年。\n2. 原始影像文件不得进行任何后期加工处理，原始文件和审核文件分目录存放。\n3. 重要影像资料应制作至少两份备份，异地进行防灾备份存储。\n4. 存储介质应定期检测其可读性，防止数据丢失。", "basis": "《电子文件归档与电子档案管理规范》(GB/T 18894)；建设单位档案管理规定"}, {"seq": 10, "point": "影像资料归档移交", "content": "1. 隐蔽工程影像资料应按单位工程、分部工程、分项工程分类整理归档。\n2. 归档影像资料应编制目录索引，注明文件名称、内容描述、拍摄日期、存储路径。\n3. 影像资料应与对应的隐蔽工程验收记录、检验批质量验收记录等纸质资料配套归档。\n4. 工程竣工时，影像资料随施工技术档案一并移交建设单位或城建档案管理机构。", "basis": "《建设工程文件归档规范》(GB/T 50328)；《城市建设档案管理规定》"}, {"seq": 11, "point": "地基与基础隐蔽工程影像要点", "content": "1. 基坑（槽）验槽应拍摄基底岩土情况、高程、平面尺寸、边坡支护状况及排水措施。\n2. 桩基钢筋笼制作、下放、焊接接头应全过程跟踪拍摄，重点拍摄接头质量和钢筋笼定位。\n3. 桩基混凝土灌注过程应拍摄导管埋深、混凝土面上升情况、泥浆指标检测。\n4. 承台、地梁钢筋绑扎和模板安装完毕后的整体情况和细部节点应逐项拍摄。", "basis": "《建筑地基基础工程施工质量验收规范》(GB 50202)；《建筑桩基技术规范》(JGJ 94)"}, {"seq": 12, "point": "主体结构钢筋隐蔽工程影像要点", "content": "1. 梁柱节点钢筋绑扎应重点拍摄钢筋规格、数量、间距、锚固长度和保护层垫块设置。\n2. 受力钢筋的连接接头（焊接、机械连接、绑扎搭接）应逐类拍摄并标注接头位置。\n3. 预应力筋孔道位置、锚垫板安装、预应力筋穿束应分别拍摄记录。\n4. 预埋件和预留孔洞的位置、尺寸、固定方式应在封模前拍摄存档。", "basis": "《混凝土结构工程施工质量验收规范》(GB 50204)；设计图纸和施工方案"}, {"seq": 13, "point": "防水隐蔽工程影像要点", "content": "1. 防水基层处理情况（平整度、干燥度、清洁度）应在防水层施工前拍摄。\n2. 防水卷材搭接宽度、搭接方向、粘结质量应逐段拍摄，搭接缝处理应特写拍摄。\n3. 细部节点（阴阳角、管根、变形缝、施工缝、后浇带）的防水加强层应逐一拍摄。\n4. 防水层成品保护情况和闭水（淋水）试验过程及结果应拍摄记录。", "basis": "《地下防水工程质量验收规范》(GB 50208)；《屋面工程质量验收规范》(GB 50207)"}, {"seq": 14, "point": "钢结构隐蔽工程影像要点", "content": "1. 钢结构构件进场验收应拍摄构件编号、截面尺寸、焊缝坡口及外观质量。\n2. 高强螺栓连接副安装应拍摄螺栓规格、穿入方向、初拧终拧标记。\n3. 钢结构焊缝应在涂装前拍摄焊缝外观及无损检测标识，重要焊缝应拍摄检测过程。\n4. 钢结构防腐涂装和防火涂装各层施工前应拍摄基层处理情况和涂层厚度检测。", "basis": "《钢结构工程施工质量验收规范》(GB 50205)；《钢结构焊接规范》(GB 50661)"}, {"seq": 15, "point": "路基路面隐蔽工程影像要点", "content": "1. 路基填筑每层压实后应拍摄压实度检测过程和结果标识。\n2. 软基处理（排水板插设、碎石桩施工、搅拌桩施工）的施工参数和成桩质量应拍摄记录。\n3. 路面基层和底基层每层施工完毕应拍摄取芯检测过程和芯样状况。\n4. 桥涵台背回填应拍摄填料类型、分层碾压厚度和压实度检测情况。", "basis": "《公路路基施工技术规范》(JTG/T 3610)；《公路路面基层施工技术细则》(JTG/T F20)"}, {"seq": 16, "point": "影像资料信息化管理", "content": "1. 鼓励采用BIM技术将隐蔽工程影像资料与三维模型关联，实现可视化追溯。\n2. 影像资料管理系统应具备快速检索、在线预览、权限控制等功能。\n3. 系统应支持移动端现场采集和上传，提高影像资料采集效率。\n4. 信息化管理平台应与质量监管平台对接，接受质量监督机构在线抽查。\n5. 系统应具备日志审计功能，记录所有访问和操作行为，确保数据安全可控。", "basis": "《建筑信息模型应用统一标准》(GB/T 51212)；行业信息化发展规划；建设单位信息化管理要求"}]}, {"name": "3.3 质量强基专项工作监督要点", "items": [{"seq": 1, "point": "文件宣贯——组织学习", "content": "1. 建设单位应组织各参建单位对质量强基相关文件进行集中学习和专题培训。\n2. 培训应覆盖项目管理层、技术骨干和一线班组长，培训后应进行考核或测试。\n3. 学习培训应有签到记录、培训教材、考核结果等完整档案。\n4. 培训频率每半年不少于一次，新进场人员应在进场一周内完成学习。", "basis": "交通运输部《公路水运工程质量强基专项行动方案》；建设单位质量管理制度"}, {"seq": 2, "point": "文件宣贯——宣传发动", "content": "1. 施工现场应悬挂质量强基主题标语和横幅，营造全员重视质量的工作氛围。\n2. 项目部应设立质量宣传栏，定期更新质量强基工作动态和典型案例。\n3. 利用安全生产月、质量月等活动契机，开展质量强基专项宣传活动。\n4. 通过微信群、内部简报等形式向全体参建人员推送质量强基工作要求。", "basis": "质量强基专项行动宣传指导意见；项目文明施工管理要求"}, {"seq": 3, "point": "文件宣贯——效果评估", "content": "1. 建设单位应每季度对文件宣贯效果进行评估，可采用问卷调查、现场抽问等方式。\n2. 评估结果应量化，知晓率和理解率达到90%以上为合格。\n3. 对评估中发现的问题应制定改进措施并进行补训。", "basis": "质量强基专项行动考核办法；建设单位培训管理制度"}, {"seq": 4, "point": "方案编制——总体方案", "content": "1. 建设单位应编制项目质量强基工作总体实施方案，明确工作目标、组织体系、重点任务和时间节点。\n2. 总体方案应结合项目特点和难点，有针对性地提出质量管控措施。\n3. 方案应经建设单位技术负责人审批，并报质量监督机构备案。\n4. 总体方案应在项目开工前完成编制和审批。", "basis": "《公路水运工程质量强基专项行动方案》；建设单位质量管理体系要求"}, {"seq": 5, "point": "方案编制——实施细则", "content": "1. 施工、监理单位应根据总体方案编制本单位质量强基实施细则。\n2. 实施细则应细化到分部分项工程，明确各环节质量控制标准和责任人。\n3. 实施细则应经单位技术负责人审批，报建设单位审核备案。\n4. 实施细则应根据施工进度和现场实际情况及时修订完善。", "basis": "施工单位质量保证体系文件；监理规划及监理实施细则"}, {"seq": 6, "point": "方案编制——动态调整", "content": "1. 施工过程中出现设计变更、施工工艺调整等情况时，应及时修订质量强基方案。\n2. 方案修订应履行原审批程序，重大变更应组织专家论证。\n3. 修订后的方案应及时传达至相关作业层并组织学习。", "basis": "设计变更管理办法；质量管理制度关于方案动态管理的要求"}, {"seq": 7, "point": "落实主体责任——建设单位首要责任", "content": "1. 建设单位应建立健全质量管理体系，设置质量管理机构，配备专职质量管理人员。\n2. 建设单位项目负责人是项目质量管理第一责任人，应对项目质量负总责。\n3. 建设单位应定期组织质量检查，每季度不少于一次全面质量巡查。\n4. 建设单位应保障合理工期和造价，不得明示或暗示降低质量标准。", "basis": "《建设工程质量管理条例》第七条至第十七条；《关于落实建设单位工程质量首要责任的通知》"}, {"seq": 8, "point": "落实主体责任——施工单位直接责任", "content": "1. 施工单位应建立从项目经理到操作人员的全员质量责任体系，层层签订质量责任书。\n2. 施工单位应严格执行“三检制”（自检、互检、交接检），每道工序均应形成质量记录。\n3. 施工单位应对进场材料、构配件和设备进行验收检验，杜绝不合格材料用于工程。\n4. 施工单位应建立质量问题台账，对质量缺陷和隐患实行“排查-整改-验收-销号”闭环管理。", "basis": "《建设工程质量管理条例》第二十六条至第三十三条；施工单位质量保证体系"}, {"seq": 9, "point": "落实主体责任——监理单位监理责任", "content": "1. 监理单位应独立、公正地开展监理工作，对施工质量实施全过程监控。\n2. 监理工程师应按规范和合同约定进行旁站、巡视和平行检验，关键工序应全程旁站。\n3. 监理单位应及时发现和制止质量违规行为，下发监理通知单并跟踪整改闭合。\n4. 监理月报应如实反映质量管理状况，重大问题应及时向建设单位和监督机构报告。", "basis": "《建设工程监理规范》(GB/T 50319)；委托监理合同；《建设工程质量管理条例》第三十四条至第三十八条"}, {"seq": 10, "point": "关键工艺控制——清单化管理", "content": "1. 施工单位应在施工前编制关键工序和特殊过程清单，明确控制标准和验收要求。\n2. 关键工序清单应涵盖基础工程、主体结构、防水工程、装饰装修等各分部工程的重点环节。\n3. 对每项关键工艺应编制专项施工方案或作业指导书，经审批后实施。\n4. 清单应明确每道关键工序的质量控制点（停检点）、控制指标和检测方法。", "basis": "《建筑工程施工质量验收统一标准》(GB 50300)；各专业施工质量验收规范"}, {"seq": 11, "point": "关键工艺控制——首件工程认可制", "content": "1. 重要分项工程在全面施工前应实施首件工程（试验段），验证施工工艺和参数。\n2. 首件工程施工应编制专项方案，施工全过程应详细记录各项工艺参数和质量检测数据。\n3. 首件工程完成后应组织总结评估，形成首件工程总结报告，经审批后方可大面积施工。\n4. 首件工程认可的标准、数据和结论应作为后续施工的质量控制依据。", "basis": "《公路工程首件工程认可制管理办法》；施工组织设计和专项施工方案"}, {"seq": 12, "point": "关键工艺控制——过程监控", "content": "1. 关键工序施工过程中实行“三定”管理：定人、定岗、定责。\n2. 施工、监理单位应对关键工序实施旁站监督，填写旁站记录。\n3. 应运用信息化手段（如视频监控、传感器监测等）对关键工艺进行实时监控和数据采集。\n4. 关键工艺施工过程质量数据应实时记录并上传至质量管理平台。\n5. 发现工艺参数偏离控制范围时，应立即停止施工，查明原因并调整合格后方可继续。", "basis": "施工质量控制标准；项目信息化管理方案；各专业施工及验收规范"}, {"seq": 13, "point": "关键工艺控制——成品保护", "content": "1. 施工单位应编制成品保护方案，明确各工序成品保护的责任人和措施。\n2. 对已完成的关键工序成果应采取有效的防护措施，防止后续施工造成损伤。\n3. 交叉作业区域应加强协调管理，合理安排工序衔接，减少成品损坏风险。\n4. 成品保护情况应纳入日常质量巡查内容，对保护不当造成的质量缺陷应追溯责任并整改。", "basis": "《建筑工程成品保护技术规程》；施工单位质量管理制度"}]}]}, {"id": "safety_ch1", "title": "安全篇-第1章-安全管理体系监督要点", "category": "安全篇", "sheets": [{"name": "1.1 大中型项目开工前安全生产条件核查", "items": [{"seq": 1, "point": "安全生产许可证", "content": "1. 施工单位应持有建设行政主管部门颁发的有效安全生产许可证。\n2. 安全生产许可证应在有效期内，企业信息应与营业执照一致。\n3. 分包单位同样需持有有效安全生产许可证，总包单位应对此进行核验。\n4. 安全生产许可范围应覆盖本项目施工内容。", "basis": "《安全生产许可证条例》第二条；《建筑施工企业安全生产许可证管理规定》"}, {"seq": 2, "point": "安全生产责任制建立", "content": "1. 施工单位应建立从企业负责人到一线作业人员的全员安全生产责任制，逐级签订安全生产责任书。\n2. 安全生产责任制应明确各岗位的责任人员、责任范围和考核标准。\n3. 项目负责人应持有有效的安全生产考核合格证书（B证）。\n4. 安全生产责任制文件应经企业主要负责人签发，并在项目部公示。", "basis": "《安全生产法》第二十二条；《建设工程安全生产管理条例》第二十一条"}, {"seq": 3, "point": "安全生产管理机构设置", "content": "1. 大中型项目应设置独立的安全生产管理机构，配备专职安全管理人员。\n2. 专职安全管理人员配置数量：建筑面积5万㎡以下不少于2人，5万㎡以上每增加5万㎡增加1人。\n3. 专职安全管理人员应持有有效的安全生产考核合格证书（C证）。\n4. 安全生产管理机构应独立于生产管理部门，直接对项目负责人负责。", "basis": "《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》"}, {"seq": 4, "point": "安全专项施工方案编制", "content": "1. 对危险性较大的分部分项工程应编制安全专项施工方案。\n2. 超过一定规模的危险性较大工程专项方案应组织专家论证。\n3. 专项方案应经施工单位技术负责人审核签字、总监理工程师审查签字后实施。\n4. 方案应包括工程概况、编制依据、施工计划、施工工艺、安全保证措施、应急预案等内容。", "basis": "《危险性较大的分部分项工程安全管理规定》（住建部令第37号）；《建设工程安全生产管理条例》第二十六条"}, {"seq": 5, "point": "安全技术交底", "content": "1. 开工前应逐级进行安全技术交底，从项目技术负责人到班组长、再到作业人员。\n2. 交底内容应包括施工工艺、危险因素、安全操作规程、应急处置措施等。\n3. 交底应形成书面记录，交底人和被交底人双签确认，归档保存。\n4. 新进场人员和转岗人员上岗前必须进行安全技术交底。", "basis": "《建设工程安全生产管理条例》第二十七条；《建筑施工安全技术统一规范》(GB 50870)"}]}, {"name": "1.2 小型项目开工前安全生产条件核查", "items": [{"seq": 1, "point": "安全生产基本条件", "content": "1. 小型项目施工单位应持有有效安全生产许可证或具备安全生产条件认可。\n2. 项目负责人应持有安全生产考核合格证书（B证），具备小型项目管理经验。\n3. 至少配备1名专职或兼职安全管理人员，安全管理人员应持C证。\n4. 安全生产基本条件应在项目开工前经监理（或建设单位）核查确认。", "basis": "《安全生产许可证条例》；《建设工程安全生产管理条例》相关条款"}, {"seq": 2, "point": "安全管理制度", "content": "1. 应建立涵盖安全检查、安全教育、安全奖惩等基本内容的安全管理制度。\n2. 制度应结合小型项目特点简化但不弱化，确保操作性和执行力。\n3. 安全管理制度应经项目负责人审批并在项目部公示。\n4. 制度执行情况应纳入项目日常管理检查内容。", "basis": "《安全生产法》；小型项目安全管理指导文件"}, {"seq": 3, "point": "现场安全防护", "content": "1. 施工现场应按规定设置围挡和警示标识，围挡高度和牢固性应符合标准。\n2. 临时用电应编制用电组织设计或制定安全用电措施，配电系统应符合“三级配电、两级保护”要求。\n3. 高处作业面应设置防护栏杆、安全网等防护设施，安全带系挂点应可靠。\n4. 消防器材应按规范配置，易燃易爆物品存放应符合安全要求。", "basis": "《建筑施工安全检查标准》(JGJ 59)；《施工现场临时用电安全技术规范》(JGJ 46)"}, {"seq": 4, "point": "安全教育培训", "content": "1. 所有进场人员（含临时用工）上岗前须接受三级安全教育，教育时间不少于规定学时。\n2. 特种作业人员应持有效特种作业操作证方可上岗。\n3. 安全教育内容应涵盖本项目的危险源辨识、安全操作规程和应急知识。\n4. 安全教育应有签到表、培训教材和考核记录等台账资料。", "basis": "《生产经营单位安全培训规定》；《特种作业人员安全技术培训考核管理规定》"}, {"seq": 5, "point": "应急预案", "content": "1. 应编制简单实用的现场应急处置方案，明确应急组织机构、职责和处置程序。\n2. 应急物资和急救器材应在现场定点存放，标识清晰，定期检查更新。\n3. 开工前应组织一次应急演练或桌面推演，参演人员覆盖面应达到100%。\n4. 应急联系方式应公示于现场醒目位置，包括急救、火警、项目负责人等信息。", "basis": "《生产安全事故应急预案管理办法》；《建设工程安全生产管理条例》第四十八条"}]}, {"name": "1.3 施工合同段开工前安全生产条件核查", "items": [{"seq": 1, "point": "合同段安全组织体系", "content": "1. 各合同段施工单位应建立以项目经理为第一责任人的安全管理组织体系。\n2. 安全管理组织机构应覆盖本标段全部施工区域和作业班组。\n3. 各合同段应明确与总包单位（或建设单位）之间的安全管理接口和工作协调机制。\n4. 相邻合同段之间应建立安全生产联防联控协调机制。", "basis": "合同文件及安全生产协议书；《建设工程安全生产管理条例》"}, {"seq": 2, "point": "标段安全风险辨识评估", "content": "1. 开工前应对本标段所有施工活动进行系统性的危险源辨识和风险评价。\n2. 应形成危险源辨识清单和重大危险源台账，重大危险源应编制专项管控方案。\n3. 风险评价结果应作为编制安全技术措施和应急预案的依据。\n4. 危险源辨识和风险评价应动态更新，施工条件变化时重新评估。", "basis": "《建筑施工安全技术统一规范》(GB 50870)；《危险源辨识与风险评价技术导则》"}, {"seq": 3, "point": "标段施工组织设计安全篇", "content": "1. 合同段施工组织设计应包含独立的安全管理篇章，内容完整、措施具体。\n2. 安全管理篇章应包括安全目标、组织体系、危险源辨识、安全技术措施、应急预案等。\n3. 施工组织设计应经施工单位技术负责人审批，监理工程师审核，建设单位备案。\n4. 安全技术措施应具有针对性和可操作性，明确责任人、实施时间和验收标准。", "basis": "《建筑施工组织设计规范》(GB/T 50502)；《建设工程安全生产管理条例》"}, {"seq": 4, "point": "标段分包安全管理", "content": "1. 存在专业分包或劳务分包的合同段，总包单位应对分包单位安全生产条件进行核查。\n2. 分包合同中应明确双方的安全生产责任和义务，签订安全生产管理协议。\n3. 总包单位应将分包单位纳入统一的安全管理体系，实行同标准、同要求管理。\n4. 分包单位进场前应提交安全生产条件资料报总包和监理审核。", "basis": "《建设工程安全生产管理条例》第二十四条；《安全生产法》第四十六条"}, {"seq": 5, "point": "标段安全投入保障", "content": "1. 各合同段应按工程造价的一定比例足额提取安全生产费用，专款专用。\n2. 安全生产费用使用计划应列入施工组织设计，经审批后执行。\n3. 安全生产费用台账应清晰完整，每笔支出均有凭证和验收记录。\n4. 监理单位应对安全生产费用使用情况进行审核和监督。", "basis": "《企业安全生产费用提取和使用管理办法》；《建设工程安全生产管理条例》第八条"}]}, {"name": "1.4 危险性较大工程开工前安全生产条件核查", "items": [{"seq": 1, "point": "危大工程清单及方案", "content": "1. 施工单位应在开工前编制危险性较大分部分项工程清单，报监理审核、建设单位确认。\n2. 每项危大工程均应编制专项施工方案，方案应包括安全保障措施和应急处置措施。\n3. 超过一定规模的危大工程专项方案应经专家论证通过后方可实施。\n4. 专项方案审批流程应完整，所有签字盖章齐全，变更后须重新履行审批程序。", "basis": "《危险性较大的分部分项工程安全管理规定》（住建部令第37号）；《关于实施<危险性较大的分部分项工程安全管理规定>有关问题的通知》"}, {"seq": 2, "point": "深基坑工程安全条件", "content": "1. 深基坑施工前应进行基坑支护设计和降水方案论证，设计文件应经审查合格。\n2. 基坑周边建筑物、管线等环境状况应调查清楚并形成书面调查报告。\n3. 基坑监测方案应编制完成，监测点布设和初始值采集应在开挖前完成。\n4. 基坑应急救援物资（砂袋、钢管、水泵等）应在开工前储备到位。", "basis": "《建筑基坑工程监测技术规范》(GB 50497)；《建筑基坑支护技术规程》(JGJ 120)"}, {"seq": 3, "point": "高支模工程安全条件", "content": "1. 模板支撑体系搭设前应有专项施工方案且经审批，高大模板应经专家论证。\n2. 模板支撑体系材料（钢管、扣件、顶托）应经进场验收和抽样检测合格。\n3. 支撑体系基础应坚实平整，排水措施完善，地基承载力应验算合格。\n4. 搭设人员应持有效架子工特种作业操作证，上岗前完成安全技术交底。", "basis": "《建筑施工模板安全技术规范》(JGJ 162)；《建筑施工扣件式钢管脚手架安全技术规范》(JGJ 130)"}, {"seq": 4, "point": "起重吊装及起重机械安全条件", "content": "1. 起重机械（塔吊、施工升降机、汽车吊等）应有出厂合格证和型式试验报告。\n2. 起重机械安装（拆卸）应编制专项方案，安装单位应具备相应资质。\n3. 起重机械安装完毕后应经有资质的检测机构检测合格，办理使用登记。\n4. 起重吊装作业区域应设置警戒区，专人指挥，指挥人员持证上岗。", "basis": "《建筑施工塔式起重机安装、使用、拆卸安全技术规程》(JGJ 196)；《特种设备安全法》"}, {"seq": 5, "point": "脚手架工程安全条件", "content": "1. 脚手架搭设前应有专项方案且经审批，超过规定高度的应经专家论证。\n2. 脚手架材料（钢管、扣件、脚手板、安全网）应经进场验收合格。\n3. 脚手架基础应平整夯实，排水畅通，立杆底部应设垫板和底座。\n4. 脚手架搭设人员应持有效架子工特种作业操作证，且人证合一。\n5. 搭设完成后应经验收合格挂牌后方可使用。", "basis": "《建筑施工扣件式钢管脚手架安全技术规范》(JGJ 130)；《建筑施工安全检查标准》(JGJ 59)"}]}, {"name": "1.5 安全管理行为监督要点", "items": [{"seq": 1, "point": "目标策划——安全目标制定", "content": "1. 建设单位应在项目开工前制定项目安全生产总目标，目标应量化、可考核。\n2. 安全目标应包括事故控制指标（如零死亡、零重伤）、隐患整改率、安全教育覆盖率等。\n3. 安全目标应分解落实到各参建单位和各管理层级，形成目标责任体系。\n4. 目标策划文件应经建设单位主要负责人审批并下发至各参建单位。", "basis": "《安全生产法》第二十条；《建设工程安全生产管理条例》；建设单位安全生产责任制"}, {"seq": 2, "point": "目标策划——目标考核", "content": "1. 应建立健全安全目标考核机制，明确考核周期、考核方法和奖惩措施。\n2. 考核周期宜为每月或每季度一次，考核结果应公开并记入信用评价。\n3. 对未完成安全目标的单位应约谈主要负责人并限期整改。", "basis": "《安全生产法》第二十二条；建设单位安全目标管理办法"}, {"seq": 3, "point": "管理制度——制度体系建设", "content": "1. 各参建单位应建立健全安全生产管理制度体系，制度覆盖安全管理各环节。\n2. 至少应包括：安全生产责任制度、安全检查制度、安全教育制度、安全奖惩制度、事故报告和处理制度、消防安全管理制度等。\n3. 制度应具有可操作性，由单位负责人签发，并在项目部公示。\n4. 制度应定期评估修订，每年不少于一次系统性审查和更新。", "basis": "《安全生产法》第四条、第二十条；《建筑施工企业安全生产管理规范》(GB 50656)"}, {"seq": 4, "point": "机构和人员——机构设置", "content": "1. 施工单位和监理单位应按规定设立安全生产管理机构，配备专职安全管理人员。\n2. 安全生产管理机构应有独立的办公场所、必要的工作设备和经费保障。\n3. 安全管理人员的任职条件、数量和专业结构应符合项目规模和施工特点。", "basis": "《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》"}, {"seq": 5, "point": "机构和人员——人员资格", "content": "1. 项目负责人应持有有效的安全生产考核合格证书（B证）。\n2. 专职安全管理人员应持有有效的安全生产考核合格证书（C证）。\n3. 特种作业人员应持有有效的特种作业操作资格证书。\n4. 所有证书复印件应纳入安全管理档案，证书有效期到期前应提醒换证。", "basis": "《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》"}, {"seq": 6, "point": "安全生产责任——责任体系", "content": "1. 应建立覆盖全员的安全生产责任制，从企业负责人到一线操作人员，层层签订安全生产责任书。\n2. 安全生产责任制应明确各岗位的责任人、责任范围和考核标准。\n3. 安全生产责任制应在施工现场显著位置公示。\n4. 应制定安全生产责任追究制度，对失职行为追究相关人员和单位责任。", "basis": "《安全生产法》第十九条至第二十二条；《建设工程安全生产管理条例》"}, {"seq": 7, "point": "分包队伍——资质审查", "content": "1. 总承包单位应对拟选择的专业分包和劳务分包单位进行安全生产条件审查。\n2. 审查内容包括：安全生产许可证、安全管理制度、安全管理机构设置、安全管理人员配备、安全业绩等。\n3. 审查应形成书面记录，审查不合格的分包单位不得选用。", "basis": "《安全生产法》第四十六条；《建设工程安全生产管理条例》第二十四条"}, {"seq": 8, "point": "分包队伍——纳入统一管理", "content": "1. 总承包单位应与分包单位签订安全生产管理协议，明确双方安全责任和权利义务。\n2. 分包单位的安全生产应纳入总承包单位统一管理，实行同标准、同检查、同考核。\n3. 分包单位人员的安全教育培训、安全技术交底应由总承包单位统一组织或监督实施。\n4. 总承包单位应定期对分包单位安全生产状况进行检查评价。", "basis": "《安全生产法》第四十六条；总承包合同及安全生产协议书"}, {"seq": 9, "point": "设备及防护用品——进场验收", "content": "1. 施工机械设备进场前应进行验收，验收内容包括出厂合格证、型式试验报告、外观和性能检查。\n2. 特种设备应经有资质检测机构检测检验合格，取得使用登记证后方可使用。\n3. 安全防护用品（安全帽、安全带、安全网等）应具有生产许可证和产品合格证。\n4. 防护用品应按规定周期进行检测或更换，过期或损坏的严禁使用。", "basis": "《建筑施工安全检查标准》(JGJ 59)；《安全网》(GB 5725)；《安全带》(GB 6095)"}, {"seq": 10, "point": "设备及防护用品——使用管理", "content": "1. 施工机械设备应建立“一机一档”管理制度，记录设备运行、维修、保养情况。\n2. 特种设备应按规定进行定期检验和日常维护保养，检验合格标志应置于显著位置。\n3. 操作人员应持证上岗，严格遵守操作规程，严禁违章操作和带病运行。\n4. 安全防护设施（临边防护、洞口防护、通道防护棚等）搭设后应经验收挂牌。", "basis": "《特种设备安全法》；《建筑机械使用安全技术规程》(JGJ 33)"}, {"seq": 11, "point": "安全生产费用——提取与使用", "content": "1. 建设单位应按合同约定及时拨付安全生产费用，不得拖欠或克扣。\n2. 施工单位应按工程造价的规范比例足额提取安全生产费用，不得挪作他用。\n3. 安全生产费用应按规定范围使用，包括安全防护设施、应急救援器材、安全教育培训、安全标识等。\n4. 应建立安全生产费用使用台账，每笔支出均应有票据和证明材料，定期向监理和建设单位报告使用情况。", "basis": "《企业安全生产费用提取和使用管理办法》；《建设工程安全生产管理条例》第八条"}, {"seq": 12, "point": "风险管控——风险辨识评估", "content": "1. 应建立定期风险辨识评估制度，施工全过程实施动态风险管控。\n2. 重大风险应建立专账，编制专项管控方案，明确管控责任人和措施。\n3. 风险等级发生变化时应及时更新风险台账和管控措施。\n4. 应在施工现场设置安全风险公告栏，向作业人员告知主要风险和防范措施。", "basis": "《安全生产法》第三十七条；《建筑施工安全技术统一规范》(GB 50870)"}, {"seq": 13, "point": "风险管控——重大风险管控", "content": "1. 重大风险施工作业应实行许可制度，作业前应经审批并核查安全条件。\n2. 重大风险施工时，施工单位和监理单位应派专人现场监督。\n3. 应利用信息化手段对重大风险进行实时监测和预警。\n4. 重大风险管控措施落实不到位时，应立即停止相关作业，待整改合格后方可恢复施工。", "basis": "《安全生产法》第三十八条；《危险性较大的分部分项工程安全管理规定》"}, {"seq": 14, "point": "隐患排查——排查制度", "content": "1. 应建立健全安全生产隐患排查治理制度，明确排查频次、排查内容和责任人。\n2. 排查频次：日常巡查每日不少于一次，专项检查每周不少于一次，综合检查每月不少于一次。\n3. 排查应覆盖所有施工区域、所有工序和所有人员。\n4. 节假日和特殊天气前后应增加专项隐患排查。", "basis": "《安全生产法》第三十八条；《安全生产事故隐患排查治理暂行规定》"}, {"seq": 15, "point": "隐患排查——整改闭环", "content": "1. 排查发现的隐患应建立隐患台账，实行“排查-登记-整改-复查-销号”闭环管理。\n2. 一般隐患应在发现后24小时内整改完毕，重大隐患应立即停止相关作业并制定整改方案。\n3. 隐患整改应明确责任人和整改期限，整改后应经复查确认。\n4. 隐患排查治理情况应定期统计分析，形成月度或季度报告报建设单位。", "basis": "《安全生产事故隐患排查治理暂行规定》；建设单位隐患排查治理管理办法"}, {"seq": 16, "point": "技术管理——安全技术措施", "content": "1. 施工组织设计中应包含独立的安全技术措施篇章，对所有施工活动提出安全技术要求。\n2. 危险性较大工程应编制专项施工方案和安全技术措施，超过一定规模的应经专家论证。\n3. 安全技术措施应具有针对性和可操作性，不得照搬照抄。\n4. 施工过程中安全技术措施的落实情况应纳入日常安全检查内容。", "basis": "《建设工程安全生产管理条例》第二十六条；《建筑施工安全技术统一规范》(GB 50870)"}, {"seq": 17, "point": "技术管理——技术交底", "content": "1. 分部分项工程施工前应进行书面安全技术交底，由技术负责人组织，交底至全体作业人员。\n2. 交底内容应包括施工工艺、危险因素、安全操作规程、应急处置措施等。\n3. 交底应形成书面记录，交底人和被交底人分别签字确认。\n4. 施工条件发生变化或采用新工艺、新设备、新材料时，应重新进行安全技术交底。", "basis": "《建设工程安全生产管理条例》第二十七条；《建筑施工安全技术统一规范》(GB 50870)"}, {"seq": 18, "point": "安全教育培训——三级教育", "content": "1. 新进场人员和转岗人员必须经过公司、项目、班组三级安全教育培训。\n2. 三级教育总学时不得少于规定要求（公司级不少于15学时，项目级不少于15学时，班组级不少于20学时）。\n3. 教育内容应包括法律法规、安全知识、操作规程、事故案例、应急知识等。\n4. 培训后应进行考核，考核不合格者不得上岗，应重新培训直至合格。", "basis": "《生产经营单位安全培训规定》；《建设工程安全生产管理条例》"}, {"seq": 19, "point": "安全教育培训——日常教育", "content": "1. 各班组应每日召开班前安全会（班前喊话），针对当日作业内容进行安全提醒。\n2. 每周应组织一次安全学习活动，学习安全文件、分析事故案例。\n3. 节假日前后、季节变换、工程转序等节点应组织专题安全教育。\n4. 所有培训教育活动应有记录，纳入安全管理档案。", "basis": "《建筑施工企业安全生产管理规范》(GB 50656)；施工单位安全教育培训制度"}, {"seq": 20, "point": "应急预案——预案编制", "content": "1. 施工单位应根据项目风险辨识结果编制综合应急预案和专项应急预案。\n2. 应急预案应明确应急组织机构、响应程序、处置措施、资源保障和通讯联络等内容。\n3. 应急预案应经施工单位技术负责人审批，报监理和建设单位备案。\n4. 应急预案应根据演练情况和施工条件变化及时修订完善。", "basis": "《生产安全事故应急预案管理办法》；《生产经营单位生产安全事故应急预案编制导则》(GB/T 29639)"}, {"seq": 21, "point": "应急预案——物资与演练", "content": "1. 应急物资和器材应按规定配置并定点存放，标识清晰，定期检查、维护和更新。\n2. 施工现场应设置应急疏散通道和集合点，保持畅通，标识明显。\n3. 综合应急预案演练每年至少一次，专项应急预案演练每半年至少一次。\n4. 演练后应进行评估总结，针对问题完善预案和措施，评估报告归档保存。", "basis": "《生产安全事故应急预案管理办法》；《建设工程安全生产管理条例》第四十八条、第四十九条"}]}]}, {"id": "safety_ch2", "title": "安全篇-第2章-现场安全管理监督要点", "category": "安全篇", "sheets": [{"name": "2.1 通用作业安全", "items": [{"seq": 1, "point": "个人防护用品配备与使用", "content": "1.进入施工现场人员必须正确佩戴安全帽，高处作业人员必须系挂安全带；\n2.安全帽、安全带、安全网等防护用品必须具有产品合格证并在有效期内；\n3.从事尘毒危害作业人员应佩戴相应的防尘防毒口罩或面具；\n4.电焊工、气割工必须佩戴焊接护目镜和防护面罩。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第3.0.10条；《安全帽》(GB 2811)；《安全带》(GB 6095)"}, {"seq": 2, "point": "临边与洞口防护", "content": "1.基坑、楼层、阳台、屋面等临边部位必须设置不低于1.2m的防护栏杆；\n2.各类洞口（楼梯口、电梯井口、预留洞口等）必须设置牢固的盖板或防护栏杆；\n3.防护栏杆应由上、下两道横杆及栏杆柱组成，上杆高度1.0~1.2m，下杆高度0.5~0.6m；\n4.防护设施应定型化、工具化，并刷红白相间警示色。", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)；《公路工程施工安全技术规范》(JTG F90-2015)第5.7条"}, {"seq": 3, "point": "安全通道与防护棚", "content": "1.进入建筑物的主要通道口必须搭设双层防护棚，顶层间距不小于0.6m；\n2.钢筋加工棚、木工加工棚等作业区域应搭设防砸、防雨防护棚；\n3.安全通道宽度不小于2m，净高不小于2.2m，标识清晰；\n4.多层作业应设置隔离防护层，防止高处落物伤及下方人员。", "basis": "《建筑施工安全检查标准》(JGJ 59)；《公路工程施工安全技术规范》(JTG F90-2015)第5.12条"}, {"seq": 4, "point": "施工便道与交通组织", "content": "1.施工便道应满足运输车辆安全通行的宽度、坡度及转弯半径要求；\n2.便道与既有道路交叉处应设置警示标志、减速带及交通指挥人员；\n3.便道临边侧应设置防撞墩或防护栏杆；\n4.夜间施工便道应有充足的照明，危险路段设置警示灯。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第4.3条；《施工现场临时用电安全技术规范》(JGJ 46)"}, {"seq": 5, "point": "安全警示标志设置", "content": "1.施工现场危险部位应设置明显的安全警示标志，包括禁止、警告、指令、提示四类；\n2.重大危险源区域应设公示牌，标明危险源名称、责任人、控制措施及应急措施；\n3.安全标志牌应设在醒目的位置，不得随意移动、遮挡或拆除；\n4.主要出入口应设置“五牌一图”（工程概况牌、管理人员名单及监督电话牌、消防保卫牌、安全生产牌、文明施工牌和施工现场总平面图）。", "basis": "《安全标志及其使用导则》(GB 2894)；《建筑施工安全检查标准》(JGJ 59)；《建设工程安全生产管理条例》"}, {"seq": 6, "point": "消防器材配置与管理", "content": "1.施工现场应根据火灾危险类别配置相应类型和数量的灭火器材；\n2.灭火器应设置在明显和便于取用的地点，周围不准堆放物品和杂物；\n3.灭火器应定期检查、维护，压力表指针在绿区范围内，外观无锈蚀损坏；\n4.每100㎡临时用房至少配置2具4kg灭火器，动火作业区域单独增设。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第5.2条；《建筑灭火器配置设计规范》(GB 50140)"}, {"seq": 7, "point": "临时用房防火要求", "content": "1.宿舍、办公用房等临时建筑构件的燃烧性能等级应为A级（不燃材料）；\n2.临时用房层数不应超过2层，每层建筑面积不应大于300㎡；\n3.宿舍房间的建筑面积不应大于30㎡，居住人数不宜超过16人；\n4.临时用房应设置不少于2部疏散楼梯，疏散通道畅通。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第4.2条"}, {"seq": 8, "point": "易燃易爆物品管理", "content": "1.易燃易爆危险品（气瓶、油料、油漆等）应分类专库存放，库房耐火等级不低于二级；\n2.氧气瓶与乙炔瓶工作间距不小于5m，与明火距离不小于10m；\n3.易燃易爆品库房应设置明显的禁火标志，配备相应灭火设施；\n4.乙炔瓶使用时应直立放置，严禁卧放，并采取防回火措施。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第6.3条；《气瓶安全技术规程》(TSG 23)"}, {"seq": 9, "point": "消防通道与疏散", "content": "1.施工现场必须设置临时消防车道，车道宽度不小于4m，净空高度不小于4m；\n2.消防车道应保持畅通，严禁占用、堵塞、封闭；\n3.临时用房疏散走道净宽度不小于1.1m，疏散楼梯净宽度不小于1.1m；\n4.应急照明灯和疏散指示标志应完好有效，备用电源供电时间不小于30min。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第3.3条"}, {"seq": 10, "point": "动火审批与监护", "content": "1.施工现场动火作业必须办理动火审批手续，明确动火级别、时间、地点、防护措施及监护人；\n2.动火作业前应清除周围易燃物，无法清除的应采取隔离、覆盖措施；\n3.动火作业期间必须有专职或兼职消防监护人在场，并配备灭火器材；\n4.动火作业结束后应检查确认无残留火种后方可离开。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第6.3条；《机关、团体、企业、事业单位消防安全管理规定》"}, {"seq": 11, "point": "动火作业分级管理", "content": "1.动火作业应分为一级、二级、三级进行分级审批管理；\n2.一级动火（易燃易爆场所、重要设施部位）由项目负责人审批，专项方案经监理批准；\n3.动火许可证有效期不超过8h，延期应重新审批；\n4.节假日、夜间动火应升级管理，提高一个动火等级审批。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第6.3条；《焊接与切割安全》(GB 9448)"}, {"seq": 12, "point": "电焊与气割作业安全", "content": "1.电焊机一次线长度不超过5m，二次线接头不超过3个，绝缘良好无破损；\n2.焊钳与焊把线绝缘可靠，接头牢固，严禁利用厂房金属结构、管道等作焊接回路；\n3.雨天不得露天焊接作业，潮湿环境应有可靠的绝缘措施；\n4.气割用减压器、回火防止器等安全装置完好，气管颜色区分清晰（氧气为红色/黑色，乙炔为红色）。", "basis": "《焊接与切割安全》(GB 9448)；《施工现场临时用电安全技术规范》(JGJ 46)"}, {"seq": 13, "point": "高空动火防护", "content": "1.高处动火作业时火星飞溅范围内不得有易燃物，下方应设接火盆或防火布；\n2.高处动火应设专人监护，配备灭火器材；\n3.五级及以上大风天气禁止露天高空动火作业；\n4.安全带应选用阻燃防火型，避免焊接火花烫伤安全带。", "basis": "《焊接与切割安全》(GB 9448)；《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 14, "point": "密闭/受限空间动火", "content": "1.密闭或受限空间内动火作业前必须进行气体检测（氧气含量19.5%~23.5%，可燃气体≤爆炸下限10%）；\n2.作业期间应连续通风，保持良好空气流通；\n3.气瓶和焊机必须放置在受限空间外部，管线不得有泄漏；\n4.作业人员须佩戴防毒面具，设专人在外监护并保持通讯畅通。", "basis": "《工贸企业有限空间作业安全管理与监督暂行规定》；《缺氧危险作业安全规程》(GB 8958)"}, {"seq": 15, "point": "动火作业后检查", "content": "1.动火作业结束后清扫场地，确认无残留火种；\n2.检查焊渣飞溅区域是否有阴燃现象；\n3.监护人应在作业结束后继续监护观察不少于30min；\n4.关闭气瓶阀门、切断电焊机电源，整理归位消防器材。", "basis": "《建设工程施工现场消防安全技术规范》(GB 50720)第6.3条"}, {"seq": 16, "point": "TN-S接零保护系统", "content": "1.施工现场临时用电必须采用TN-S（三相五线制）接零保护系统；\n2.保护零线（PE线）必须采用绿/黄双色线，不得混用或代用；\n3.PE线上严禁装设开关或熔断器，严禁通过工作电流；\n4.配电系统应采用三级配电、两级保护，总配电箱和开关箱内必须设置漏电保护器。", "basis": "《施工现场临时用电安全技术规范》(JGJ 46)第5.1条"}, {"seq": 17, "point": "配电箱与开关箱", "content": "1.配电箱、开关箱应装设在干燥、通风及常温场所，周围有足够2人同时工作的空间和通道；\n2.配电箱、开关箱应装设端正、牢固，固定式箱体中心距地面1.4m~1.6m，移动式0.8m~1.6m；\n3.配电箱、开关箱内电器装置应完好可靠，分路标记清晰，接线规范；\n4.配电箱应上锁管理，非电工人员严禁操作。", "basis": "《施工现场临时用电安全技术规范》(JGJ 46)第8.1条"}, {"seq": 18, "point": "漏电保护装置", "content": "1.开关箱中漏电保护器额定漏电动作电流不应大于30mA，动作时间不应大于0.1s；\n2.潮湿或有腐蚀介质场所漏电保护器额定漏电动作电流不应大于15mA；\n3.总配电箱漏电保护器额定漏电动作电流应大于30mA，动作时间应大于0.1s，但两者乘积不应大于30mA·s；\n4.漏电保护器应每日试验一次，每月全面检测一次，损坏的立即更换。", "basis": "《施工现场临时用电安全技术规范》(JGJ 46)第8.2条"}, {"seq": 19, "point": "电缆线路敷设", "content": "1.电缆干线应采用埋地或架空敷设，严禁沿地面明设；\n2.电缆直接埋地敷设深度不应小于0.7m，穿越道路时应加设防护套管；\n3.架空电缆应沿电杆、支架或墙壁敷设，采用绝缘子固定，严禁沿脚手架、树木敷设；\n4.电缆接头应牢固可靠，做好绝缘包扎，不得承受外力。", "basis": "《施工现场临时用电安全技术规范》(JGJ 46)第7.2条"}, {"seq": 20, "point": "接地与防雷", "content": "1.施工现场的电气设备金属外壳必须与保护零线连接；\n2.保护零线除必须在总配电箱处做重复接地外，还必须在配电系统的中间处和末端处做重复接地；\n3.接地电阻值应符合要求（工作接地≤4Ω，重复接地≤10Ω，防雷接地≤30Ω）；\n4.施工现场的高耸建（构）筑物及机械设备应有可靠的防雷接地措施。", "basis": "《施工现场临时用电安全技术规范》(JGJ 46)第5.3条、第9.1条"}, {"seq": 21, "point": "爆破器材管理", "content": "1.爆破器材（炸药、雷管、导爆索等）必须储存在经批准的专用库房内，不得超量、超品种储存；\n2.炸药与雷管必须分库存放，两库安全距离符合规范要求；\n3.爆破器材领用须执行“两签三对”制度（两签：领用人签字、发放人签字；三对：对品种、对数量、对编号）；\n4.当班剩余爆破器材必须办理退库手续，严禁私自存放在现场或宿舍。", "basis": "《民用爆炸物品安全管理条例》；《爆破安全规程》(GB 6722)第4章"}, {"seq": 22, "point": "爆破设计及审批", "content": "1.爆破作业必须编制爆破设计说明书，明确爆破参数、装药结构、起爆网路及安全验算；\n2.A、B级爆破工程应经专家评审通过后方可实施；\n3.爆破设计应计算爆破振动安全允许距离、个别飞散物安全允许距离及冲击波安全允许距离；\n4.爆破设计文件须经爆破技术负责人审核、项目负责人批准后方可使用。", "basis": "《爆破安全规程》(GB 6722)第5章；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 23, "point": "爆破安全警戒", "content": "1.爆破前应确定警戒范围，设置明显的警戒标志和信号（预警信号、起爆信号、解除信号）；\n2.警戒范围应根据爆破设计确定，一般飞石安全距离：浅孔爆破≥300m，深孔爆破≥200m，洞室爆破按设计≥300m；\n3.爆破前所有人员、设备应撤至安全区域，各警戒点设专人值守；\n4.确认所有警戒点报告安全后方可下令起爆。", "basis": "《爆破安全规程》(GB 6722)第7章"}, {"seq": 24, "point": "爆破后安全检查", "content": "1.爆破后应至少等待通风时间15min（地下工程30min）后方可进入检查；\n2.检查人员应由爆破技术人员和有经验的爆破员组成；\n3.应检查确认有无盲炮（拒爆）、有无危石塌落、有无残留爆破器材；\n4.发现盲炮应立即上报，由原爆破人员按规程处理，严禁强拉、强掏起爆药包。", "basis": "《爆破安全规程》(GB 6722)第8章"}, {"seq": 25, "point": "爆破作业人员资质", "content": "1.爆破作业人员必须持有效的《爆破作业人员许可证》，按许可类别和等级从事相应工作；\n2.爆破工程技术人员须持有相应级别的安全作业证；\n3.爆破员、安全员、保管员不得相互兼任；\n4.爆破作业人员应定期参加继续教育和安全培训。", "basis": "《民用爆炸物品安全管理条例》第33条；《爆破作业人员资格条件和管理要求》(GA 53)"}, {"seq": 26, "point": "起重机械与吊具", "content": "1.起重机械必须经有资质的检验检测机构检验合格，取得安全使用证或检验合格标志；\n2.吊钩应有防脱绳装置，表面无裂纹、无剥裂，危险断面磨损不超过原尺寸的10%；\n3.钢丝绳在一个捻节距内断丝数不得超过总丝数的10%，无扭结、无压扁、无严重锈蚀；\n4.起重机械的安全装置（力矩限制器、超高限位器、幅度限位器等）必须齐全有效。", "basis": "《起重机械安全规程》(GB 6067)；《建筑施工起重吊装工程安全技术规范》(JGJ 276)"}, {"seq": 27, "point": "吊装方案与交底", "content": "1.大型构件吊装、特殊吊装及危险性较大的吊装工程应编制专项施工方案；\n2.超过一定规模的吊装专项方案应经专家论证；\n3.吊装前应进行全面的安全技术交底，明确吊装流程、指挥信号、人员分工及应急措施；\n4.吊装作业区应设置警戒线，安排专职信号工、司索工和起重司机各司其职。", "basis": "《危险性较大的分部分项工程安全管理规定》(住建部令第37号)；《建筑施工起重吊装工程安全技术规范》(JGJ 276)"}, {"seq": 28, "point": "吊装操作安全", "content": "1.起重机不得超负荷或吊运重量不明的物件，起吊前应试吊确认制动器灵敏可靠；\n2.吊装过程中应严格执行“十不吊”规定；\n3.六级及以上大风或大雨、大雪、大雾等恶劣天气应停止露天吊装作业；\n4.严禁利用限制器和限位装置代替操纵机构，严禁在起重作业过程中进行检查和维修。", "basis": "《起重机械安全规程》(GB 6067)第10章；《建筑施工起重吊装工程安全技术规范》(JGJ 276)"}, {"seq": 29, "point": "双机及多机抬吊", "content": "1.双机抬吊时应选用同类型或性能相近的起重机，荷载分配合理，每台起重机的荷载不得超过其额定起重量的80%；\n2.多机抬吊应由一人统一指挥，指挥者应站在两台起重机司机都能看到的位置；\n3.抬吊过程中各起重机应同步起吊、同步回转、同步落位；\n4.抬吊应由有经验的起重工负责绑扎和指挥。", "basis": "《建筑施工起重吊装工程安全技术规范》(JGJ 276)"}, {"seq": 30, "point": "吊索具管理", "content": "1.吊索具应有出厂合格证，额定荷载标识清晰；\n2.吊索具应定期进行检查，每半年至少进行一次全面检验；\n3.损坏、变形或超期的吊索具应做报废处理，严禁继续使用；\n4.吊索具应存放在干燥通风处，分类摆放，防止腐蚀和损伤。", "basis": "《起重机械吊具与索具安全规程》(LD 48)"}, {"seq": 31, "point": "有限空间辨识与审批", "content": "1.施工前应对有限空间（污水井、检查井、桩孔、人孔、箱梁内部等）进行全面辨识并建立台账；\n2.有限空间作业必须执行“先审批、后作业”制度，办理有限空间作业许可证；\n3.作业许可证应明确作业内容、时间、人员、气体检测结果及安全措施；\n4.未经审批严禁擅自进入有限空间作业。", "basis": "《工贸企业有限空间作业安全管理与监督暂行规定》；《缺氧危险作业安全规程》(GB 8958)"}, {"seq": 32, "point": "气体检测与通风", "content": "1.有限空间作业前30min内必须进行气体检测，检测指标包括氧气含量、可燃气体、硫化氢、一氧化碳等；\n2.氧气含量应在19.5%~23.5%之间，可燃气体浓度应低于爆炸下限的10%，有毒气体浓度应低于职业接触限值；\n3.作业前应进行有效通风，作业期间保持连续通风，严禁纯氧通风换气；\n4.作业中断超过30min重新进入前，应重新进行气体检测。", "basis": "《缺氧危险作业安全规程》(GB 8958)；《工作场所有害因素职业接触限值》(GBZ 2.1)"}, {"seq": 33, "point": "个人防护与监护", "content": "1.进入有限空间作业人员必须佩戴全身式安全带，连接安全绳，绳端固定于有限空间外可靠的锚固点；\n2.根据气体检测结果佩戴相应的呼吸防护用品（过滤式防毒面具或正压式空气呼吸器）；\n3.有限空间外应设不少于2名监护人员，保持有效的通讯联络；\n4.监护人员应坚守岗位，不得离岗，发现异常立即通知作业人员撤离。", "basis": "《缺氧危险作业安全规程》(GB 8958)第6章"}, {"seq": 34, "point": "用电与照明安全", "content": "1.有限空间内使用的电气设备应符合防爆要求（在可能含易燃易爆气体的环境）；\n2.照明电压应使用安全电压，金属容器内和潮湿环境不大于12V，其他不大于24V；\n3.照明线路应使用绝缘完好的电缆，无接头、无破损；\n4.变压器不得带入有限空间内，应放置在外部干燥处。", "basis": "《施工现场临时用电安全技术规范》(JGJ 46)第10.2条；《缺氧危险作业安全规程》(GB 8958)"}, {"seq": 35, "point": "应急救援准备", "content": "1.有限空间作业前应制定应急救援预案，明确救援程序、人员分工和通讯联络方式；\n2.外部应配备应急救援器材（三脚架、绞盘、安全绳、空气呼吸器、急救箱等）；\n3.严禁盲目施救，未经培训和配备防护用品的人员不得进入有限空间救人；\n4.每年至少组织一次有限空间应急救援演练。", "basis": "《工贸企业有限空间作业安全管理与监督暂行规定》第20条"}]}, {"name": "2.2 桥梁工程安全", "items": [{"seq": 1, "point": "基坑开挖与支护", "content": "1.基坑深度超过3m应编制专项施工方案，深度超过5m或地质条件复杂时应经专家论证；\n2.基坑开挖应遵循“分层、分块、对称、限时”的原则，严禁超挖；\n3.基坑周边1m范围内不得堆载，坡顶1倍基坑深度范围内严禁超载；\n4.基坑临边应按规范设置防护栏杆和上下通道，夜间设警示灯。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.2条；《建筑施工土石方工程安全技术规范》(JGJ 180)"}, {"seq": 2, "point": "基坑排水与降水", "content": "1.基坑开挖前应做好地面排水系统，防止地表水流入基坑；\n2.开挖深度低于地下水位时应采取降水措施，降水井布置应满足坑底稳定要求；\n3.降水期间应监测坑内外地下水位变化，防止坑底突涌和周边沉降；\n4.基坑排水设备应有备用电源，确保连续降水不间断。", "basis": "《建筑基坑支护技术规程》(JGJ 120)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 3, "point": "基坑监测", "content": "1.基坑工程必须进行施工监测，监测内容包括：基坑坡顶水平位移和垂直位移、支护结构内力、地下水位变化、周边建（构）筑物沉降等；\n2.监测频率：开挖期间每天不少于1次，变形异常时加密监测；\n3.监测报警值应根据设计文件确定，达到报警值时应立即停止施工、启动应急预案；\n4.监测数据应及时整理分析，编制监测日报。", "basis": "《建筑基坑工程监测技术规范》(GB 50497)；《建筑施工安全检查标准》(JGJ 59)"}, {"seq": 4, "point": "基坑内作业安全", "content": "1.基坑内作业人员上下须设置专用通道（梯笼或专用爬梯），严禁沿坑壁攀爬；\n2.基坑深度超过2m应设临边防护栏杆；\n3.坑壁间滞留的浮石、危石应清理干净；\n4.基底超挖部分应按规定分层回填夯实，严禁用废渣虚填。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.2条"}, {"seq": 5, "point": "挖孔桩施工安全", "content": "1.人工挖孔桩深度超过16m时应采用机械成孔，超过10m时应进行专项设计并论证；\n2.孔口应高出地面30cm以上，设防雨盖板、防护栏杆及警示标志；\n3.孔内必须设应急软爬梯，爬梯应固定牢靠，随开挖深度及时接长；\n4.距孔口3m范围内严禁有机动车辆行驶或堆放重物。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.5条；《建筑桩基技术规范》(JGJ 94)"}, {"seq": 6, "point": "孔内通风与气体检测", "content": "1.挖孔桩作业前必须进行孔内气体检测（氧气、有毒有害气体、可燃气体）；\n2.孔深超过5m时，作业过程中应采用机械通风，保持孔内空气新鲜；\n3.每天下孔前应先用活体（鸽子、鸡等）检测孔内气体，确认安全后方可下孔；\n4.孔内空气不达标时，严禁人员下孔作业。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.5.5条"}, {"seq": 7, "point": "孔壁支护与提升设备", "content": "1.挖孔桩必须随挖随护，每开挖一段（通常0.5~1.0m）应及时浇筑护壁混凝土；\n2.护壁混凝土强度不得低于C20，厚度不应小于10cm，不得使用砂浆代替；\n3.提升设备（卷扬机、电动葫芦等）应有可靠的安全装置（制动装置、上限位等）；\n4.吊桶应有防脱钩装置，吊绳使用前应检查，断丝超标应立即更换。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.5条"}, {"seq": 8, "point": "孔口防护与通讯", "content": "1.孔口作业人员应佩戴安全带，并与孔口固定锚点可靠连接；\n2.孔内作业人员与孔口监护人员应保持有效的通讯联络（对讲机或信号铃）；\n3.暂停施工时孔口应用牢固的盖板封闭；\n4.相邻两孔净距小于3m或5倍桩径（取大值）时，不得同时开挖。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.5.8条"}, {"seq": 9, "point": "爬模/翻模系统安全", "content": "1.爬模（翻模）系统应由具有相应资质的设计单位进行设计，并通过验收方可使用；\n2.爬模架体应设置防倾覆装置、防坠落装置和同步提升控制系统；\n3.爬模架体每层作业平台应满铺脚手板，外立面用密目安全网全封闭；\n4.每次爬升前应进行全面检查，确认锚固点、液压系统、架体连接等完好可靠。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.8条；《液压爬升模板工程技术规程》(JGJ 195)"}, {"seq": 10, "point": "高空作业防护", "content": "1.高墩作业人员必须经过体检合格，无高血压、心脏病、癫痫等禁忌症；\n2.作业人员应正确佩戴安全带，高挂低用，配备防坠器；\n3.高墩作业面下方应设置水平安全网，随墩身升高同步提升；\n4.六级及以上大风、雷雨、大雾天气应停止高墩施工作业。", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 11, "point": "模板安装与拆除", "content": "1.模板安装应自下而上进行，每就位一块应立即固定，吊装模板下方严禁站人；\n2.模板拆除应自上而下逐层进行，严禁从高处抛掷；\n3.拆除的模板及构件应及时清理堆放，不得堆放在作业平台上；\n4.高墩模板吊装须有专人指挥，风力大于五级时停止吊装。", "basis": "《建筑施工模板安全技术规范》(JGJ 162)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 12, "point": "混凝土浇筑安全", "content": "1.泵送混凝土管道应有独立的加固支撑系统，不得攀挂或固定在爬模架体受力构件上；\n2.布料机、泵管末端应有可靠的固定和防摆动措施；\n3.混凝土浇筑应分层均匀，防止偏载导致模板体系失稳；\n4.振捣作业人员应穿戴绝缘手套和胶靴。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.8条"}, {"seq": 13, "point": "支架搭设", "content": "1.支架搭设前应编制专项施工方案，超过一定规模的应经专家论证；\n2.支架基础应平整夯实，有可靠的排水措施，地基承载力应满足设计要求；\n3.支架搭设应严格按照方案和规范要求，立杆间距、水平杆步距、剪刀撑设置等符合设计与规范；\n4.支架搭设完毕应经施工单位自检、监理验收合格，挂验收合格牌后方可使用。", "basis": "《建筑施工碗扣式钢管脚手架安全技术规范》(JGJ 166)；《建筑施工承插型盘扣式钢管支架安全技术规程》(JGJ 231)"}, {"seq": 14, "point": "支架预压与监测", "content": "1.支架搭设验收合格后应进行预压，预压荷载不小于最大施工荷载的1.1倍；\n2.预压应分级加载，每级持荷时间不少于30min，最大荷载持荷时间不少于24h；\n3.预压过程中应监测支架沉降和变形，并做好记录；\n4.根据预压结果调整模板预拱度，编制预压报告。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.10条"}, {"seq": 15, "point": "支架使用与拆除", "content": "1.支架使用期间严禁随意拆除受力杆件和拉结点；\n2.支架上材料堆放应均匀，严禁集中超载堆放；\n3.支架拆除应先上后下、先拆非承重后拆承重，须设警戒区和专人监护；\n4.六级及以上大风或大雨天气应停止支架上作业。", "basis": "《建筑施工安全检查标准》(JGJ 59)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 16, "point": "挂篮设计与验收", "content": "1.挂篮应由具有相应资质的设计单位进行设计，挂篮结构应经有资质的第三方检测机构检测合格；\n2.挂篮投入使用前应进行荷载试验（静载试验不小于最大荷载的1.2倍），试验报告经监理审批后投入使用；\n3.挂篮的行走系统、锚固系统、悬吊系统应安全可靠，主要受力构件安全系数不小于2.0；\n4.挂篮必须设置前限位和防倾覆安全装置。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.10条；《公路桥涵施工技术规范》(JTG/T F50)"}, {"seq": 17, "point": "挂篮安装与行走", "content": "1.挂篮安装和拆除应编制专项方案，安装完成后应经联合验收；\n2.挂篮行走前应检查行走轨道、反压轮、牵引装置等是否完好；\n3.挂篮行走时两端应对称同步进行，行走速度应缓慢均匀，设专人统一指挥；\n4.挂篮行走时作业平台上不得有无关人员和堆放材料。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.10.6条"}, {"seq": 18, "point": "挂篮悬浇安全", "content": "1.挂篮悬浇前应检查各锚固点、吊杆、后锚等是否牢固可靠；\n2.混凝土浇筑应自悬臂端向墩顶方向对称均衡进行，严格控制不平衡荷载；\n3.挂篮前端应设置牢固的安全防护栏杆和密目安全网，下方设水平安全网；\n4.跨航道或既有道路时挂篮底部应全封闭，防止落物。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.10条"}, {"seq": 19, "point": "预制场安全", "content": "1.预制场内各功能区（制梁区、存梁区、钢筋加工区等）应合理分区，通道畅通；\n2.张拉作业时应设置警示区，两端严禁站人，张拉人员应站在侧面操作；\n3.龙门吊作业须有专人指挥，严格遵守“十不吊”规定；\n4.预制场内临时用电应符合JGJ 46规范要求。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.6条"}, {"seq": 20, "point": "预应力张拉安全", "content": "1.张拉作业前应检查油泵、千斤顶、油压表等设备，确保标定合格且在有效期内；\n2.张拉时应缓慢均匀加压，严禁急剧升压，操作人员须站在构件两侧，严禁正对锚具站立；\n3.张拉区域应设置“张拉危险、闲人免进”警示牌，非作业人员不得进入；\n4.孔道压浆应在张拉完成后及时进行，压浆人员戴防护眼镜和手套。", "basis": "《公路桥涵施工技术规范》(JTG/T F50)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 21, "point": "梁板运输方案", "content": "1.梁板运输应编制运输方案，明确运输路线、车辆型号、加固措施及应急预案；\n2.超长、超宽、超高运输应按规定办理大件运输许可手续；\n3.运输道路应满足承载力和通行净空要求，弯道半径、坡度符合运输车辆行驶条件；\n4.运输前应对车辆进行全面检查，制动、转向、灯光、轮胎等应完好。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.7条"}, {"seq": 22, "point": "运梁车安全", "content": "1.运梁车应安装声光报警装置和倒车影像（或倒车雷达）；\n2.运梁车上梁板应稳固支垫、可靠绑扎，防止运输过程中移位、倾覆；\n3.运输过程中应有引导车开道，押运人员随行监护；\n4.运梁车行驶速度不宜超过15km/h，转弯、坡道处应减速慢行。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.7条"}, {"seq": 23, "point": "架桥机安装与验收", "content": "1.架桥机必须经特种设备检验机构检验合格，取得安全检验合格证；\n2.架桥机安装后应进行全面检查和试运转，并进行额定荷载和1.1倍动载试验；\n3.架桥机的前支腿、中支腿、后支腿应支垫稳固，地基承载力和水平度符合要求；\n4.架桥机过孔作业应有专项方案，过孔速度不大于2m/min。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.7条；《架桥机安全规程》(GB 26469)"}, {"seq": 24, "point": "架梁作业安全", "content": "1.架梁前应复核墩台中线、支座位置和高程，确保安装精度；\n2.梁板起吊应平稳缓慢，起吊高度超过墩顶1m后，方可横移就位；\n3.架梁作业区应划定警戒范围，严禁非作业人员进入；\n4.横移和落梁过程中应严密监视梁板两端同步性，偏差不得超过设计允许值。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.7条"}, {"seq": 25, "point": "跨线施工防护", "content": "1.跨高速公路、铁路、航道的桥梁架设应编制专门的安全防护方案；\n2.跨线施工应搭设安全防护棚架或挂设防护网，防止落物影响下方通行；\n3.跨线施工期间应协调相关部门实施交通管制或限速通行；\n4.防护棚架应有足够的抗冲击强度，定期检查维护。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.7.8条"}, {"seq": 26, "point": "桥面系施工安全", "content": "1.桥面施工应设置临边防护栏杆和水平安全网，防止人员及材料坠落；\n2.桥面湿接缝、横隔板连接等作业应搭设吊篮或使用桥面检测车；\n3.桥面铺装沥青混凝土施工时应做好高温防护和有害气体防护；\n4.桥面伸缩缝施工时应注意成品保护和交通引导。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第6.9条"}, {"seq": 27, "point": "防撞护栏施工", "content": "1.防撞护栏施工宜采用护栏模板台车或移动式吊篮，减少高处临边作业风险；\n2.护栏钢筋绑扎和模板安装时，人员应站在内侧操作平台上；\n3.外侧模板调整须系好安全带，工具材料应妥善放置防止坠落；\n4.护栏混凝土浇筑应分段进行，不得碰撞模板导致倾覆。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)"}]}, {"name": "2.3 隧道工程安全", "items": [{"seq": 1, "point": "隧道施工安全总体要求", "content": "1.隧道施工必须遵循“管超前、严注浆、短进尺、强支护、早封闭、勤量测”十八字方针；\n2.隧道施工前应进行地质复核和超前地质预报，动态调整施工方案；\n3.隧道施工应建立门禁管理系统，实时掌握洞内人员、设备信息；\n4.隧道施工应建立完善的通风、照明、通讯、报警及应急救援系统。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《公路工程施工安全技术规范》(JTG F90-2015)第7章"}, {"seq": 2, "point": "人员与门禁管理", "content": "1.隧道洞口应设置门禁系统（电子门禁或人工登记），所有进出人员必须实名登记；\n2.进洞人员必须佩戴含定位芯片的安全帽（或携带定位卡），洞口显示屏实时显示洞内人数；\n3.严禁与施工无关的人员进入隧道，参观人员须经项目负责人批准并佩戴防护用品；\n4.爆破作业期间严禁任何人员进入，警戒解除后方可恢复门禁通行。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第7.3.2条"}, {"seq": 3, "point": "通风与防尘", "content": "1.隧道施工必须采用机械通风，通风机应有备用电源，保证不间断供风；\n2.洞内空气质量应符合：氧气≥20%，CO≤30mg/m³，粉尘浓度（游离SiO₂＜10%时）≤8mg/m³；\n3.通风管应随掌子面推进及时延伸，管口距掌子面：压入式≤15m，吸出式≤5m；\n4.爆破后应加强通风，通风时间不少于30min，检测合格后方可进入。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《工业企业设计卫生标准》(GBZ 1)"}, {"seq": 4, "point": "应急逃生系统", "content": "1.隧道施工必须设置应急逃生通道，逃生通道距掌子面距离：Ⅳ级围岩≤50m、Ⅴ级及以上围岩≤30m；\n2.逃生通道可采用逃生管（直径≥600mm钢管）或专用通道，应保持畅通无阻；\n3.隧道内应配备应急救援物资（急救箱、担架、氧气袋、照明设备等）；\n4.掌子面附近应储备足够的应急抢险物资（方木、钢拱架、沙袋等）。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第7.13条"}, {"seq": 5, "point": "施工用电与照明", "content": "1.隧道施工用电应采用TN-S系统，设置双电源或备用发电机；\n2.隧道内照明：作业段≥36V安全电压，成洞段≥220V（高度≥2.5m），灯具应防水防爆；\n3.掌子面附近应采用LED照明灯具，满足作业照度要求（一般作业面≥50lx）；\n4.电缆线路应沿隧道壁敷设，距地面高度不少于2m，接头处做防水处理。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第7.6条；《施工现场临时用电安全技术规范》(JGJ 46)"}, {"seq": 6, "point": "洞口边坡及仰坡", "content": "1.洞口开挖前应做好洞口排水系统（截水沟、排水沟），防止雨水冲刷边坡；\n2.洞口边坡、仰坡开挖应自上而下分层进行，严禁掏底开挖或上下层同时作业；\n3.边坡、仰坡开挖后应及时进行防护（喷锚、框架梁等），土质边坡坡率不陡于1:0.75；\n4.洞口应设置边坡稳定监测点，定期观测位移，异常时立即停止施工。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第4章；《公路工程施工安全技术规范》(JTG F90-2015)第7.4条"}, {"seq": 7, "point": "明洞与洞门施工", "content": "1.明洞基坑开挖应设临边防护，坑壁放坡或支护符合设计要求；\n2.明洞衬砌混凝土浇筑前应检查模板支撑体系是否牢固；\n3.洞门施工作业平台应搭设牢固，临空侧设防护栏杆；\n4.洞门装饰作业人员应正确佩戴安全防护用品，高空作业系好安全带。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第4章"}, {"seq": 8, "point": "进洞安全", "content": "1.隧道进洞前应施作超前大管棚或超前小导管并注浆加固，确保进洞安全；\n2.进洞初期应缩短开挖进尺（一般≤1榀钢架间距），加强初期支护；\n3.洞口段应加密监控量测断面（一般间距≤5m），及时分析数据指导施工；\n4.偏压洞口应先施工反压回填或抗滑桩等偏压处治措施。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《公路工程施工安全技术规范》(JTG F90-2015)第7.4条"}, {"seq": 9, "point": "全断面法适用条件", "content": "1.全断面法适用于Ⅰ~Ⅲ级围岩，断面尺寸不宜过大；\n2.全断面开挖一次进尺一般3~4m，围岩条件差时应缩短进尺；\n3.开挖后应及时施作初期支护，封闭成环时间不得超过设计规定；\n4.全断面开挖时应采用凿岩台车或多台风钻同时钻孔，提高工效、减少围岩暴露时间。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第6章"}, {"seq": 10, "point": "台阶法开挖安全", "content": "1.台阶法适用于Ⅲ~Ⅳ级围岩，上台阶高度一般为6~8m，台阶长度一般3~5m；\n2.上台阶开挖后应及时施作初期支护（钢拱架、喷射混凝土），严禁长时间不支护；\n3.下台阶开挖应左右错开进行（错距≥2榀钢架），严禁对称同时开挖；\n4.仰拱应及时跟进，距掌子面距离：Ⅳ级围岩≤40m，Ⅴ级围岩≤25m。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第6章；《公路工程施工安全技术规范》(JTG F90-2015)第7.5条"}, {"seq": 11, "point": "环形开挖留核心土法", "content": "1.适用于Ⅳ~Ⅴ级围岩，环形导坑开挖后应及时施作初期支护；\n2.核心土应保留足够尺寸，顶宽≥2m，高度≥2m，斜坡坡度≤1:1；\n3.核心土开挖应待初期支护封闭成环且变形基本稳定后进行；\n4.双侧壁导坑法或CRD法施工时，各洞室开挖纵向间距应≥15m。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第6章"}, {"seq": 12, "point": "分部开挖安全控制", "content": "1.双侧壁导坑法各导坑开挖面纵向间距≥15m，横通道间距≤30m；\n2.CRD法（交叉中隔壁法）各洞室错开距离≥10m，中隔壁拆除须待变形稳定后分段进行；\n3.分部开挖各临时支护（临时仰拱、临时中隔壁等）不得随意拆除；\n4.拆除临时支护前须确认永久支护已达到设计强度，拆除过程应进行位移监测。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第6章"}, {"seq": 13, "point": "TBM/盾构施工安全", "content": "1.TBM（隧道掘进机）选型须根据地层条件确定，开挖前进行地质预报；\n2.TBM掘进参数（推力、转速、贯入度等）应根据围岩条件实时调整；\n3.TBM换刀作业为高风险工序，必须编制专项方案，换刀时须有专人监护；\n4.长距离掘进时须关注通风降温、除尘、排水等系统运行状况。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第7.9条"}, {"seq": 14, "point": "初期支护（喷射混凝土）", "content": "1.喷射混凝土施工前应清理岩面浮石，作业人员佩戴防尘口罩、护目镜和防护手套；\n2.湿喷工艺优先采用，减少粉尘，喷射压力0.2~0.5MPa，喷嘴与受喷面距离0.6~1.2m；\n3.喷射作业应分段、分片、分层由下而上进行，一次喷射厚度（拱部5~10cm，边墙7~15cm）；\n4.喷射混凝土用水泥、速凝剂等材料应质量合格，配合比经试验确定。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第8章；《喷射混凝土用速凝剂》(GB/T 35159)"}, {"seq": 15, "point": "钢拱架与钢筋网施工", "content": "1.钢拱架加工尺寸应准确，接头处螺栓连接牢固，拱脚支垫稳固无虚渣；\n2.钢拱架安装后应及时打设锁脚锚杆（锚管），防止拱架下沉；\n3.钢拱架间距、垂直度应符合设计要求，相邻拱架间纵向连接筋应焊接牢固；\n4.钢筋网应与锚杆和钢拱架连接牢固，搭接长度≥1个网格间距。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第8章"}, {"seq": 16, "point": "二次衬砌施工", "content": "1.二衬台车应有出厂合格证，安装后经验收合格方可使用；\n2.台车轨道应铺设稳固，轨距偏差≤±5mm，高差≤10mm；\n3.二衬混凝土浇筑应左右对称、分层进行，防止台车偏移和跑模；\n4.台车拆除应待混凝土达到设计强度的75%以上，拆模顺序先侧后顶。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第9章"}, {"seq": 17, "point": "仰拱与填充施工", "content": "1.仰拱应紧跟掌子面，Ⅳ级围岩仰拱距掌子面≤40m，Ⅴ级围岩≤25m；\n2.仰拱开挖应分幅进行（半幅通车半幅施工），确保隧道内运输畅通；\n3.仰拱栈桥应有足够的承载力，设置防护栏杆和防滑措施；\n4.仰拱混凝土应一次浇筑成型，填充层应在仰拱混凝土达到设计强度后进行。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)"}, {"seq": 18, "point": "防水层施工安全", "content": "1.防水板铺设台架应搭设牢固，作业平台满铺脚手板，临边设防护栏杆；\n2.防水板焊接（热合焊接）时应控制温度（一般300~400℃），防止烫伤；\n3.防水板焊接时应通风良好，作业人员佩戴防毒口罩；\n4.防水板铺设后应及时进行焊缝气密性检查，合格后方可进入下一工序。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第11章"}, {"seq": 19, "point": "排水系统施工", "content": "1.隧道开挖过程中涌水突泥风险高，应进行超前探水预报；\n2.隧道内排水沟、盲沟、泄水孔等应按设计施工，保持排水通畅；\n3.富水段施工应备用水泵和排水管，排水能力应大于最大涌水量的1.5倍；\n4.排水设备应有专人看管，定期检查维护，确保正常运行。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第11章"}, {"seq": 20, "point": "监控量测", "content": "1.隧道施工必须进行监控量测，必测项目：洞内外观察、拱顶下沉、周边收敛、地表沉降（浅埋段）；\n2.量测断面间距：Ⅴ级围岩5~10m，Ⅳ级围岩10~20m，Ⅲ级围岩20~30m；\n3.量测频率：开挖后15天内每天1~2次，16~30天每2天1次，30天后每周1~2次；\n4.当变形速率或累计变形值超过管理等级时，应立即暂停施工，启动预警响应。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)第20章；《公路隧道设计规范》(JTG 3370.1)"}, {"seq": 21, "point": "超前地质预报", "content": "1.隧道施工必须进行超前地质预报，采用“长距离+短距离”相结合的综合预报方法；\n2.长距离预报采用TSP/TGP地震波法，预报距离100~150m；短距离采用地质雷达、超前钻探等；\n3.超前地质预报应作为工序纳入施工循环，每次预报结果应及时指导施工方案调整；\n4.不良地质段（断层、溶洞、富水带等）应加密超前钻探和物探频次。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《铁路隧道超前地质预报技术规程》(Q/CR 9217)"}, {"seq": 22, "point": "施工信息化管理", "content": "1.隧道施工应建立信息化管理平台，实时采集、传输、分析监测数据；\n2.监测数据出现异常时系统自动预警，并通过短信/APP通知相关责任人；\n3.信息化平台应能生成日报、周报、月报，汇总分析变形趋势；\n4.关键工序（开挖、支护、衬砌等）施工数据应同步录入信息化系统，实现可追溯。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)"}, {"seq": 23, "point": "富水软岩施工安全", "content": "1.富水软岩段应采用综合超前地质预报，查明地下水和围岩情况；\n2.采取“以堵为主、限量排放”的治水原则，超前帷幕注浆或径向注浆堵水；\n3.开挖采用短进尺（一般≤1榀钢架）、弱爆破、强支护，及时封闭成环；\n4.加大监控量测频率，掌握围岩变形和地下水位变化情况。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《公路工程施工安全技术规范》(JTG F90-2015)第7.11条"}, {"seq": 24, "point": "岩溶地层施工安全", "content": "1.岩溶发育区应采用综合超前地质预报（TSP+地质雷达+超前钻探），探明溶洞位置、规模及充填物性质；\n2.小型溶洞可采用回填（浆砌片石/混凝土）穿越，大型溶洞需进行专项处治设计；\n3.溶洞段开挖应严格控制进尺，遵循“先护后挖”原则；\n4.溶洞区应连续监测围岩变形和溶洞稳定性，准备应急救援物资。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《公路工程施工安全技术规范》(JTG F90-2015)第7.11.4条"}, {"seq": 25, "point": "采空区施工安全", "content": "1.采空区段应进行专项地质勘察，查明采空区分布范围、顶底板情况及充填状态；\n2.采空区处治措施（注浆充填、墩柱支撑、跨越等）根据采空区特征和工程要求确定；\n3.采空区注浆应控制注浆压力和注浆量，防止注浆压力过大引起地表隆起；\n4.穿越采空区期间应加强围岩变形和瓦斯监测。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《煤矿采空区岩土工程勘察规范》(GB 51044)"}, {"seq": 26, "point": "软岩大变形控制", "content": "1.软岩大变形段应遵循“先让后抗、刚柔并济”的支护原则；\n2.初期支护应采用可缩式钢架（U型钢/可缩式连接），预留变形量一般15~40cm；\n3.二次衬砌应适时施作，待初期支护变形基本稳定（速率≤0.2mm/d）后进行；\n4.锚杆（锚索）施工应严格控制长度和角度，确保锚固效果，必要时采用预应力锚杆。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《公路隧道设计规范》(JTG 3370.1)"}, {"seq": 27, "point": "岩爆预防与控制", "content": "1.岩爆预测采用综合方法（地应力测试+微震监测+岩芯饼化分析）；\n2.中等以上岩爆风险段应采取应力释放措施（超前应力解除爆破、钻孔卸压等）；\n3.开挖后及时喷射钢纤维混凝土+系统锚杆+钢筋网进行柔性支护；\n4.岩爆段作业人员须穿戴防冲击护具（防砸背心、护腿、护目镜等），机械设备应有防护罩。", "basis": "《公路隧道施工技术规范》(JTG/T 3660)；《岩爆隧道施工技术规程》(T/CECS G：D71-01)"}, {"seq": 28, "point": "瓦斯隧道安全管理", "content": "1.瓦斯隧道必须建立瓦斯检测、通风、防火、防爆“四位一体”的安全管理体系；\n2.瓦斯隧道所有电气设备必须采用防爆型（Exd/exe型），电缆采用阻燃型；\n3.瓦斯隧道严禁烟火，进洞人员严禁携带火种、手机、非防爆电子设备，穿防静电工作服；\n4.瓦斯浓度检测应实行“一炮三检”（装药前、爆破前、爆破后）和连续监测，浓度≥0.5%时报警、≥1.0%时断电撤人。", "basis": "《公路瓦斯隧道技术规范》(T/CECS G：D71-02)；《煤矿安全规程》"}]}, {"name": "2.4 路基工程安全", "items": [{"seq": 1, "point": "路基施工安全总要求", "content": "1.路基工程施工前应进行现场调查，识别危险源并编制安全生产方案；\n2.路基施工应做好临时排水系统，防止雨水冲刷边坡和浸泡路基；\n3.施工机械应有专人指挥，机械作业范围内严禁无关人员停留；\n4.路基与既有道路交叉施工时应设置交通引导标志和安全防护设施。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第4章；《公路路基施工技术规范》(JTG/T 3610)"}, {"seq": 2, "point": "施工机械安全管理", "content": "1.压路机、推土机、挖掘机等大型施工机械操作人员须持证上岗；\n2.机械使用前应进行日常检查（制动、转向、灯光、液压系统等）；\n3.多台机械在同一作业面施工时，前后间距≥8m，左右间距≥2m；\n4.机械在边坡、陡坎边缘作业时应有防倾覆措施，推土机铲刀不得悬空。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第4.4条"}, {"seq": 3, "point": "临时设施安全", "content": "1.弃土场、取土场应合理选址，边坡稳定，有完善的排水系统；\n2.临时便道应满足施工车辆安全通行要求，纵坡不宜大于10%，弯道设警示标志；\n3.炸药库、油库等危险品临时设施应远离施工区和生活区，满足安全距离要求；\n4.临时设施使用期间应定期检查和维护。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)；《公路路基施工技术规范》(JTG/T 3610)"}, {"seq": 4, "point": "土方开挖安全", "content": "1.土方开挖应自上而下分层进行，严禁掏底开挖，每层高度不宜超过3m；\n2.开挖边坡应随开挖随修整，土质边坡坡率应符合设计要求（一般≥1:1.5）；\n3.挖掘机作业时，铲斗不得从车辆驾驶室上方越过，回转半径内不得有人；\n4.弃土下方及滚石危及范围内的道路应设警示标志，作业时下方不得有人。", "basis": "《公路路基施工技术规范》(JTG/T 3610)；《公路工程施工安全技术规范》(JTG F90-2015)第4.5条"}, {"seq": 5, "point": "石方爆破开挖", "content": "1.石方爆破必须由具备相应资质的单位进行爆破设计和施工；\n2.爆破前应在危险区边界设置明显警戒线和岗哨，清除警戒范围内的人员和设备；\n3.爆破后应检查有无盲炮，确认安全后方可解除警戒；\n4.邻近村庄、道路的爆破应采取控制爆破（预裂爆破、光面爆破）或覆盖防护等减振降飞措施。", "basis": "《爆破安全规程》(GB 6722)；《公路工程施工安全技术规范》(JTG F90-2015)第4.6条"}, {"seq": 6, "point": "路基填筑安全", "content": "1.填筑作业应分层摊铺、分层碾压，每层厚度根据压实机具确定（一般≤30cm）；\n2.自卸汽车卸料时应有专人指挥，卸料后应待车厢完全落下方可行驶；\n3.压路机碾压时应注意路基边缘，距边缘不小于0.5m，碾压轮迹重叠宽度不小于1/3轮宽；\n4.高填方路基应埋设沉降观测装置，按设计要求进行沉降和位移监测。", "basis": "《公路路基施工技术规范》(JTG/T 3610)；《公路工程施工安全技术规范》(JTG F90-2015)第4.7条"}, {"seq": 7, "point": "高填深挖路基", "content": "1.高填方路基（填方高度≥20m或边坡高度≥8m）应进行专项稳定性分析；\n2.高填方应分层填筑，每填高10m应设置不小于2m宽的平台；\n3.深挖路堑（挖方高度≥20m或土质边坡高度≥15m）应编制专项施工方案并通过论证；\n4.高填深挖段应进行全过程施工监测，监测项目包括表面沉降、深层水平位移、地下水位等。", "basis": "《公路路基设计规范》(JTG D30)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 8, "point": "高边坡施工安全", "content": "1.高边坡（边坡高度≥15m的土质边坡或≥20m的岩质边坡）施工前应编制专项方案并论证；\n2.高边坡开挖应严格遵循“分级开挖、分级支护、逐级稳定”的原则；\n3.每级边坡开挖完成后应及时支护（锚杆、锚索、框架梁等），严禁一挖到底再回头支护；\n4.高边坡应设置完善的截排水系统，坡顶截水沟距坡顶边缘≥5m。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第4.8条；《建筑边坡工程技术规范》(GB 50330)"}, {"seq": 9, "point": "高边坡监测与预警", "content": "1.高边坡施工期应进行专项监测：坡顶水平位移/垂直位移、深层位移（测斜）、锚索应力、地下水位等；\n2.监测频率：施工期每周不少于2次，汛期和变形异常期每天1次；\n3.监测数据超预警值时应立即停工、启动应急预案、上报并组织专家会审；\n4.高边坡应设置变形观测桩和裂缝观测条，便于直观掌握边坡变化。", "basis": "《建筑边坡工程技术规范》(GB 50330)；《建筑基坑工程监测技术规范》(GB 50497)"}, {"seq": 10, "point": "危岩与崩塌防护", "content": "1.高边坡施工前应进行危岩排查，清除松动危石和浮石；\n2.人工清除危岩应自上而下进行，下方严禁站人和通行；\n3.高边坡施工区域下方应设置拦截网（被动防护网或SNS柔性防护网）；\n4.高边坡坡面作业人员应系安全带，挂设安全绳并固定于坡顶可靠锚固点。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)第4.8条"}, {"seq": 11, "point": "锚杆（索）施工安全", "content": "1.锚杆（索）钻孔作业应搭设稳固的操作平台，作业人员系好安全带；\n2.锚索张拉时千斤顶后方严禁站人，操作人员应站在侧面；\n3.锚索张拉应分阶段进行（初张拉→持荷→补张拉→锁定），做好张拉记录；\n4.锚头封锚前应对锚索进行防腐处理，封锚混凝土强度不低于C30。", "basis": "《岩土锚杆与喷射混凝土支护工程技术规范》(GB 50086)；《建筑边坡工程技术规范》(GB 50330)"}, {"seq": 12, "point": "高边坡汛期安全", "content": "1.汛期前应对高边坡进行全面检查，疏通截排水系统；\n2.雨天及雨后24h内应加密巡检，发现裂缝、滑坡迹象立即上报；\n3.高边坡区域应储备应急抢险物资（防水布、沙袋、排水泵等）；\n4.发生滑坡或坍塌时应立即启动应急预案，撤离危险区域人员。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)；《地质灾害防治条例》"}, {"seq": 13, "point": "防护工程施工安全", "content": "1.坡面防护（喷播植草、骨架护坡、挡土墙等）作业应搭设操作平台或使用吊篮；\n2.砌筑挡土墙应分段进行，分段长度一般10~15m，段间设变形缝；\n3.挡土墙墙背回填应分层夯实，分层厚度≤30cm，压实度≥设计要求；\n4.高挡墙（高度≥8m）施工应进行墙身位移监测。", "basis": "《公路路基施工技术规范》(JTG/T 3610)"}, {"seq": 14, "point": "排水设施施工安全", "content": "1.排水沟、截水沟、急流槽等排水设施应与路基工程同步施工；\n2.沟槽开挖应放坡或采取支护措施，弃土堆放距沟边≥1m；\n3.预制管涵安装应采用机械配合，吊装时下方严禁站人；\n4.排水设施施工期间应注意天气变化，预报有雨时应提前做好防护。", "basis": "《公路路基施工技术规范》(JTG/T 3610)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 15, "point": "生态防护与绿化", "content": "1.边坡绿化施工应选择适宜的季节和天气，避开高温和雷雨天气；\n2.采用客土喷播或液力喷播时，作业人员应佩戴防尘口罩和护目镜；\n3.喷播作业区域下方应设警戒标识，防止喷料飘散影响环境及行人；\n4.高边坡绿化养护作业应做好安全防护，系好安全带。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 16, "point": "涵洞基坑施工", "content": "1.涵洞基坑开挖应放坡或支护，基坑周边设防护栏杆和上下通道；\n2.基坑内有地下水时应采取排水或降水措施，防止坑壁坍塌；\n3.涵洞基坑开挖后应及时验槽和施工基础，减少暴露时间；\n4.基坑两侧1m范围内不得堆载，弃土应运至指定弃土场。", "basis": "《公路桥涵施工技术规范》(JTG/T F50)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 17, "point": "涵洞主体施工安全", "content": "1.涵洞模板支撑体系应有足够的刚度和稳定性，经验收合格后方可浇筑混凝土；\n2.涵洞混凝土浇筑应分层进行，两侧对称浇筑，防止偏压移位；\n3.盖板涵预制盖板吊装时应有专人指挥，吊具与盖板连接牢固；\n4.现浇涵洞顶板应编制模板支架专项方案，超过一定规模的须经专家论证。", "basis": "《公路桥涵施工技术规范》(JTG/T F50)"}, {"seq": 18, "point": "箱涵顶进施工", "content": "1.箱涵顶进应编制专项施工方案，并进行结构受力验算；\n2.顶进设备（千斤顶、液压泵站、后背等）应经检查校核，顶力满足设计要求；\n3.顶进过程中应监测箱涵轴线偏移和高程变化，发现偏差及时纠偏；\n4.顶进作业区应设警戒线，非作业人员禁止入内。", "basis": "《公路桥涵施工技术规范》(JTG/T F50)；《公路工程施工安全技术规范》(JTG F90-2015)"}, {"seq": 19, "point": "涵洞回填安全", "content": "1.涵洞两侧及顶部回填应在结构混凝土达到设计强度后进行；\n2.涵洞两侧回填应对称分层进行，高差不超过1层填筑厚度（≤30cm）；\n3.涵顶填土厚度小于0.5m时，严禁任何重型机械和车辆通行；\n4.回填压实应避免对涵洞结构产生偏压和冲击，靠近结构物1m范围内宜采用小型机具夯实。", "basis": "《公路桥涵施工技术规范》(JTG/T F50)"}, {"seq": 20, "point": "通道安全防护", "content": "1.通行通道（人行通道、车行通道、通道涵等）施工应确保既有交通的安全畅通；\n2.通道施工区域应与通行区域进行有效隔离（围挡、护栏等），设专人引导交通；\n3.通道内施工应有充足的照明和通风，保持通道干燥整洁；\n4.通道施工完成后应及时恢复路面，拆除围挡，完善标志标线。", "basis": "《公路工程施工安全技术规范》(JTG F90-2015)"}]}]}, {"id": "safety_ch3", "title": "安全篇-第3章-专项工作监督要点", "category": "安全篇", "sheets": [{"name": "3.1 安全生产网格化管理", "items": [{"seq": 1, "point": "网格体系建设\n(3.1.1)", "content": "建立健全安全生产网格化管理体系，明确网格化管理组织架构、职责分工和运行机制", "basis": "《安全生产法》第4条；网格化管理相关文件"}, {"seq": 2, "point": "网格体系建设\n(3.1.1)", "content": "制定网格化管理工作方案，明确总网格长、网格长、网格员层级及对应责任人", "basis": "企业安全生产标准化基本规范(GB/T 33000)"}, {"seq": 3, "point": "网格体系建设\n(3.1.1)", "content": "建立网格化管理工作制度，包括例会制度、巡查制度、信息报送制度、考核奖惩制度", "basis": "《关于推进安全生产领域改革发展的意见》"}, {"seq": 4, "point": "网格体系建设\n(3.1.1)", "content": "按要求定期召开网格化管理例会，研究部署安全生产工作，形成会议记录", "basis": "企业内部网格化管理制度"}, {"seq": 5, "point": "网格划分\n(3.1.2)", "content": "按照「横向到边、纵向到底」原则，科学合理划分安全生产管理网格，做到全覆盖、无盲区", "basis": "企业安全生产网格化管理指南"}, {"seq": 6, "point": "网格划分\n(3.1.2)", "content": "编制网格划分图，明确各网格边界、网格责任人、联系方式并公示", "basis": "施工现场安全管理规范"}, {"seq": 7, "point": "网格划分\n(3.1.2)", "content": "重大风险区域（高处作业、深基坑、临时用电等）应单独划设重点管理网格", "basis": "风险分级管控和隐患排查治理双重预防机制"}, {"seq": 8, "point": "人员管理\n(3.1.3)", "content": "网格长、网格员应经培训合格后上岗，熟悉本网格风险点和管控措施", "basis": "《生产经营单位安全培训规定》"}, {"seq": 9, "point": "人员管理\n(3.1.3)", "content": "网格人员变动应及时调整并报备，确保管理不脱节", "basis": "企业网格化人员管理制度"}, {"seq": 10, "point": "人员管理\n(3.1.3)", "content": "建立网格人员履职档案，记录巡查、发现隐患、处置等履职情况", "basis": "《安全生产责任制考核办法》"}, {"seq": 11, "point": "过程管理\n(3.1.4)", "content": "网格员按规定频次开展日常巡查，发现隐患及时登记、上报、整改、验收", "basis": "《安全生产事故隐患排查治理暂行规定》"}, {"seq": 12, "point": "过程管理\n(3.1.4)", "content": "建立隐患排查治理台账，实行「清单式」管理，做到整改责任、措施、时限、资金、预案「五落实」", "basis": "隐患排查治理体系建设要求"}, {"seq": 13, "point": "过程管理\n(3.1.4)", "content": "上级对下级网格管理工作进行定期检查督导，通报问题并督促整改", "basis": "企业层级管理制度"}, {"seq": 14, "point": "过程管理\n(3.1.4)", "content": "实行网格化管理绩效考核，将考核结果与奖惩、评优挂钩", "basis": "企业绩效考核办法"}, {"seq": 15, "point": "培训考核\n(3.1.5)", "content": "制定网格人员年度培训计划，内容涵盖法律法规、风险辨识、应急处置等", "basis": "《生产经营单位安全培训规定》"}, {"seq": 16, "point": "培训考核\n(3.1.5)", "content": "新上岗网格人员须经岗前培训并考核合格，老员工每年进行再培训", "basis": "企业安全培训制度"}, {"seq": 17, "point": "培训考核\n(3.1.5)", "content": "定期组织网格化管理业务考核，检验网格员履职能力", "basis": "企业网格化考核管理办法"}, {"seq": 18, "point": "信息化运用\n(3.1.6)", "content": "运用信息化手段（APP/系统平台）开展网格巡查、隐患上报、整改跟踪", "basis": "智慧工地建设相关要求"}, {"seq": 19, "point": "信息化运用\n(3.1.6)", "content": "建立网格化管理数据库，实现数据统计、分析和预警功能", "basis": "安全生产信息化建设指南"}, {"seq": 20, "point": "信息化运用\n(3.1.6)", "content": "信息化平台应覆盖所有网格区域，确保信息报送及时准确", "basis": "企业信息化管理制度"}]}, {"name": "3.2 高处作业管理", "items": [{"seq": 1, "point": "方案化\n(3.2.1)", "content": "高处作业（≥2m）必须编制专项施工方案，经审批后实施；超过一定规模的须专家论证", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 2, "point": "方案化\n(3.2.1)", "content": "专项方案应包含危险源辨识、安全技术措施、防护设施设计、应急预案等内容", "basis": "《危险性较大的分部分项工程安全管理规定》"}, {"seq": 3, "point": "方案化\n(3.2.1)", "content": "施工前进行方案技术交底，交底到一线作业人员并签字确认", "basis": "《建设工程安全生产管理条例》"}, {"seq": 4, "point": "方案化\n(3.2.1)", "content": "方案实施过程中发生工况变化应及时修订并重新审批", "basis": "施工方案动态管理要求"}, {"seq": 5, "point": "安全带/网标准化\n(3.2.2)", "content": "安全带必须符合GB 6095标准，在使用有效期内，外观无破损、配件齐全", "basis": "《安全带》(GB 6095)；《安全带测试方法》(GB 6096)"}, {"seq": 6, "point": "安全带/网标准化\n(3.2.2)", "content": "安全网（平网、立网、密目网）符合GB 5725标准，设置规范、无破损", "basis": "《安全网》(GB 5725)"}, {"seq": 7, "point": "安全带/网标准化\n(3.2.2)", "content": "安全带应「高挂低用」，挂点牢固可靠；安全网张挂平整、接缝严密", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 8, "point": "安全带/网标准化\n(3.2.2)", "content": "安全防护用品建立采购、验收、发放、报废台账", "basis": "企业劳保用品管理制度"}, {"seq": 9, "point": "防护设施\n(3.2.3)", "content": "临边、洞口、攀登、悬空等高处作业区域必须设置防护栏杆、挡脚板等防护设施", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 10, "point": "防护设施\n(3.2.3)", "content": "防护栏杆材料、结构、承载力满足规范要求，不得随意拆除", "basis": "《建筑施工安全检查标准》(JGJ 59)"}, {"seq": 11, "point": "防护设施\n(3.2.3)", "content": "洞口防护（短边≥25cm）采用盖板或防护栏杆封闭，悬挂警示标识", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 12, "point": "防护设施\n(3.2.3)", "content": "攀登作业梯子、操作平台等符合安全要求，使用前进行检查", "basis": "《移动式梯子安全技术要求》"}, {"seq": 13, "point": "临时设施检查\n(3.2.4)", "content": "脚手架、吊篮、升降平台等临时设施搭设后须经验收合格方可使用", "basis": "《建筑施工扣件式钢管脚手架安全技术规范》(JGJ 130)"}, {"seq": 14, "point": "临时设施检查\n(3.2.4)", "content": "临时设施在使用过程中定期检查维护，恶劣天气后须全面检查", "basis": "《建筑施工安全检查标准》(JGJ 59)"}, {"seq": 15, "point": "临时设施检查\n(3.2.4)", "content": "临时设施的拆除须有方案、有监护，按顺序拆除", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 16, "point": "人员准入\n(3.2.5)", "content": "高处作业人员须年满18周岁，体检合格（无高血压、心脏病、恐高症等禁忌症）", "basis": "《特种作业人员安全技术培训考核管理规定》"}, {"seq": 17, "point": "人员准入\n(3.2.5)", "content": "高处作业人员须持有效特种作业操作证上岗（登高架设作业等）", "basis": "《特种作业人员安全技术培训考核管理规定》"}, {"seq": 18, "point": "人员准入\n(3.2.5)", "content": "新入场高处作业人员须经三级安全教育和专项培训合格", "basis": "《生产经营单位安全培训规定》"}, {"seq": 19, "point": "现场管理\n(3.2.6)", "content": "高处作业现场设置警戒区域和警示标识，严禁无关人员进入", "basis": "《安全标志及其使用导则》(GB 2894)"}, {"seq": 20, "point": "现场管理\n(3.2.6)", "content": "严禁在六级及以上大风、暴雨、雷电等恶劣天气进行露天高处作业", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 21, "point": "现场管理\n(3.2.6)", "content": "高处作业物料堆放稳固，工具放入工具袋，严禁上下抛掷", "basis": "《建筑施工安全检查标准》(JGJ 59)"}, {"seq": 22, "point": "现场管理\n(3.2.6)", "content": "交叉作业时设置隔离防护，上下层作业错开或采取可靠防护", "basis": "《建筑施工高处作业安全技术规范》(JGJ 80)"}, {"seq": 23, "point": "信息化监控\n(3.2.7)", "content": "关键高处作业区域安装视频监控，实现远程实时巡查", "basis": "智慧工地建设要求"}, {"seq": 24, "point": "信息化监控\n(3.2.7)", "content": "运用物联网技术（如安全带智能锁扣、安全网张力传感器等）对防护设施状态进行监测", "basis": "安全生产科技创新相关文件"}, {"seq": 25, "point": "信息化监控\n(3.2.7)", "content": "建立高处作业人员的信息化管理系统（人员资质、培训、违章记录等）", "basis": "企业人员信息化管理要求"}]}, {"name": "3.3 汛期管理", "items": [{"seq": 1, "point": "责任落实\n(3.3.1)", "content": "成立汛期安全生产领导小组，明确第一责任人和各级防汛职责", "basis": "《防汛条例》；《安全生产法》"}, {"seq": 2, "point": "责任落实\n(3.3.1)", "content": "制定汛期安全生产工作方案，明确防汛目标、措施和保障", "basis": "交通运输部汛期安全生产工作通知"}, {"seq": 3, "point": "责任落实\n(3.3.1)", "content": "落实汛期24小时值班制度和领导带班制度", "basis": "《防汛值班制度》"}, {"seq": 4, "point": "责任落实\n(3.3.1)", "content": "签订防汛安全责任书，层层传导压力", "basis": "企业安全生产责任制管理要求"}, {"seq": 5, "point": "本质安全·风险排查评估\n(3.3.2)", "content": "开展汛前安全风险全面排查，重点排查地质灾害隐患点、低洼地带、临水临崖区域", "basis": "《地质灾害防治条例》；汛前安全检查要求"}, {"seq": 6, "point": "本质安全·风险排查评估\n(3.3.2)", "content": "对排查出的风险进行评估分级（红/橙/黄/蓝），制定分级管控措施", "basis": "风险分级管控和隐患排查治理双重预防机制"}, {"seq": 7, "point": "本质安全·风险排查评估\n(3.3.2)", "content": "建立风险动态更新机制，汛期每半月进行一次风险复核", "basis": "风险动态管理制度"}, {"seq": 8, "point": "本质安全·风险排查评估\n(3.3.2)", "content": "建立隐患排查治理台账，重大隐患挂牌督办，限期整改", "basis": "《安全生产事故隐患排查治理暂行规定》"}, {"seq": 9, "point": "本质安全·安全屋建设\n(3.3.3)", "content": "在施工区域合理设置防汛安全屋（紧急避险点），配备应急物资", "basis": "防汛应急预案编制要求"}, {"seq": 10, "point": "本质安全·安全屋建设\n(3.3.3)", "content": "安全屋内配备应急照明、通信设备、饮用水、食品、医疗急救包等", "basis": "应急物资储备标准"}, {"seq": 11, "point": "本质安全·安全屋建设\n(3.3.3)", "content": "安全屋标识清晰，疏散路线图张贴醒目，定期组织避险演练", "basis": "应急管理相关要求"}, {"seq": 12, "point": "监测预警\n(3.3.4)", "content": "建立与气象、水文、自然资源等部门的联动机制，及时获取预警信息", "basis": "《突发事件应对法》；部门联动机制要求"}, {"seq": 13, "point": "监测预警\n(3.3.4)", "content": "设置现场雨量监测、水位监测等设备，实时掌握现场气象水文数据", "basis": "防汛监测技术要求"}, {"seq": 14, "point": "监测预警\n(3.3.4)", "content": "明确预警等级及对应响应措施，预警信息及时传递到一线班组", "basis": "《气象灾害预警信号发布与传播办法》"}, {"seq": 15, "point": "监测预警\n(3.3.4)", "content": "汛期建立每日安全巡查和「零报告」制度", "basis": "汛期安全管理制度"}, {"seq": 16, "point": "应急处置\n(3.3.5)", "content": "编制防汛应急预案并按规定报备，预案内容应包括组织指挥、响应程序、处置措施等", "basis": "《生产安全事故应急预案管理办法》"}, {"seq": 17, "point": "应急处置\n(3.3.5)", "content": "组建应急抢险队伍，明确人员名单、职责和联系方式", "basis": "应急队伍建设要求"}, {"seq": 18, "point": "应急处置\n(3.3.5)", "content": "储备防汛应急物资（沙袋、水泵、发电机、救生衣等），数量充足、存放到位", "basis": "《防汛物资储备定额》"}, {"seq": 19, "point": "应急处置\n(3.3.5)", "content": "每汛期至少组织一次防汛应急演练，检验预案可行性和队伍响应能力", "basis": "《生产安全事故应急预案管理办法》"}, {"seq": 20, "point": "应急处置\n(3.3.5)", "content": "汛期发生险情时立即启动应急响应，按规定上报，科学处置", "basis": "《生产安全事故报告和调查处理条例》"}]}]}, {"id": "spot_check", "title": "抽检篇", "category": "抽检篇", "sheets": [{"name": "第1章 抽检工作", "items": [{"seq": 1, "point": "基本要求", "content": "抽检工作应遵循「依法依规、科学公正、程序规范、注重实效」的原则", "basis": "《建设工程质量管理条例》"}, {"seq": 2, "point": "基本要求", "content": "建设单位应建立健全抽检工作制度，明确抽检组织机构、职责分工和工作流程", "basis": "《建设工程质量检测管理办法》"}, {"seq": 3, "point": "基本要求", "content": "抽检工作的抽样比例、检测频次应符合设计及规范要求，不得随意降低标准", "basis": "设计文件及施工质量验收规范"}, {"seq": 4, "point": "基本要求", "content": "抽检人员应具备相应资质和能力，检测设备应定期检定/校准并在有效期内", "basis": "《检验检测机构资质认定管理办法》"}, {"seq": 5, "point": "基本要求", "content": "抽检工作全过程应如实记录，形成可追溯的质量记录，严禁弄虚作假", "basis": "《建设工程质量管理条例》"}, {"seq": 6, "point": "准备工作\n(收集资料)", "content": "收集工程概况、设计图纸、施工组织设计、相关规范标准等技术资料", "basis": "《建设工程质量检测管理办法》"}, {"seq": 7, "point": "准备工作\n(收集资料)", "content": "收集施工单位、监理单位、检测单位等参建各方资质及人员资格信息", "basis": "建设主管部门资质管理要求"}, {"seq": 8, "point": "准备工作\n(编制计划)", "content": "根据工程特点和规范要求，编制抽检工作计划，明确检测项目、频次、方法", "basis": "项目质量监督工作计划编制要求"}, {"seq": 9, "point": "准备工作\n(编制计划)", "content": "抽检计划应涵盖实体质量和原材料两大类，明确各检测指标的抽检比例", "basis": "《建筑工程施工质量验收统一标准》(GB 50300)"}, {"seq": 10, "point": "准备工作\n(仪器设备)", "content": "检测仪器设备准备：确认设备状态、检定有效期、配件齐全，现场适用", "basis": "《检测和校准实验室能力认可准则》(CNAS-CL01)"}, {"seq": 11, "point": "实体抽检\n(路基)", "content": "路基工程：抽检压实度、弯沉值、平整度、边坡坡度等关键指标", "basis": "《公路路基施工技术规范》(JTG/T 3610)"}, {"seq": 12, "point": "实体抽检\n(路面)", "content": "路面工程：抽检厚度、压实度、平整度、抗滑性能、渗水系数等", "basis": "《公路路面基层施工技术细则》(JTG/T F20)"}, {"seq": 13, "point": "实体抽检\n(桥梁下部)", "content": "桥梁工程-下部结构：抽检桩基完整性、墩柱混凝土强度、钢筋保护层厚度", "basis": "《公路桥涵施工技术规范》(JTG/T 3650)"}, {"seq": 14, "point": "实体抽检\n(桥梁上部)", "content": "桥梁工程-上部结构：抽检梁板混凝土强度、预应力张拉、支座安装质量", "basis": "《公路桥涵施工技术规范》(JTG/T 3650)"}, {"seq": 15, "point": "实体抽检\n(隧道)", "content": "隧道工程：抽检初支厚度、二衬厚度、空洞、混凝土强度、锚杆拉拔力", "basis": "《公路隧道施工技术规范》(JTG/T 3660)"}, {"seq": 16, "point": "实体抽检\n(交安设施)", "content": "交安设施：抽检标志板反光系数、标线厚度/逆反射系数、护栏高度/中心高度", "basis": "《公路交通安全设施施工技术规范》(JTG/T 3671)"}, {"seq": 17, "point": "实体抽检\n(机电)", "content": "机电工程：抽检照明照度/均匀度、通风风速、消防系统功能等", "basis": "《公路隧道照明设计细则》《公路隧道通风设计细则》"}, {"seq": 18, "point": "实体抽检\n(抽样方法)", "content": "实体抽检应覆盖关键工序和重要部位，采用随机抽样与重点抽检相结合", "basis": "《公路工程质量检验评定标准》(JTG F80/1)"}, {"seq": 19, "point": "实体抽检\n(记录要求)", "content": "实体抽检应现场即时完成初步记录，数据不得事后补记或涂改", "basis": "《检验检测机构监督管理办法》"}, {"seq": 20, "point": "原材料抽检\n(粗集料)", "content": "粗集料：抽检压碎值、针片状含量、含泥量、级配、坚固性等", "basis": "《公路工程集料试验规程》(JTG E42)"}, {"seq": 21, "point": "原材料抽检\n(细集料)", "content": "细集料：抽检含泥量、泥块含量、级配、细度模数、云母含量等", "basis": "《公路工程集料试验规程》(JTG E42)"}, {"seq": 22, "point": "原材料抽检\n(沥青)", "content": "沥青：抽检针入度、软化点、延度、蜡含量、老化后指标等", "basis": "《公路工程沥青及沥青混合料试验规程》(JTG E20)"}, {"seq": 23, "point": "原材料抽检\n(水泥)", "content": "水泥：抽检强度、安定性、凝结时间、比表面积、标准稠度用水量", "basis": "《通用硅酸盐水泥》(GB 175)"}, {"seq": 24, "point": "原材料抽检\n(钢筋/钢绞线)", "content": "钢筋/钢绞线：抽检屈服强度、抗拉强度、伸长率、冷弯性能、重量偏差", "basis": "《钢筋混凝土用钢》(GB/T 1499)；《预应力混凝土用钢绞线》(GB/T 5224)"}, {"seq": 25, "point": "原材料抽检\n(波纹管/锚具/支座)", "content": "波纹管/锚具/支座：抽检外观质量、尺寸偏差、力学性能（锚固效率系数等）", "basis": "《预应力混凝土用波纹管》等产品标准"}, {"seq": 26, "point": "原材料抽检\n(外加剂)", "content": "外加剂/添加剂：抽检减水率、凝结时间差、抗压强度比、含气量等", "basis": "《混凝土外加剂》(GB 8076)"}, {"seq": 27, "point": "原材料抽检\n(防水/土工材料)", "content": "防水材料/土工材料：抽检拉伸强度、断裂伸长率、撕裂强度、渗透系数等", "basis": "《高分子防水材料》《土工合成材料》等标准"}, {"seq": 28, "point": "过程管理\n(不合格处理)", "content": "抽检过程中发现不合格项，应按程序及时通知相关单位，并做好不合格标识", "basis": "《建设工程质量检测管理办法》"}, {"seq": 29, "point": "过程管理\n(整改复检)", "content": "不合格项须进行原因分析，制定整改方案，整改后重新抽检合格方可通过", "basis": "《工程质量问题处理管理办法》"}, {"seq": 30, "point": "过程管理\n(数据录入)", "content": "抽检数据和结果应及时录入信息系统，确保数据可追溯、可分析", "basis": "工程质量检测信息化管理要求"}, {"seq": 31, "point": "过程管理\n(汇总报告)", "content": "定期汇总抽检结果，编制抽检工作报告，分析质量趋势和突出问题", "basis": "项目质量报告编制要求"}, {"seq": 32, "point": "过程管理\n(见证监督)", "content": "抽检过程应接受建设单位、监理单位的监督见证，必要时邀请第三方参与", "basis": "《建设工程质量检测管理办法》"}, {"seq": 33, "point": "结果应用\n(反馈)", "content": "抽检结果应及时反馈至施工、监理单位，并作为质量改进的依据", "basis": "《建设工程质量管理条例》"}, {"seq": 34, "point": "结果应用\n(通报)", "content": "抽检结果应在工程质量例会上通报，重要问题专题研究", "basis": "项目质量例会制度"}, {"seq": 35, "point": "结果应用\n(档案)", "content": "抽检原始记录、检测报告、整改记录等档案资料归档保存，保存期不少于工程使用年限", "basis": "《建设工程文件归档规范》(GB/T 50328)"}, {"seq": 36, "point": "结果应用\n(追责)", "content": "对抽检中发现的质量问题，应追究相关责任单位和责任人的责任", "basis": "《建设工程质量管理条例》"}, {"seq": 37, "point": "结果应用\n(信用评价)", "content": "抽检结果作为工程质量评定、竣工验收和信用评价的重要依据之一", "basis": "《建筑业企业信用评价标准》"}]}, {"name": "第2章 主要检测指标及统计方式", "items": [{"seq": 1, "point": "路基压实度", "content": "", "basis": "≥设计值(一般≥93%/94%/96%按部位)"}, {"seq": 2, "point": "路基弯沉值", "content": "", "basis": "≤设计弯沉值"}, {"seq": 3, "point": "路基平整度", "content": "", "basis": "≤设计值(一般≤15mm或≤12mm)"}, {"seq": 4, "point": "路基边坡坡度", "content": "", "basis": "≤设计坡度±0.5%"}, {"seq": 5, "point": "路基宽度", "content": "", "basis": "≥设计宽度；偏差≤+50mm"}, {"seq": 6, "point": "路基中线偏位", "content": "", "basis": "≤50mm"}, {"seq": 7, "point": "路基纵断面高程", "content": "", "basis": "偏差≤+10/-20mm"}, {"seq": 8, "point": "路基横坡", "content": "", "basis": "偏差≤±0.5%"}, {"seq": 9, "point": "路堤填筑层厚", "content": "", "basis": "≤设计层厚+20mm"}, {"seq": 10, "point": "台背回填压实度", "content": "", "basis": "≥96%"}, {"seq": 11, "point": "软基处理-复合地基承载力", "content": "", "basis": "≥设计承载力特征值"}, {"seq": 12, "point": "软基处理-桩体完整性", "content": "", "basis": "Ⅰ类桩≥95%；无Ⅲ/Ⅳ类桩"}, {"seq": 13, "point": "排水设施断面尺寸", "content": "", "basis": "偏差≤±30mm"}, {"seq": 14, "point": "防护工程砂浆/混凝土强度", "content": "", "basis": "≥设计强度等级"}, {"seq": 15, "point": "土工合成材料搭接宽度", "content": "", "basis": "≥设计搭接宽度-20mm"}, {"seq": 16, "point": "路基CBR值", "content": "", "basis": "≥设计CBR值"}, {"seq": 17, "point": "路基回弹模量", "content": "", "basis": "≥设计回弹模量"}, {"seq": 18, "point": "换填深度", "content": "", "basis": "≥设计换填深度"}, {"seq": 19, "point": "加筋材料间距", "content": "", "basis": "偏差≤±50mm"}, {"seq": 20, "point": "排水垫层厚度", "content": "", "basis": "偏差≤±10%设计厚度"}, {"seq": 21, "point": "路面面层厚度", "content": "", "basis": "偏差：高速/一级≤-10%H，其他≤-12%H"}, {"seq": 22, "point": "路面基层/底基层厚度", "content": "", "basis": "偏差≤设计厚度-10mm(基层)/≤-12mm(底基层)"}, {"seq": 23, "point": "路面面层压实度", "content": "", "basis": "≥96%（SMA≥97%）"}, {"seq": 24, "point": "路面基层压实度", "content": "", "basis": "≥98%（基层）/≥97%（底基层）"}, {"seq": 25, "point": "路面平整度", "content": "", "basis": "IRI≤2.0m/km(高速)/≤2.5m/km(一级)"}, {"seq": 26, "point": "路面抗滑性能(摆值/构造深度)", "content": "", "basis": "BPN≥45(高速)；TD≥0.55mm"}, {"seq": 27, "point": "路面渗水系数", "content": "", "basis": "≤120mL/min(SMA≤80mL/min)"}, {"seq": 28, "point": "路面弯沉值", "content": "", "basis": "≤竣工验收弯沉值"}, {"seq": 29, "point": "路面横坡", "content": "", "basis": "偏差≤±0.3%"}, {"seq": 30, "point": "路面宽度", "content": "", "basis": "≥设计宽度；偏差≤+20mm"}, {"seq": 31, "point": "沥青含量/油石比", "content": "", "basis": "偏差≤±0.3%"}, {"seq": 32, "point": "矿料级配", "content": "", "basis": "关键筛孔通过率偏差≤±5%"}, {"seq": 33, "point": "沥青混合料稳定度/流值", "content": "", "basis": "稳定度≥设计值；流值在范围内"}, {"seq": 34, "point": "水泥稳定料水泥剂量", "content": "", "basis": "偏差≤设计剂量±0.5%"}, {"seq": 35, "point": "水泥稳定料含水率", "content": "", "basis": "偏差≤最佳含水率±1%"}, {"seq": 36, "point": "沥青层间粘结强度", "content": "", "basis": "≥设计粘结强度值"}, {"seq": 37, "point": "路面高程", "content": "", "basis": "偏差≤+10/-15mm"}, {"seq": 38, "point": "路面接缝高差", "content": "", "basis": "≤3mm"}, {"seq": 39, "point": "碎石垫层级配", "content": "", "basis": "符合设计级配范围"}, {"seq": 40, "point": "透层/粘层/封层洒布量", "content": "", "basis": "偏差≤设计洒布量±10%"}, {"seq": 41, "point": "混凝土抗压强度", "content": "", "basis": "≥设计强度等级"}, {"seq": 42, "point": "钢筋保护层厚度", "content": "", "basis": "合格率≥90%；偏差≤+10/-5mm(板)/+12/-5mm(梁)"}, {"seq": 43, "point": "桩基完整性", "content": "", "basis": "Ⅰ类桩≥95%；无Ⅲ/Ⅳ类桩"}, {"seq": 44, "point": "桩基承载力", "content": "", "basis": "≥设计承载力特征值"}, {"seq": 45, "point": "桩基沉渣厚度", "content": "", "basis": "≤50mm(摩擦桩)/≤30mm(端承桩)"}, {"seq": 46, "point": "墩柱垂直度", "content": "", "basis": "偏差≤H/1000且≤30mm"}, {"seq": 47, "point": "墩柱断面尺寸", "content": "", "basis": "偏差≤±10mm"}, {"seq": 48, "point": "盖梁/台帽混凝土强度", "content": "", "basis": "≥设计强度等级"}, {"seq": 49, "point": "支座安装位置偏差", "content": "", "basis": "偏差≤±5mm(顺桥向)/≤±10mm(横桥向)"}, {"seq": 50, "point": "支座安装高程偏差", "content": "", "basis": "偏差≤±5mm"}, {"seq": 51, "point": "预应力张拉控制应力", "content": "", "basis": "偏差≤±6%张拉控制应力"}, {"seq": 52, "point": "预应力孔道压浆密实度", "content": "", "basis": "密实度≥95%"}, {"seq": 53, "point": "钢构件焊缝质量", "content": "", "basis": "符合设计焊缝质量等级"}, {"seq": 54, "point": "钢构件涂层厚度", "content": "", "basis": "≥设计涂层厚度"}, {"seq": 55, "point": "伸缩缝安装宽度/高差", "content": "", "basis": "宽度偏差≤±10mm；高差≤2mm"}, {"seq": 56, "point": "桥梁整体线形/高程", "content": "", "basis": "偏差在设计允许范围内"}, {"seq": 57, "point": "箱梁/空心板内模尺寸", "content": "", "basis": "偏差≤±5mm"}, {"seq": 58, "point": "桥梁荷载试验-静载", "content": "", "basis": "校验系数≤1.0；残余变形≤20%"}, {"seq": 59, "point": "桥梁荷载试验-动载", "content": "", "basis": "实测频率≥理论频率；阻尼比正常"}, {"seq": 60, "point": "锚具硬度", "content": "", "basis": "符合产品标准要求"}, {"seq": 61, "point": "钢绞线松弛率", "content": "", "basis": "≤2.5%(1000h)"}, {"seq": 62, "point": "桥梁支座力学性能", "content": "", "basis": "承载力、位移、转角满足设计要求"}, {"seq": 63, "point": "初期支护厚度", "content": "", "basis": "≥设计厚度；平均厚度≥设计值"}, {"seq": 64, "point": "二次衬砌厚度", "content": "", "basis": "≥设计厚度；无小于设计值1/2的点"}, {"seq": 65, "point": "衬砌背后空洞", "content": "", "basis": "无空洞缺陷或空洞面积≤允许值"}, {"seq": 66, "point": "衬砌混凝土强度", "content": "", "basis": "≥设计强度等级"}, {"seq": 67, "point": "锚杆拉拔力", "content": "", "basis": "≥设计拉拔力；单根≥90%设计值"}, {"seq": 68, "point": "锚杆长度/数量", "content": "", "basis": "长度≥设计值-50mm；数量符合设计"}, {"seq": 69, "point": "钢拱架间距", "content": "", "basis": "偏差≤±50mm"}, {"seq": 70, "point": "钢筋网间距", "content": "", "basis": "偏差≤±10mm"}, {"seq": 71, "point": "喷射混凝土强度", "content": "", "basis": "≥设计强度等级"}, {"seq": 72, "point": "喷射混凝土平整度", "content": "", "basis": "矢高≤50mm"}, {"seq": 73, "point": "防水板搭接宽度", "content": "", "basis": "≥100mm；偏差≤-10mm"}, {"seq": 74, "point": "防水板焊缝质量", "content": "", "basis": "无漏焊、虚焊；气密性合格"}, {"seq": 75, "point": "隧道净空断面尺寸", "content": "", "basis": "偏差≤±30mm；无侵限"}, {"seq": 76, "point": "仰拱厚度/强度", "content": "", "basis": "厚度≥设计值；强度≥设计等级"}, {"seq": 77, "point": "隧道排水系统通畅性", "content": "", "basis": "排水通畅、无堵塞"}, {"seq": 78, "point": "隧道照明亮度", "content": "", "basis": "≥设计照度值"}, {"seq": 79, "point": "隧道通风风速", "content": "", "basis": "≥设计风速值"}, {"seq": 80, "point": "超前支护小导管/管棚质量", "content": "", "basis": "长度、数量、注浆符合设计要求"}, {"seq": 81, "point": "标志板反光膜逆反射系数", "content": "", "basis": "≥标准规定值(根据反光膜等级)"}, {"seq": 82, "point": "标志板基础尺寸", "content": "", "basis": "偏差≤±30mm"}, {"seq": 83, "point": "标线厚度", "content": "", "basis": "≥设计厚度(热熔型≥1.8mm)"}, {"seq": 84, "point": "标线逆反射系数", "content": "", "basis": "≥标准规定值(一般≥150mcd)"}, {"seq": 85, "point": "波形梁护栏高度/中心高度", "content": "", "basis": "偏差≤±20mm(高度)/≤±10mm(中心)"}, {"seq": 86, "point": "波形梁护栏立柱埋深", "content": "", "basis": "≥设计埋深"}, {"seq": 87, "point": "波形梁板厚度/镀锌层厚度", "content": "", "basis": "板厚≥设计值；镀锌层≥标准值"}, {"seq": 88, "point": "隔离栅高度/网孔尺寸", "content": "", "basis": "偏差≤±15mm(高度)/≤±5mm(网孔)"}, {"seq": 89, "point": "防眩板安装高度/间距", "content": "", "basis": "偏差≤±10mm(高度)/≤±20mm(间距)"}, {"seq": 90, "point": "轮廓标安装位置/逆反射性能", "content": "", "basis": "安装牢固高度正确；逆反射合格"}, {"seq": 91, "point": "粗集料-压碎值", "content": "", "basis": "≤设计值(一般≤26%~30%按等级)"}, {"seq": 92, "point": "粗集料-针片状含量", "content": "", "basis": "≤15%(高速/一级)或≤20%"}, {"seq": 93, "point": "粗集料-含泥量", "content": "", "basis": "≤1%(C60)/≤2%(C30~C55)/≤3%"}, {"seq": 94, "point": "粗集料-级配", "content": "", "basis": "符合设计级配范围"}, {"seq": 95, "point": "粗集料-坚固性", "content": "", "basis": "≤12%(混凝土)/≤5%(沥青面层)"}, {"seq": 96, "point": "细集料-含泥量", "content": "", "basis": "≤3%(C30及以上≤2%)"}, {"seq": 97, "point": "细集料-泥块含量", "content": "", "basis": "≤1%(C30及以上≤0.5%)"}, {"seq": 98, "point": "细集料-细度模数", "content": "", "basis": "中砂2.3~3.0(或设计要求)"}, {"seq": 99, "point": "细集料-云母含量", "content": "", "basis": "≤2%"}, {"seq": 100, "point": "沥青-针入度(25℃)", "content": "", "basis": "符合设计标号要求(如60~80)"}, {"seq": 101, "point": "沥青-软化点", "content": "", "basis": "≥设计值(一般≥43~46℃按标号)"}, {"seq": 102, "point": "沥青-延度(15℃/10℃)", "content": "", "basis": "≥设计值(一般≥100cm)"}, {"seq": 103, "point": "沥青-老化后质量变化", "content": "", "basis": "≤±1.0%(RTFOT)"}, {"seq": 104, "point": "水泥-抗压强度(3d/28d)", "content": "", "basis": "≥设计强度等级(如42.5/52.5)"}, {"seq": 105, "point": "水泥-安定性(雷氏夹/试饼法)", "content": "", "basis": "雷氏夹膨胀≤5mm；试饼无开裂翘曲"}, {"seq": 106, "point": "水泥-凝结时间", "content": "", "basis": "初凝≥45min；终凝≤600min"}, {"seq": 107, "point": "水泥-比表面积", "content": "", "basis": "≥300m²/kg且≤400m²/kg"}, {"seq": 108, "point": "钢筋-屈服强度/抗拉强度/伸长率", "content": "", "basis": "≥标准规定值(如400/500MPa级)；强屈比≥1.25；超屈比≤1.30"}]}, {"name": "第3章 双随机抽检操作规程", "items": [{"seq": 1, "point": "适用范围定义", "content": "本规程适用于公路水运建设工程质量双随机抽检工作", "basis": "《关于推广随机抽查规范事中事后监管的通知》"}, {"seq": 2, "point": "适用范围定义", "content": "「双随机」是指随机抽取检查对象、随机选派抽检人员", "basis": "《建设工程质量检测管理办法》"}, {"seq": 3, "point": "适用范围定义", "content": "质量抽检对象包括：在建项目实体质量、原材料及中间产品质量、参建单位质量行为", "basis": "《公路工程质量监督规定》"}, {"seq": 4, "point": "适用范围定义", "content": "下列情形不适用双随机抽检：事故调查、举报核查、专项质量评估等须定向检查的情形", "basis": "双随机抽查工作实施细则"}, {"seq": 5, "point": "准备工作", "content": "建立检查对象名录库：涵盖所有在建标段、主要结构部位、主要原材料及中间产品类别", "basis": "双随机抽检工作规范"}, {"seq": 6, "point": "准备工作", "content": "建立抽检人员名录库：包括检测技术人员、专家和监督管理人员", "basis": "《检验检测机构资质认定管理办法》"}, {"seq": 7, "point": "准备工作", "content": "制定双随机抽检实施细则，明确随机抽取方法、程序和规则", "basis": "双随机抽查工作实施细则"}, {"seq": 8, "point": "准备工作", "content": "准备随机抽检工具：随机数生成器/摇号软件、抽检记录表单、检测仪器设备", "basis": "双随机抽检操作指南"}, {"seq": 9, "point": "抽取流程", "content": "制定当次抽检方案：确定抽检类别、范围和比例，报批后执行", "basis": "双随机抽检工作程序"}, {"seq": 10, "point": "抽取流程", "content": "从检查对象名录库中通过随机方式（摇号/随机数）抽取被检对象", "basis": "双随机抽检操作规范"}, {"seq": 11, "point": "抽取流程", "content": "从抽检人员名录库中随机选派本次抽检执行人员", "basis": "《检验检测机构资质认定管理办法》"}, {"seq": 12, "point": "抽取流程", "content": "抽检对象和人员确定后，在规定时限内（一般不超过3个工作日）通知相关单位", "basis": "双随机抽检工作程序"}, {"seq": 13, "point": "抽取流程", "content": "因特殊情况需变更抽检对象或人员的，须经审批并记录原因", "basis": "双随机抽检实施细则"}, {"seq": 14, "point": "抽取流程", "content": "建立双随机抽检台帐，记录每次抽检的抽取过程、抽检结果和处理情况", "basis": "《建设工程质量检测管理办法》"}, {"seq": 15, "point": "随机抽样程序", "content": "现场抽样前出示工作证件和抽检通知书，告知被检单位权利和义务", "basis": "《行政处罚法》《建设工程质量检测管理办法》"}, {"seq": 16, "point": "随机抽样程序", "content": "按照预先确定的抽样方法（随机数表/坐标法/分层抽样等）确定具体抽样点位", "basis": "《公路工程现场检测技术规程》"}, {"seq": 17, "point": "随机抽样程序", "content": "取样、制样、封样过程应有被检单位代表在场见证并签字确认", "basis": "《建设工程质量检测管理办法》"}, {"seq": 18, "point": "随机抽样程序", "content": "样品在运输和保管过程中应保持标识清晰、状态不变，确保可追溯性", "basis": "《检测和校准实验室能力认可准则》(CNAS-CL01)"}, {"seq": 19, "point": "随机抽样程序", "content": "检测完成后及时出具检测报告，报告格式规范、结论明确、签字盖章齐全", "basis": "《检验检测机构监督管理办法》"}, {"seq": 20, "point": "管理台账模板说明", "content": "管理台账模板应包括以下要素：台账编号、抽检日期、检查对象名称与类别、抽检人员姓名及证号、抽样方法、检测项目、检测结果、处理意见、整改跟踪情况", "basis": "双随机抽检管理制度"}, {"seq": 21, "point": "管理台账模板说明", "content": "管理台账应按年度或项目归档，电子台账和纸质台账同步保存", "basis": "《建设工程文件归档规范》(GB/T 50328)"}, {"seq": 22, "point": "管理台账模板说明", "content": "管理台账应定期汇总分析，形成季度/年度双随机抽检工作报告", "basis": "质量监督工作报告制度"}]}]}]};